#[test]
fn renderer_preview_carries_rainbow_variant_identity_from_config() {
    use crate::settings_preview::PreviewTrailCompanion;
    use aterm_effects::kitty_pet::PetSpecies;

    let motion = crate::native_app::ViewMotionCx::default();
    for (raw, expected) in [
        (
            "rainbow kitty underline",
            PreviewTrailCompanion::Pet(PetSpecies::Cat),
        ),
        (
            "rainbow kitty tall",
            PreviewTrailCompanion::Pet(PetSpecies::Cat),
        ),
        (
            "rainbow kitty pet",
            PreviewTrailCompanion::Pet(PetSpecies::Cat),
        ),
        (
            "rainbow dog pet",
            PreviewTrailCompanion::Pet(PetSpecies::Dog),
        ),
        ("rainbow kitty flying", PreviewTrailCompanion::FlyingKitty),
    ] {
        let config: Config = aterm_toml::from_str(&format!(
            "cursor_trail = true\ncursor_trail_style = {raw:?}\n"
        ))
        .unwrap();
        let mut state = SettingsViewState::new(&config);
        state.navigate(SettingsRoute::CursorMotion);
        let preview = renderer_preview_spec(&state, 900, motion, 13.0, 1.0)
            .unwrap_or_else(|| panic!("preview for {raw}"));

        assert_eq!(preview.cursor.trail_style, PreviewTrailStyle::RainbowKitty);
        assert_eq!(
            preview.cursor.effective_trail_style_raw(),
            prefs::cursor_trail_style_canonical(raw).unwrap()
        );
        assert_eq!(preview.cursor.trail_companion(), expected, "{raw}");
    }
}

#[test]
fn preview_activity_comes_from_the_exact_authored_spec() {
    let mut home = SettingsViewState::new(&Config {
        cursor_trail: Some(true),
        ..Config::default()
    });
    let motion = crate::native_app::ViewMotionCx::default();
    assert_eq!(
        home.preview_animation(
            100,
            motion,
            13.0,
            1.0,
            LogicalRect::new(0.0, 0.0, 1_200.0, 720.0),
        ),
        PreviewAnimation::Continuous,
        "wide Top Settings animates its visible cursor runway without requiring focus"
    );
    assert_eq!(
        home.preview_animation(
            100,
            motion,
            13.0,
            1.0,
            LogicalRect::new(0.0, 0.0, 390.0, 568.0),
        ),
        PreviewAnimation::None,
        "compact Top Settings page 0 renders only a static theme sample"
    );
    home.page_reveal = Some(UiKey::new(format!(
        "settings/control/{}",
        prefs::EDIT_CURSOR_TRAIL_STYLE
    )));
    let _ = settings_route_at(&home, &view_cx_at(390.0, 568.0));
    assert_eq!(
        home.preview_animation(
            100,
            motion,
            13.0,
            1.0,
            LogicalRect::new(0.0, 0.0, 390.0, 568.0),
        ),
        PreviewAnimation::Continuous,
        "the visible cursor-trail card keeps its live preview"
    );

    let mut appearance = SettingsViewState::new(&Config::default());
    appearance.navigate(SettingsRoute::Appearance);
    assert_eq!(
        appearance.preview_animation(100, motion, 13.0, 1.0, view_cx().viewport),
        PreviewAnimation::None,
        "Appearance is a genuinely static renderer sample"
    );
    assert!(
        renderer_preview_spec(&appearance, 100, motion, 17.5, 1.0)
            .unwrap()
            .audit_value()
            .contains("17.5 px"),
        "an unset font-size preview uses the renderer's applied size"
    );
    assert!(
        renderer_preview_spec(&appearance, 100, motion, 1.0, 1.0)
            .unwrap()
            .audit_value()
            .contains("6 px"),
        "host font fallback is normalized to the prefs minimum"
    );

    for (authored, expected) in [
        ("BAR", PreviewCursorStyle::Bar),
        (" Beam ", PreviewCursorStyle::Bar),
        ("hidden", PreviewCursorStyle::Block),
    ] {
        let config: Config = aterm_toml::from_str(&format!(
            "cursor_style = {authored:?}\ncursor_blink = false\ncursor_trail = false\n"
        ))
        .unwrap();
        let mut state = SettingsViewState::new(&config);
        state.navigate(SettingsRoute::CursorMotion);
        assert_eq!(
            renderer_preview_spec(&state, 100, motion, 13.0, 1.0)
                .unwrap()
                .cursor
                .style,
            expected,
            "cursor preview must share the owning resolver for {authored:?}"
        );
    }

    let hidden: Config = aterm_toml::from_str(
        "cursor_style = \"hidden\"\ncursor_blink = true\ncursor_trail = false\n",
    )
    .unwrap();
    let mut hidden = SettingsViewState::new(&hidden);
    hidden.navigate(SettingsRoute::CursorMotion);
    assert_eq!(
        hidden.preview_animation(100, motion, 13.0, 1.0, view_cx().viewport),
        PreviewAnimation::BlinkEdge { after_ms: 430 },
        "an unknown configured cursor style falls back to the runtime's blinking Block"
    );

    let blink: Config = aterm_toml::from_str(
        "cursor_style = \"block\"\ncursor_blink = true\ncursor_trail = false\n",
    )
    .unwrap();
    let mut blink = SettingsViewState::new(&blink);
    blink.navigate(SettingsRoute::CursorMotion);
    assert_eq!(
        blink.preview_animation(100, motion, 13.0, 1.0, view_cx().viewport),
        PreviewAnimation::BlinkEdge { after_ms: 430 }
    );

    let zero: Config = aterm_toml::from_str(
        "cursor_blink = false\ncursor_trail = true\ncursor_trail_style = \"phaser\"\ncursor_trail_intensity = 0.0\ncursor_momentum_glow = false\n",
    )
    .unwrap();
    let mut zero = SettingsViewState::new(&zero);
    zero.navigate(SettingsRoute::CursorMotion);
    assert_eq!(
        zero.preview_animation(100, motion, 13.0, 1.0, view_cx().viewport),
        PreviewAnimation::None,
        "a zero-intensity trail does not arm invisible work"
    );
    let off = |intensity: &str| {
        let config: Config = aterm_toml::from_str(&format!(
            "cursor_blink = false\ncursor_trail = true\ncursor_trail_style = \"off\"\ncursor_trail_intensity = {intensity}\n"
        ))
        .unwrap();
        let mut state = SettingsViewState::new(&config);
        state.navigate(SettingsRoute::CursorMotion);
        state.preview_animation(100, motion, 13.0, 1.0, view_cx().viewport)
    };
    assert_eq!(off("1.0"), PreviewAnimation::Continuous);
    assert_eq!(off("0.0"), PreviewAnimation::None);
}

#[test]
fn canonical_non_cursor_previews_are_pixel_static_across_live_blink_edges() {
    crate::tray_raster::prepare_ui_fonts_for_direct_view_test();
    let config: Config = aterm_toml::from_str(
        "cursor_style = \"bar\"\ncursor_blink = true\ncursor_trail = true\ncursor_trail_style = \"phaser\"\n",
    )
    .unwrap();
    let motion = crate::native_app::ViewMotionCx::default();

    for route in [SettingsRoute::Appearance, SettingsRoute::TextFonts] {
        let mut state = SettingsViewState::new(&config);
        state.navigate(route);
        let early = renderer_preview_spec(&state, 100, motion, 13.0, 1.0)
            .unwrap_or_else(|| panic!("early {route:?} preview"));
        let late = renderer_preview_spec(&state, 600, motion, 13.0, 1.0)
            .unwrap_or_else(|| panic!("late {route:?} preview"));

        assert_eq!(early.animation(), PreviewAnimation::None, "{route:?}");
        assert_eq!(late.animation(), PreviewAnimation::None, "{route:?}");
        assert!(!early.cursor.blink, "{route:?} keeps its static cursor");
        assert!(
            !early.cursor.trail_enabled,
            "{route:?} keeps cursor motion out of its scene"
        );
        assert_eq!(
            early.paint_fingerprint(),
            late.paint_fingerprint(),
            "{route:?} retained identity is phase-static"
        );
        assert_eq!(
            compile_preview_for_pixels(early).1,
            compile_preview_for_pixels(late).1,
            "{route:?} pixels are phase-static"
        );
    }
}

#[test]
fn serious_mode_suppresses_native_preview_trails_post_fx_and_cadence() {
    let config: Config = aterm_toml::from_str(
        "cursor_blink = true\n\
         cursor_trail = true\n\
         cursor_trail_style = \"fire\"\n\
         cursor_trail_bloom = true\n\
         cursor_fire_shimmer = true\n\
         hdr_glow = true\n\
         cursor_glow_sdr_boost = 0.5\n",
    )
    .unwrap();
    let mut state = SettingsViewState::new(&config);
    state.navigate(SettingsRoute::CursorMotion);
    state.common.last_focus = Some(UiKey::new(format!(
        "settings/control/{}",
        prefs::EDIT_CURSOR_FIRE_SHIMMER
    )));

    let active = renderer_preview_spec(
        &state,
        100,
        crate::native_app::ViewMotionCx::default(),
        13.0,
        1.0,
    )
    .expect("active cursor preview");
    assert!(
        active.cursor.trail_enabled,
        "negative control: trail is authored"
    );
    assert!(active.post_fx.bloom, "negative control: bloom is authored");
    assert!(
        active.post_fx.fire_shimmer,
        "negative control: fire shimmer is authored"
    );

    let serious_motion = crate::native_app::ViewMotionCx {
        serious: true,
        ..crate::native_app::ViewMotionCx::default()
    };
    let serious = renderer_preview_spec(&state, 100, serious_motion, 13.0, 1.0)
        .expect("serious cursor preview remains available");
    assert!(serious.reduced_motion);
    assert!(!serious.cursor.trail_enabled);
    assert!(!serious.post_fx.bloom);
    assert!(!serious.post_fx.fire_shimmer);
    assert!(!serious.post_fx.hdr_glow);
    assert_eq!(serious.post_fx.sdr_boost, 0.0);
    assert_eq!(serious.animation(), PreviewAnimation::None);
    assert_ne!(active.paint_fingerprint(), serious.paint_fingerprint());
}

#[test]
fn serious_mode_style_candidate_previews_the_atomic_post_commit_state() {
    let config: Config = aterm_toml::from_str(
        "serious_mode = true\ncursor_trail = true\ncursor_trail_style = \"fire\"\n",
    )
    .unwrap();
    let mut state = SettingsViewState::new(&config);
    state.navigate(SettingsRoute::CursorStyles);
    let serious = crate::native_app::ViewMotionCx {
        serious: true,
        ..crate::native_app::ViewMotionCx::default()
    };
    let preview = |state: &SettingsViewState| {
        renderer_preview_spec_for_key_with_font(
            state,
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            100,
            serious,
            13.0,
            1.0,
            None,
        )
        .unwrap()
    };

    let resting = preview(&state);
    assert!(!resting.cursor.trail_enabled);
    assert_eq!(resting.focused_value, "off");

    state.common.last_focus = Some(UiKey::new(cursor_style_row_key("water")));
    let focused = preview(&state);
    assert!(focused.cursor.trail_enabled);
    assert!(!focused.reduced_motion);
    assert_eq!(focused.cursor.trail_style, PreviewTrailStyle::Water);

    state.common.last_focus = None;
    state.common.hovered = Some(UiKey::new(cursor_style_row_key("water")));
    let hovered = preview(&state);
    assert!(hovered.cursor.trail_enabled);
    assert_eq!(hovered.cursor.trail_style, PreviewTrailStyle::Water);

    state.common.hovered = Some(UiKey::new(cursor_style_row_key("off")));
    let off_candidate = preview(&state);
    assert!(!off_candidate.cursor.trail_enabled);
    assert!(off_candidate.reduced_motion);
    assert!(field_bool(&state, prefs::EDIT_SERIOUS_MODE, false));
}

#[test]
fn top_settings_paints_direct_labels_but_keeps_complete_label_semantics() {
    let (runtime, _instance, view) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    let field = state
        .legacy
        .fields
        .iter()
        .find(|field| field.key == prefs::EDIT_THEME)
        .unwrap();
    let expected_visual = field.label.to_string();
    let row = top_setting_row(state, prefs::EDIT_THEME, None, SettingsWidth::Wide, true)
        .unwrap()
        .row;
    let compiled = UiTree::new(row)
        .compile(LogicalRect::new(0.0, 0.0, 900.0, 80.0))
        .unwrap();
    let wrapper_key = UiKey::new(format!("settings/label/{}", prefs::EDIT_THEME));
    let semantic = compiled.semantic(&wrapper_key).unwrap();
    assert!(
        semantic.label.starts_with(&expected_visual),
        "{}",
        semantic.label
    );
    let visual_key = UiKey::new(format!(
        "settings/label/{}/visual/line-0",
        prefs::EDIT_THEME
    ));
    let visual = painted_row_label(&compiled, prefs::EDIT_THEME).unwrap();
    assert_eq!(visual, expected_visual);
    assert!(!visual.contains("Default"));
    assert!(!visual.contains("Override"));
    assert!(compiled.semantic(&visual_key).is_none());
}

#[test]
fn music_suppression_resolver_covers_every_reason_and_priority() {
    use crate::native_app::ViewMotionCx;
    let motion = ViewMotionCx::default();
    let reason = |config: Config, motion: ViewMotionCx, output: bool| {
        top_music_suppression_reason_for_output(
            &SettingsViewState::new(&Config {
                cursor_trail: config.cursor_trail.or(Some(true)),
                ..config
            }),
            motion,
            output,
        )
    };

    assert_eq!(
        reason(Config::default(), motion, false),
        Some(MusicStatus::NoOutput { saved_on: true })
    );
    assert_eq!(
        reason(
            Config {
                trail_sounds: Some(false),
                ..Config::default()
            },
            motion,
            false,
        ),
        Some(MusicStatus::NoOutput { saved_on: false })
    );

    for (config, cx, why) in [
        (
            Config {
                trail_sounds: Some(false),
                ..Config::default()
            },
            motion,
            "an authored Off switch is not described as suppressed",
        ),
        (
            Config {
                serious_mode: Some(true),
                ..Config::default()
            },
            motion,
            "Serious Mode projects the switch Off instead of claiming it is On",
        ),
        (
            Config {
                cursor_trail_style: Some("not-a-trail".to_string()),
                ..Config::default()
            },
            motion,
            "an unknown style falls back to the default trail and still plays",
        ),
        (
            Config::default(),
            ViewMotionCx {
                focused: false,
                ..motion
            },
            "this window's focus is not a gate of Music effects",
        ),
        (
            Config {
                load_adaptive_motion: Some(false),
                ..Config::default()
            },
            ViewMotionCx {
                performance_reduced: true,
                ..motion
            },
            "the authored adaptive-motion opt-out is respected",
        ),
        (
            Config {
                motion: Some("full".to_string()),
                ..Config::default()
            },
            ViewMotionCx {
                system_reduced: true,
                performance_reduced: true,
                ..motion
            },
            "explicit Full overrides system and adaptive reduction",
        ),
    ] {
        assert_eq!(reason(config, cx, true), None, "{why}");
    }

    type Rung = fn(&mut Config, &mut ViewMotionCx);
    let ladder: [(Rung, MusicStatus); 5] = [
        (
            |config, _| config.trail_sound_volume = Some(0.0),
            MusicStatus::VolumeZero,
        ),
        (
            |config, _| config.cursor_trail_style = Some("off".to_string()),
            MusicStatus::TypingNotesOff,
        ),
        (
            |config, _| config.motion = Some("reduced".to_string()),
            MusicStatus::MotionPaused(MotionReduction::Setting),
        ),
        (
            |_, cx| cx.system_reduced = true,
            MusicStatus::MotionPaused(MotionReduction::System),
        ),
        (
            |_, cx| cx.performance_reduced = true,
            MusicStatus::MotionPaused(MotionReduction::HeavyLoad),
        ),
    ];
    let apply = |rungs: &[(Rung, MusicStatus)]| {
        let mut config = Config::default();
        let mut cx = motion;
        for (rung, _) in rungs {
            rung(&mut config, &mut cx);
        }
        reason(config, cx, true)
    };
    for (index, (_, status)) in ladder.iter().enumerate() {
        assert_eq!(
            apply(&ladder[index..=index]),
            Some(*status),
            "rung {index} on its own"
        );
        assert_eq!(
            apply(&ladder[index..]),
            Some(*status),
            "rung {index} outranks every later rung"
        );
    }

    let full = MusicStatus::MotionPaused(MotionReduction::Setting).full();
    assert!(
        full.starts_with("On. ")
            && full.contains(&reduce_motion_words())
            && full.contains("the bonk")
            && full.contains("the note when a program starts printing")
            && full.contains("other sounds still play")
            && !full.contains("silent"),
        "{full}"
    );
}

#[test]
fn highlighted_motion_candidate_resolves_against_live_host_facts_before_commit() {
    let config: Config = aterm_toml::from_str("motion = \"reduced\"\n").unwrap();
    let mut state = SettingsViewState::new(&config);
    state.navigate(SettingsRoute::CursorMotion);
    let field = state
        .legacy
        .fields
        .iter()
        .find(|field| field.key == prefs::EDIT_MOTION)
        .expect("motion field");
    let picker = ChoicePicker::new(
        prefs::EDIT_MOTION,
        choices_for_field(field, &state.assets.themes).expect("motion choices"),
        SettingsState::display_value(field),
        true,
        true,
        &effective_default_for_field(prefs::EDIT_MOTION),
    );
    state.choice_picker = Some(picker);
    let focus = |state: &mut SettingsViewState, value: &str| {
        let picker = state.choice_picker.as_ref().unwrap();
        let index = picker
            .options
            .iter()
            .position(|option| option.value.as_deref().unwrap_or("auto") == value)
            .unwrap();
        state.common.last_focus = Some(UiKey::new(format!(
            "settings/choice/{}/{index}",
            prefs::EDIT_MOTION
        )));
    };

    let preview_reduced_motion =
        |state: &SettingsViewState, motion: crate::native_app::ViewMotionCx| {
            renderer_preview_spec_for_key_with_font(
                state,
                prefs::EDIT_MOTION,
                100,
                motion,
                13.0,
                1.0,
                None,
            )
            .expect("the Motion row has a live preview")
            .reduced_motion
        };
    let constrained = crate::native_app::ViewMotionCx {
        system_reduced: true,
        performance_reduced: true,
        ..crate::native_app::ViewMotionCx::default()
    };
    focus(&mut state, "full");
    assert!(
        !preview_reduced_motion(&state, constrained),
        "highlighted Full overrides OS and adaptive reduction"
    );
    focus(&mut state, "auto");
    assert!(preview_reduced_motion(&state, constrained));
    focus(&mut state, "reduced");
    assert!(preview_reduced_motion(
        &state,
        crate::native_app::ViewMotionCx::default()
    ));

    focus(&mut state, "auto");
    let load_only = crate::native_app::ViewMotionCx {
        system_reduced: false,
        performance_reduced: true,
        ..crate::native_app::ViewMotionCx::default()
    };
    assert!(preview_reduced_motion(&state, load_only));
    state
        .legacy
        .fields
        .iter_mut()
        .find(|field| field.key == prefs::EDIT_LOAD_ADAPTIVE_MOTION)
        .unwrap()
        .seed = Some("false".to_string());
    assert!(!preview_reduced_motion(&state, load_only));

    focus(&mut state, "full");
    assert!(preview_reduced_motion(
        &state,
        crate::native_app::ViewMotionCx {
            focused: false,
            ..crate::native_app::ViewMotionCx::default()
        }
    ));
    assert_eq!(
        state.raw_value(prefs::EDIT_MOTION).as_deref(),
        Some("reduced")
    );
}

fn setup() -> (
    NativeRuntime,
    crate::native_app::AppInstanceId,
    crate::native_app::ViewId,
) {
    setup_with_update(UpdateState::from_status(1, "0.1.0", None, false))
}

fn setup_with_update(
    update: UpdateState,
) -> (
    NativeRuntime,
    crate::native_app::AppInstanceId,
    crate::native_app::ViewId,
) {
    setup_with(update, SettingsViewState::new(&Config::default()))
}

/// A Settings app on `update`, its one view on `state`.
fn setup_with(
    update: UpdateState,
    state: SettingsViewState,
) -> (
    NativeRuntime,
    crate::native_app::AppInstanceId,
    crate::native_app::ViewId,
) {
    let app = SettingsApp::new(update);
    let mut runtime = NativeRuntime::new();
    let instance = runtime
        .insert_instance(NativeApp::Settings(Box::new(app)))
        .unwrap();
    let mut core_views = ViewStore::default();
    let view = core_views.insert_native(instance).unwrap();
    runtime
        .attach_view(view, instance, AppViewState::Settings(Box::new(state)))
        .unwrap();
    (runtime, instance, view)
}

fn replace_settings_source(
    runtime: &mut NativeRuntime,
    view: crate::native_app::ViewId,
    source: String,
) {
    let snapshot = VersionedConfigService::new(source)
        .expect("valid Settings fixture")
        .snapshot();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        panic!("Settings view");
    };
    **state = SettingsViewState::from_snapshot(&snapshot).expect("project Settings fixture");
}

#[test]
fn every_rung_of_the_update_page_admits_a_stage_that_failed_to_apply() {
    use crate::update_apply_trouble::ApplyRetry;

    let mut status = update_status(true);
    status.failing_applies = 2;
    status.outcome = "staged 0.2.0 (build 2) \u{2014} verified and ready to apply".to_string();
    let troubled = UpdateState::from_status(1, "0.1.0", Some(&status), false)
        .with_apply_lane(
            "overlap handoff failed safely: handoff proof ended ChildDied",
            ApplyRetry::Scheduled,
        )
        .projection();

    assert!(
        !troubled.apply_is_failing,
        "two is below the escalation threshold — the window the page used to \
         spend saying \"Ready\""
    );
    let detail = compact_update_detail(&troubled);
    assert!(
        !detail.contains("ChildDied"),
        "never the proof-outcome enum name: {detail}"
    );
    let minimum = compact_update_detail_minimum(&troubled);
    assert!(
        minimum.contains('2'),
        "the count survives to the tersest rung: {minimum}"
    );

    let clean = UpdateState::from_status(1, "0.1.0", Some(&update_status(true)), false)
        .with_apply_lane(
            "overlap handoff failed safely: handoff proof ended ChildDied",
            ApplyRetry::Scheduled,
        )
        .projection();
    assert!(clean.apply_trouble.is_none());
    assert_ne!(
        compact_update_headline(&troubled),
        compact_update_headline(&clean)
    );
    assert_ne!(
        compact_update_summary_detail(&troubled),
        compact_update_summary_detail(&clean)
    );
    assert_ne!(detail, compact_update_detail(&clean));
    assert_ne!(minimum, compact_update_detail_minimum(&clean));
}

#[test]
fn the_update_button_never_starts_a_build_on_hold() {
    use crate::update_apply_trouble::ApplyRetry;
    let press = |failed: u32, retry: ApplyRetry, id: &str| {
        let on_hold = retry == ApplyRetry::NewerRelease;
        let mut status = update_status(true);
        status.failing_applies = failed;
        let update = UpdateState::from_status(1, "0.1.0", Some(&status), false)
            .with_apply_lane("handoff proof ended ChildDied", retry)
            .with_staged_on_hold(on_hold);
        let projection = update.projection();
        assert_eq!(projection.staged_on_hold, on_hold);
        if on_hold {
            let said = [
                projection.headline.clone(),
                projection.detail.clone().expect("detail"),
                compact_update_headline(&projection),
                compact_update_summary_detail(&projection).to_string(),
                compact_update_detail(&projection),
                compact_update_detail_minimum(&projection),
            ];
            assert!(
                said.iter().all(|line| !line.contains("ready")
                    && !line.contains("Ready")
                    && !line.contains("Install")),
                "{said:?}"
            );
        }
        let (mut runtime, instance, view) = setup_with_update(update);
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::SoftwareUpdate),
                    value: None,
                }),
            )
            .unwrap();
        let pressed = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(id),
                    value: None,
                }),
            )
            .unwrap();
        let request = pressed.effects.iter().find_map(|effect| match effect {
            AppEffect::Update { request, .. } => Some(*request),
            _ => None,
        });
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            panic!("Settings view")
        };
        (request, state.feedback.clone())
    };
    for id in ["updates/install-now", "updates/check"] {
        for failed in [2, 0] {
            let (request, said) = press(failed, ApplyRetry::NewerRelease, id);
            assert_eq!(request, None, "{id} sends nothing for a build on hold");
            assert!(said.is_some(), "{id} says why it sent nothing");
        }
    }
    assert_eq!(
        press(2, ApplyRetry::ManualOnly, "updates/install-now").0,
        Some(UpdateRequest::InstallAndRelaunch)
    );
}

#[test]
// The in-app updater's page: Windows has none (`native_updater_here`).
#[cfg(any(target_os = "macos", target_os = "linux"))]
fn an_unread_copy_claims_nothing_about_updating_itself() {
    let press = |update: UpdateState| {
        let (mut runtime, instance, view) = setup_with_update(update);
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::SoftwareUpdate),
                    value: None,
                }),
            )
            .unwrap();
        let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_074.0, 684.0));
        let headline = compiled
            .semantic(&UiKey::new("updates/headline"))
            .map(|node| node.label.clone())
            .expect("the status headline");
        let action = compiled
            .semantic(&UiKey::new("updates/install-now"))
            .and_then(|node| node.state)
            .expect("the action");
        let caption = compiled
            .semantic(&UiKey::new("updates/automatic/caption"))
            .map(|node| node.label.clone());
        let pressed = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("updates/install-now"),
                    value: None,
                }),
            )
            .unwrap();
        let request = pressed.effects.iter().find_map(|effect| match effect {
            AppEffect::Update { request, .. } => Some(*request),
            _ => None,
        });
        (headline, action, caption, request)
    };
    let (headline, action, caption, request) =
        press(UpdateState::from_status(1, "0.1.0", None, false));
    assert_eq!(headline, crate::update_screen::UPDATE_UNOBSERVED_HEADLINE);
    assert!(!action.enabled && action.busy, "{action:?}");
    assert_eq!(caption, None, "no caption claims what the switches do");
    assert_eq!(request, None, "no check is sent on a guess");

    let linux = cfg!(target_os = "linux");
    let linux_rungs = [
        SettingsWidth::Wide,
        SettingsWidth::Medium,
        SettingsWidth::Compact,
    ]
    .map(|width| update_automatic_caption(width, false, true, UpdateInstallability::Installable));
    let mut read = update_status(false);
    read.installable = true;
    let (headline, action, caption, request) =
        press(UpdateState::from_status(1, "0.1.0", Some(&read), false));
    assert_ne!(headline, crate::update_screen::UPDATE_UNOBSERVED_HEADLINE);
    assert!(action.enabled, "{action:?}");
    assert_eq!(request, Some(UpdateRequest::Check));
    if linux {
        assert!(
            caption
                .as_ref()
                .is_some_and(|text| linux_rungs.contains(text)),
            "a Linux copy's caption is Linux's updater's: {caption:?}"
        );
    }

    read.installable = false;
    let (headline, action, caption, request) =
        press(UpdateState::from_status(1, "0.1.0", Some(&read), false));
    assert_eq!(headline, "This copy of aterm can\u{2019}t update itself.");
    assert!(!action.enabled, "{action:?}");
    if linux {
        assert!(
            caption
                .as_ref()
                .is_some_and(|text| linux_rungs.contains(text)),
            "a Linux copy's caption is Linux's updater's: {caption:?}"
        );
    } else {
        assert!(caption.is_some_and(|text| text.contains("installed copy")));
    }
    assert_eq!(request, None);
}

fn update_status(staged: bool) -> aterm_update::UpdateStatus {
    aterm_update::UpdateStatus {
        linux: None,
        enabled: true,
        current_build: 1,
        staged_build: staged.then_some(2),
        staged_version: staged.then(|| "0.2.0".to_string()),
        staged_commit: staged.then(|| "deadbeef".to_string()),
        staged_dmg_sha256: staged.then(|| "0".repeat(64)),
        changelog: staged
            .then(|| "### Better\n- compact Settings\n- semantic previews".to_string()),
        outcome: "Update service healthy".to_string(),
        updated_at: String::new(),
        failing_checks: 0,
        failing_kind: String::new(),
        failing_applies: 0,
        installable: true,
        failing_since: String::new(),
        failing_persistent: false,
        failing_checks_kind: String::new(),
        channel_unreadable: false,
    }
}

