fn access_fixture(fda: FdaState, dr: DrClass, scope: aterm_containment::FdaScope) -> MacosAccess {
    crate::security_fixtures::access(fda, dr, scope)
}

fn census_fixture(running_stable: bool) -> aterm_containment::consent::Claimants {
    crate::security_fixtures::census(running_stable)
}

fn every_retire_outcome() -> crate::consent_retire::RetireReport {
    use aterm_containment::consent::Retired;
    [
        ("/A/moved.app", Retired::Moved),
        ("/A/gone.app", Retired::NotOffered),
        ("/A/busy.app", Retired::InUse),
        (
            "/A/refused.app",
            Retired::Failed("The operation couldn’t be completed.".to_string()),
        ),
    ]
    .into_iter()
    .map(|(path, outcome)| (std::path::PathBuf::from(path), outcome))
    .collect()
}

#[test]
fn the_census_is_on_the_panel_and_the_trash_button_takes_only_what_it_lists() {
    use aterm_containment::FdaScope;
    let buttons = |access: &MacosAccess| -> Vec<String> {
        let mut out = Vec::new();
        fn walk(node: &UiNode, out: &mut Vec<String>) {
            if let UiContent::Button(control) = &node.content {
                out.push(control.action.as_str().to_string());
            }
            for child in &node.children {
                walk(child, out);
            }
        }
        walk(
            &macos_access_card(access, AccessLead::Whole, f32::INFINITY),
            &mut out,
        );
        out
    };
    let mut access = access_fixture(FdaState::Granted, DrClass::Identity, FdaScope::Unknown);
    assert!(
        macos_access_copy(&access).claimants.is_empty(),
        "no census, no rows"
    );

    access.claimants = Some(census_fixture(true));
    let copy = macos_access_copy(&access);
    assert_eq!(copy.claimants.len(), 3, "{:#?}", copy.claimants);
    assert!(copy.claimants[1].starts_with("/Applications/aterm.app.rollback "));
    assert!(copy.claimants[2].starts_with("/Users//a/Old/aterm.app "));
    let mut linked = census_fixture(true);
    linked.found[2].links = vec![std::path::PathBuf::from("/Applications/aterm-old.app")];
    let row = macos_access_copy(&MacosAccess {
        claimants: Some(linked),
        ..access.clone()
    })
    .claimants[2]
        .clone();
    assert!(
        row.starts_with("/Users//a/Old/aterm.app ") && row.contains("/Applications/aterm-old.app"),
        "{row}"
    );
    assert_eq!(
        access.retire_plan(),
        vec![std::path::PathBuf::from("/Applications/aterm.app.rollback")]
    );
    assert!(buttons(&access).contains(&MACOS_ACCESS_TRASH.to_string()));
    assert!(
        macos_access_height(&access, AccessLead::Whole, f32::INFINITY)
            > macos_access_height(
                &MacosAccess {
                    claimants: None,
                    ..access.clone()
                },
                AccessLead::Whole,
                f32::INFINITY
            ),
        "the card is authored tall enough for its rows"
    );

    access.trash_tool = false;
    assert!(access.retire_plan().is_empty());
    assert!(!buttons(&access).contains(&MACOS_ACCESS_TRASH.to_string()));

    access.trash_tool = true;
    access.claimants = Some(census_fixture(false));
    assert!(
        access.retire_plan().is_empty(),
        "beside an unstable running copy"
    );
    assert!(!buttons(&access).contains(&MACOS_ACCESS_TRASH.to_string()));

    access.retired = Some(every_retire_outcome());
    let retired = macos_access_copy(&access).retired;
    assert_eq!(retired.len(), 4, "one line per outcome: {retired:?}");
    assert!(retired[3].ends_with("The operation couldn’t be completed."));
}

#[test]
fn a_decline_quiets_every_view_and_doubles_in_a_row() {
    use aterm_containment::FdaScope;
    use std::sync::atomic::{AtomicUsize, Ordering};
    static ASKED: AtomicUsize = AtomicUsize::new(0);
    fn counting_no(_title: &str, _body: &str, _proceed: &str) -> Option<bool> {
        ASKED.fetch_add(1, Ordering::AcqRel);
        Some(false)
    }
    ASKED.store(0, Ordering::Release);
    let mut access = access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown);
    access.warmup_rows = denied_rows();
    let shared = SharedOwnerQuiet::default();
    let open_view = || {
        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Security);
            state.replace_macos_access(access.clone());
            state.arm_consent_gestures(ConsentGestures {
                confirm: ConfirmArm::StandIn(counting_no),
                ..ConsentGestures::inert()
            });
            state.arm_owner_quiet(std::sync::Arc::clone(&shared));
        }
        (runtime, instance, view)
    };
    let press = |runtime: &mut NativeRuntime, instance, view, action: &'static str| {
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(action),
                    value: None,
                }),
            )
            .unwrap();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.feedback.clone().unwrap_or_default()
    };
    let quieted = OwnerAnswer::Quiet.refusal("");
    let (mut runtime, instance, view) = open_view();
    assert_ne!(
        press(&mut runtime, instance, view, MACOS_ACCESS_ASK_AGAIN),
        quieted,
        "the first press asks and is declined, not quieted"
    );
    for _ in 0..2 {
        assert_eq!(
            press(&mut runtime, instance, view, MACOS_ACCESS_ASK_AGAIN),
            quieted,
            "the same view, a queued press"
        );
    }
    let (mut later, later_instance, later_view) = open_view();
    assert_eq!(
        press(&mut later, later_instance, later_view, MACOS_ACCESS_WARM_UP),
        quieted,
        "a view opened after the decline, another gesture"
    );
    assert_eq!(ASKED.load(Ordering::Acquire), 1, "one alert, then quiet");

    let start = QuietStamp::now();
    let mut quiet = OwnerQuiet::default();
    quiet.declined(start);
    assert!(quiet.quiet_at(start.after(OWNER_QUIET_FIRST / 2)));
    assert!(!quiet.quiet_at(start.after(OWNER_QUIET_FIRST)));
    let second = start.after(OWNER_QUIET_FIRST);
    quiet.declined(second);
    assert!(
        quiet.quiet_at(second.after(OWNER_QUIET_FIRST * 3 / 2)),
        "doubled"
    );
    for n in 0..20 {
        quiet.declined(second.after(OWNER_QUIET_FIRST * n));
    }
    let last = second.after(OWNER_QUIET_FIRST * 19);
    assert!(quiet.quiet_at(last.after(OWNER_QUIET_MAX / 2)));
    assert!(!quiet.quiet_at(last.after(OWNER_QUIET_MAX)), "capped");

    let hours = std::time::Duration::from_secs(8 * 60 * 60);
    let woke = QuietStamp {
        awake: last.awake + std::time::Duration::from_secs(1),
        wall: last.wall + hours,
    };
    assert!(!quiet.quiet_at(woke), "the wall clock ends it");
    quiet.declined(woke);
    assert!(quiet.quiet_at(woke.after(OWNER_QUIET_FIRST / 2)));
    assert!(
        !quiet.quiet_at(woke.after(OWNER_QUIET_FIRST)),
        "first again"
    );
    let set_back = QuietStamp {
        awake: woke.awake + OWNER_QUIET_FIRST,
        wall: woke.wall - hours,
    };
    assert!(!quiet.quiet_at(set_back), "the awake clock ends it");
    quiet.accepted();
    assert!(!quiet.quiet_at(last));
}

#[test]
fn the_reset_report_expires_and_the_trash_status_shows_in_every_layout() {
    use aterm_containment::FdaScope;
    let mut access = access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown);
    access.warmup_rows = denied_rows();
    let report = MacosAccessReset::from_attempts(&[]);
    let (mut runtime, _instance, view) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    state.navigate(SettingsRoute::Security);
    state.replace_macos_access(MacosAccess {
        reset: Some(report),
        ..access.clone()
    });
    state.replace_macos_access(access.clone());
    assert!(
        state
            .macos_access_for_test()
            .is_some_and(|a| a.reset.is_some())
    );
    state.replace_macos_access(MacosAccess {
        warmup_live: true,
        ..access.clone()
    });
    assert!(
        state
            .macos_access_for_test()
            .is_some_and(|a| a.reset.is_none()),
        "a warm-up under way follows the report's advice"
    );
    state.replace_macos_access(MacosAccess {
        reset: Some(MacosAccessReset::from_attempts(&[])),
        ..access.clone()
    });
    state.navigate(SettingsRoute::Appearance);
    state.navigate(SettingsRoute::Security);
    state.replace_macos_access(access.clone());
    assert!(
        state
            .macos_access_for_test()
            .is_some_and(|a| a.reset.is_none()),
        "leaving the page drops it"
    );

    let status = MacosAccess {
        retire_status: Some("Moved 1 copy to the Trash.".to_string()),
        ..access
    };
    for lead in AccessLead::ALL {
        let card = macos_access_card(&status, lead, f32::INFINITY);
        fn has(node: &UiNode, key: &str) -> bool {
            node.key.as_str() == key || node.children.iter().any(|c| has(c, key))
        }
        assert!(
            has(&card, "settings/macos-access/retire-status"),
            "lead={lead:?}"
        );
    }
    assert!(
        macos_access_height(&status, AccessLead::NoTrade, f32::INFINITY)
            > macos_access_height(
                &MacosAccess {
                    retire_status: None,
                    ..status.clone()
                },
                AccessLead::NoTrade,
                f32::INFINITY
            )
    );
}

#[test]
fn owner_text_escapes_what_draws_as_nothing_and_keeps_the_rest() {
    for hidden in [
        '\u{00AD}',
        '\u{061C}',
        '\u{200B}',
        '\u{2028}',
        '\u{202E}',
        '\u{2066}',
        '\u{3164}',
        '\u{FE0F}',
        '\u{FFF0}',
        '\u{FFFA}',
        '\u{1BCA0}',
        '\u{1D173}',
        '\u{E0041}',
        '\u{E0FFF}',
        '\u{13430}',
        '\u{1343F}',
        '\n',
        '\u{7F}',
    ] {
        let shown = owner_text(&format!("a{hidden}b"));
        assert!(
            !shown.contains(hidden),
            "{hidden:?} passed through: {shown}"
        );
        assert!(
            shown.starts_with("a\\u{") && shown.ends_with("}b"),
            "{shown}"
        );
    }
    let plain = "/Users/é/日本/aterm (dev).app";
    assert_eq!(owner_text(plain), plain);
}

#[test]
fn switching_privacy_off_takes_the_ask_again_offer_and_its_advice() {
    use aterm_containment::FdaScope;
    let mut access = access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown);
    access.warmup_rows = denied_rows();
    assert!(access.reset_plan().is_some());
    assert!(
        MacosAccess {
            enabled: false,
            ..access.clone()
        }
        .reset_plan()
        .is_none()
    );
    let report = MacosAccessReset {
        outcome: ResetOutcome::AllReset,
        reset: vec![Folder::Documents],
        declined: Vec::new(),
    };

    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Security);
        state.replace_macos_access(access.clone());
        state.arm_consent_gestures(ConsentGestures::confirming());
    }
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(MACOS_ACCESS_ASK_AGAIN),
                value: None,
            }),
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    assert!(state.feedback.is_some());
    state.replace_macos_access(MacosAccess {
        enabled: false,
        ..access
    });
    assert_eq!(state.feedback, None, "the advice went with the switch");
    assert!(
        state
            .macos_access_for_test()
            .is_some_and(|a| a.reset.is_none())
    );

    {
        let mut rows = denied_rows();
        let denied = access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown);
        state.replace_macos_access(MacosAccess {
            warmup_rows: rows.clone(),
            reset: Some(report.clone()),
            ..denied.clone()
        });
        state.feedback = Some("Asking macOS about the items listed here".to_string());
        state.macos_access_feedback = state.feedback.clone();
        state.reset_feedback = Some("the report's line".to_string());
        let mut changed = rows.clone();
        changed[1].1 = crate::consent_warmup::WarmupRow::Allowed;
        state.replace_macos_access(MacosAccess {
            warmup_rows: changed,
            ..denied.clone()
        });
        assert!(state.feedback.is_some(), "the warm-up's line survives");
        state.replace_macos_access(MacosAccess {
            warmup_rows: rows.clone(),
            reset: Some(report.clone()),
            ..denied.clone()
        });
        state.feedback = Some("the block's line".to_string());
        state.macos_access_feedback = state.feedback.clone();
        state.reset_feedback = state.feedback.clone();
        rows[0].1 = crate::consent_warmup::WarmupRow::Allowed;
        state.replace_macos_access(MacosAccess {
            warmup_rows: rows,
            ..denied
        });
        assert!(
            state
                .macos_access_for_test()
                .is_some_and(|a| a.reset.is_none())
        );
        assert_eq!(state.feedback, None, "the line went with its report");

        state.feedback = Some("the block's line".to_string());
        state.macos_access_feedback = state.feedback.clone();
        state.replace_macos_access(MacosAccess {
            warmup_offered: false,
            ..state.macos_access_for_test().cloned().expect("published")
        });
        assert_eq!(state.feedback, None, "the warm-up switch took it");
    }

    let never = MacosAccess {
        warmup_offered: false,
        ..access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown)
    };
    state.replace_macos_access(MacosAccess {
        reset: Some(report.clone()),
        ..never.clone()
    });
    state.replace_macos_access(never);
    let kept = state.macos_access_for_test().cloned().expect("published");
    assert_eq!(kept.reset, Some(report), "kept across the republish");
}

#[test]
fn the_trash_alert_escapes_planted_names_and_counts_its_copies() {
    use aterm_containment::FdaScope;
    use aterm_containment::consent::{Claimant, Claimants, Enumeration, classify_dr};
    static SEEN: std::sync::Mutex<Vec<(String, String)>> = std::sync::Mutex::new(Vec::new());
    fn record_no(title: &str, body: &str, _proceed: &str) -> Option<bool> {
        SEEN.lock()
            .unwrap_or_else(|p| p.into_inner())
            .push((title.to_string(), body.to_string()));
        Some(false)
    }
    SEEN.lock().unwrap_or_else(|p| p.into_inner()).clear();
    let planted =
        "/Users//a/Applications/x\n\u{2028}\u{2029}Nothing leaves this Mac.\u{202E}ppa.app";
    let dev_id = "designated => identifier \"x\" and anchor apple generic and certificate \
                  leaf[subject.OU] = \"T\"";
    let copy = |path: &str, dr_text: &str, running: bool| Claimant {
        path: std::path::PathBuf::from(path),
        dr: classify_dr(dr_text),
        dr_text: dr_text.to_string(),
        signing: if running { "developer-id" } else { "adhoc" },
        team: None,
        running,
        links: Vec::new(),
    };
    let mut access = access_fixture(FdaState::Granted, DrClass::Identity, FdaScope::Unknown);
    access.claimants = Some(Claimants {
        found: vec![
            copy("/Applications/aterm.app", dev_id, true),
            copy(planted, "designated => cdhash H\"aa\"", false),
        ],
        enumeration: Enumeration::Complete,
    });
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Security);
        state.replace_macos_access(access.clone());
        state.arm_consent_gestures(ConsentGestures {
            confirm: ConfirmArm::StandIn(record_no),
            ..ConsentGestures::inert()
        });
    }
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(MACOS_ACCESS_TRASH),
                value: None,
            }),
        )
        .unwrap();
    let seen = SEEN.lock().unwrap_or_else(|p| p.into_inner()).clone();
    assert_eq!(seen.len(), 1);
    let (_title, body) = &seen[0];
    let named = body.lines().next().expect("the copy's line");
    assert_eq!(
        named,
        "/Users//a/Applications/x\\u{000A}\\u{2028}\\u{2029}Nothing leaves this Mac.\\u{202E}ppa.app",
        "the planted name is one escaped line"
    );
    assert!(
        !body.contains(['\u{2028}', '\u{2029}', '\u{202E}']),
        "{body:?}"
    );
    assert!(
        macos_access_copy(&access)
            .claimants
            .iter()
            .all(|line| !line.contains(['\n', '\u{2028}', '\u{2029}', '\u{202E}'])),
        "the panel rows escape it too"
    );
}

#[test]
fn an_unconfirmed_owner_gesture_changes_nothing() {
    use aterm_containment::FdaScope;
    let mut access = access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown);
    access.warmup_rows = denied_rows();
    access.claimants = Some(census_fixture(true));
    for action in [
        MACOS_ACCESS_WARM_UP,
        MACOS_ACCESS_ASK_AGAIN,
        MACOS_ACCESS_TRASH,
    ] {
        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Security);
            state.replace_macos_access(access.clone());
        }
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(action),
                    value: None,
                }),
            )
            .unwrap();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        assert!(!state.take_consent_warmup_request(), "{action}");
        assert_eq!(state.take_claimant_retire_request(), None, "{action}");
        assert!(
            state
                .macos_access_for_test()
                .is_some_and(|access| access.reset.is_none()),
            "{action}"
        );
        let said = state.feedback.clone();
        assert!(said.is_some(), "{action}: says so");
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(action),
                    value: None,
                }),
            )
            .unwrap();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        assert_eq!(
            state.feedback, said,
            "{action}: not asked is not a decline, so the next press is not quieted"
        );
    }
}

#[test]
fn a_press_behind_a_confirmed_alert_asks_nothing() {
    use aterm_containment::FdaScope;
    use std::sync::atomic::{AtomicUsize, Ordering};
    static ASKED: AtomicUsize = AtomicUsize::new(0);
    fn counting_yes(_title: &str, _body: &str, _proceed: &str) -> Option<bool> {
        ASKED.fetch_add(1, Ordering::AcqRel);
        Some(true)
    }
    let mut trash = access_fixture(FdaState::Granted, DrClass::Identity, FdaScope::Unknown);
    trash.claimants = Some(census_fixture(true));
    let warm_up = access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown);
    for (action, access, under_way) in [
        (MACOS_ACCESS_WARM_UP, warm_up, "already asking"),
        (MACOS_ACCESS_TRASH, trash, "already moving"),
    ] {
        ASKED.store(0, Ordering::Release);
        let shared = SharedOwnerQuiet::default();
        let open_view = || {
            let (mut runtime, instance, view) = setup();
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Security);
            state.replace_macos_access(access.clone());
            state.arm_consent_gestures(ConsentGestures {
                confirm: ConfirmArm::StandIn(counting_yes),
                ..ConsentGestures::inert()
            });
            state.arm_owner_quiet(std::sync::Arc::clone(&shared));
            (runtime, instance, view)
        };
        let press = |runtime: &mut NativeRuntime, instance, view| {
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::Action(ActionInvocation {
                        id: ActionId::new(action),
                        value: None,
                    }),
                )
                .unwrap();
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.feedback.clone().unwrap_or_default()
        };
        let (mut first, first_instance, first_view) = open_view();
        let (mut second, second_instance, second_view) = open_view();
        let _ = press(&mut first, first_instance, first_view);
        let queued = press(&mut first, first_instance, first_view);
        assert!(
            queued.contains(under_way),
            "{action}: the same view: {queued}"
        );
        let other = press(&mut second, second_instance, second_view);
        assert!(other.contains(under_way), "{action}: another view: {other}");
        assert_eq!(
            ASKED.load(Ordering::Acquire),
            1,
            "{action}: one alert for three presses"
        );

        {
            let Some(AppViewState::Settings(state)) = first.view_state_mut(first_view) else {
                unreachable!();
            };
            let taken = if action == MACOS_ACCESS_WARM_UP {
                state.take_consent_warmup_request()
            } else {
                state.take_claimant_retire_request().is_some()
            };
            assert!(taken, "{action}: one request recorded");
            assert!(
                !state.take_consent_warmup_request()
                    && state.take_claimant_retire_request().is_none(),
                "{action}: consumed exactly once"
            );
            let mut running = state.macos_access.clone().expect("published");
            running.warmup_live = true;
            running.retire_live = true;
            state.replace_macos_access(running.clone());
            assert!(
                state
                    .feedback
                    .as_deref()
                    .is_some_and(|line| line.contains(under_way)),
                "{action}: kept while it runs"
            );
            if action == MACOS_ACCESS_WARM_UP {
                running.retire_live = true;
                running.warmup_live = false;
            } else {
                running.warmup_live = true;
                running.retire_live = false;
            }
            assert!(
                state.replace_macos_access(running.clone()),
                "{action}: the line going is a change to draw"
            );
            assert_eq!(state.feedback, None, "{action}: gone once it is not");
            assert!(
                !state.replace_macos_access(running),
                "{action}: and nothing more changes"
            );
        }

        shared
            .lock()
            .unwrap_or_else(|p| p.into_inner())
            .settle_confirmed();
        {
            let Some(AppViewState::Settings(state)) = first.view_state_mut(first_view) else {
                unreachable!();
            };
            state.replace_macos_access(MacosAccess {
                warmup_live: true,
                retire_live: true,
                ..access.clone()
            });
        }
        let live = press(&mut first, first_instance, first_view);
        assert!(live.contains(under_way), "{action}: a live worker: {live}");
        assert_eq!(ASKED.load(Ordering::Acquire), 1, "{action}: no second ask");
        {
            let Some(AppViewState::Settings(state)) = first.view_state_mut(first_view) else {
                unreachable!();
            };
            assert!(
                !state.take_consent_warmup_request()
                    && state.take_claimant_retire_request().is_none(),
                "{action}: a press beside a live worker records no second worker"
            );
        }
        let _ = press(&mut second, second_instance, second_view);
        assert_eq!(
            ASKED.load(Ordering::Acquire),
            2,
            "{action}: settled, a new press asks"
        );
    }
}

fn debugger_facts(
    mode: aterm_containment::consent::DebuggerMode,
    member: aterm_containment::consent::DebuggerMember,
    hardening: aterm_containment::consent::SelfHardening,
) -> crate::debugger_access::DebuggerFacts {
    use aterm_containment::consent::{DebuggerMode, DebuggerProbe, DebuggerProbeLabel};
    crate::debugger_access::DebuggerFacts {
        enabled: true,
        probe: DebuggerProbe {
            mode,
            member,
            label: if mode == DebuggerMode::Unknown {
                DebuggerProbeLabel::StatusUnrecognized
            } else {
                DebuggerProbeLabel::StatusOk
            },
        },
        self_hardened: hardening,
        in_flight: None,
        busy: false,
        recorded: None,
        drift_since: None,
        last_outcome: None,
        refusal: None,
    }
}

fn debugger_access(facts: crate::debugger_access::DebuggerFacts) -> MacosAccess {
    MacosAccess {
        debugger: facts,
        ..access_fixture(
            FdaState::Granted,
            DrClass::Identity,
            aterm_containment::FdaScope::Unknown,
        )
    }
}

fn every_debugger_facts() -> Vec<crate::debugger_access::DebuggerFacts> {
    use crate::debugger_access::{InFlightFacts, ObservedMarker, Origin, Outcome, Refusal};
    use aterm_containment::consent::{
        DebuggerChange, DebuggerMember, DebuggerMode, DebuggerProbeLabel, SelfHardening,
    };
    let modes = [
        DebuggerMode::Enabled,
        DebuggerMode::Disabled,
        DebuggerMode::Unrecognized,
        DebuggerMode::Unknown,
    ];
    let members = [
        DebuggerMember::Admin,
        DebuggerMember::Developer,
        DebuggerMember::NotMember,
        DebuggerMember::Unknown,
    ];
    let hardenings = [
        SelfHardening::Hardened,
        SelfHardening::NotHardened,
        SelfHardening::Unknown,
    ];
    let labels = [
        DebuggerProbeLabel::Pending,
        DebuggerProbeLabel::StatusOk,
        DebuggerProbeLabel::StatusUnrecognized,
        DebuggerProbeLabel::ToolAbsent,
        DebuggerProbeLabel::SpawnFailed,
        DebuggerProbeLabel::TimedOut,
        DebuggerProbeLabel::OutputUnreadable,
        DebuggerProbeLabel::RefusedDisabled,
        DebuggerProbeLabel::RefusedOutOfBundle,
        DebuggerProbeLabel::RefusedNoExe,
        DebuggerProbeLabel::UnsupportedPlatform,
    ];
    let outcomes = [
        None,
        Some(Outcome::Changed(DebuggerChange::On)),
        Some(Outcome::Changed(DebuggerChange::Off)),
        Some(Outcome::NotChanged(DebuggerChange::On)),
        Some(Outcome::Unrecognized(DebuggerChange::On)),
        Some(Outcome::Unobserved(DebuggerChange::Off)),
        Some(Outcome::NotDue(DebuggerChange::On, DebuggerMode::Enabled)),
        Some(Outcome::NotDue(DebuggerChange::On, DebuggerMode::Unknown)),
        Some(Outcome::NotStarted(DebuggerChange::Off)),
        Some(Outcome::PeerInFlight(DebuggerChange::On)),
    ];
    let refusals = [
        None,
        Some(Refusal::NoWindow),
        Some(Refusal::NotMacos),
        Some(Refusal::PrivacyOff),
        Some(Refusal::RecordsUnread),
        Some(Refusal::InFlight),
        Some(Refusal::NotConfirmed),
        Some(Refusal::Busy),
        Some(Refusal::State(DebuggerChange::On, DebuggerMode::Enabled)),
        Some(Refusal::State(DebuggerChange::Off, DebuggerMode::Disabled)),
        Some(Refusal::State(
            DebuggerChange::On,
            DebuggerMode::Unrecognized,
        )),
        Some(Refusal::State(DebuggerChange::On, DebuggerMode::Unknown)),
        Some(Refusal::CouldNotStart),
    ];
    let mut out = Vec::new();
    for mode in modes {
        for member in members {
            for hardening in hardenings {
                let mut base = debugger_facts(mode, member, hardening);
                out.push(base);
                for enabled in [false, true] {
                    for label in labels {
                        base.enabled = enabled;
                        base.probe.label = label;
                        out.push(base);
                    }
                }
                base = debugger_facts(mode, member, hardening);
                for inherited in [false, true] {
                    out.push(crate::debugger_access::DebuggerFacts {
                        in_flight: Some(InFlightFacts {
                            change: DebuggerChange::On,
                            since: 1_790_000_000,
                            inherited,
                        }),
                        busy: true,
                        ..base
                    });
                }
                for origin in [Origin::Aterm, Origin::Outside, Origin::Unknown] {
                    out.push(crate::debugger_access::DebuggerFacts {
                        recorded: Some(ObservedMarker {
                            mode,
                            since: 1_790_000_000,
                            origin,
                        }),
                        drift_since: Some(1_790_000_000),
                        ..base
                    });
                }
                for last_outcome in outcomes {
                    for refusal in refusals {
                        out.push(crate::debugger_access::DebuggerFacts {
                            last_outcome,
                            refusal,
                            ..base
                        });
                    }
                }
            }
        }
    }
    out
}

#[test]
fn the_debugger_row_follows_the_observed_state_table() {
    use aterm_containment::consent::{
        DebuggerChange, DebuggerMember, DebuggerMode, DebuggerProbeLabel, SelfHardening,
    };
    let button = |facts| debugger_row_copy(&debugger_access(facts)).button;
    let live = |change| {
        Some(DebuggerButton {
            change,
            enabled: true,
            busy: false,
        })
    };
    for member in [
        DebuggerMember::Admin,
        DebuggerMember::Developer,
        DebuggerMember::Unknown,
    ] {
        for hardening in [
            SelfHardening::Hardened,
            SelfHardening::NotHardened,
            SelfHardening::Unknown,
        ] {
            assert_eq!(
                button(debugger_facts(DebuggerMode::Disabled, member, hardening)),
                live(DebuggerChange::On),
                "{member:?}/{hardening:?}: O8 — offered whatever aterm's own hardening"
            );
            assert_eq!(
                button(debugger_facts(DebuggerMode::Enabled, member, hardening)),
                live(DebuggerChange::Off),
                "{member:?}/{hardening:?}: Turn Off only reduces exposure"
            );
        }
    }
    let hardened = |mode, member| debugger_facts(mode, member, SelfHardening::Hardened);
    assert_eq!(
        button(hardened(DebuggerMode::Disabled, DebuggerMember::NotMember)),
        None
    );
    assert_eq!(
        button(hardened(DebuggerMode::Unrecognized, DebuggerMember::Admin)),
        None,
        "-enable would overwrite that definition"
    );
    let mut unread = hardened(DebuggerMode::Unknown, DebuggerMember::Admin);
    for label in [DebuggerProbeLabel::ToolAbsent, DebuggerProbeLabel::Pending] {
        unread.probe.label = label;
        assert_eq!(button(unread), None, "{label:?}");
    }
    let mut off = hardened(DebuggerMode::Disabled, DebuggerMember::Admin);
    off.enabled = false;
    assert_eq!(button(off), None, "privacy checks off: aterm did not look");
    let mut drift = hardened(DebuggerMode::Disabled, DebuggerMember::Admin);
    drift.drift_since = Some(1_790_000_000);
    assert_eq!(button(drift), live(DebuggerChange::On));
    let mut flight = hardened(DebuggerMode::Disabled, DebuggerMember::Admin);
    flight.in_flight = Some(crate::debugger_access::InFlightFacts {
        change: DebuggerChange::On,
        since: 1_790_000_000,
        inherited: true,
    });
    flight.busy = true;
    assert_eq!(
        button(flight),
        Some(DebuggerButton {
            change: DebuggerChange::On,
            enabled: false,
            busy: true,
        })
    );
}

#[test]
fn the_debugger_button_is_live_exactly_when_a_press_is_taken() {
    use aterm_containment::consent::DebuggerChange;
    for facts in every_debugger_facts() {
        let copy = debugger_row_copy(&debugger_access(facts));
        for change in [DebuggerChange::On, DebuggerChange::Off] {
            let live = copy
                .button
                .is_some_and(|button| button.change == change && button.enabled);
            assert_eq!(
                live,
                debugger_press_refusal(&facts, change).is_none(),
                "{facts:?} {change:?}"
            );
        }
        if let Some(button) = copy.button {
            assert!(
                !(button.enabled && button.busy),
                "a busy button is never pressable: {facts:?}"
            );
        }
    }
}

fn press_debugger(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    action: &'static str,
) -> Option<String> {
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(action),
                value: None,
            }),
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    state.feedback.clone()
}

#[test]
fn a_confirmed_debugger_press_records_one_change_for_the_park() {
    use aterm_containment::consent::{DebuggerChange, DebuggerMember, DebuggerMode, SelfHardening};
    use std::sync::atomic::{AtomicUsize, Ordering};
    static ASKED: AtomicUsize = AtomicUsize::new(0);
    fn counting_yes(title: &str, body: &str, proceed: &str) -> Option<bool> {
        assert!(!title.is_empty() && !body.is_empty() && !proceed.is_empty());
        ASKED.fetch_add(1, Ordering::AcqRel);
        Some(true)
    }
    for (action, mode, change, hardening) in [
        (
            MACOS_ACCESS_DEBUGGER_ON,
            DebuggerMode::Disabled,
            DebuggerChange::On,
            SelfHardening::Hardened,
        ),
        (
            MACOS_ACCESS_DEBUGGER_ON,
            DebuggerMode::Disabled,
            DebuggerChange::On,
            SelfHardening::NotHardened,
        ),
        (
            MACOS_ACCESS_DEBUGGER_OFF,
            DebuggerMode::Enabled,
            DebuggerChange::Off,
            SelfHardening::NotHardened,
        ),
    ] {
        ASKED.store(0, Ordering::Release);
        let shared = SharedOwnerQuiet::default();
        let access = debugger_access(debugger_facts(mode, DebuggerMember::Admin, hardening));
        let open_view = || {
            let (mut runtime, instance, view) = setup();
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(SettingsRoute::Security);
                state.replace_macos_access(access.clone());
                state.arm_consent_gestures(ConsentGestures {
                    confirm: ConfirmArm::StandIn(counting_yes),
                    ..ConsentGestures::inert()
                });
                state.arm_owner_quiet(std::sync::Arc::clone(&shared));
            }
            (runtime, instance, view)
        };
        let (mut runtime, instance, view) = open_view();
        let context = format!("{action}/{hardening:?}");
        assert_eq!(
            press_debugger(&mut runtime, instance, view, action),
            None,
            "{context}"
        );
        assert!(
            press_debugger(&mut runtime, instance, view, action).is_some(),
            "{context}: a queued press is refused"
        );
        let (mut other, other_instance, other_view) = open_view();
        assert!(
            press_debugger(&mut other, other_instance, other_view, action).is_some(),
            "{context}: another view behind the same yes is refused"
        );
        assert_eq!(ASKED.load(Ordering::Acquire), 1, "{context}: one alert");
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        assert_eq!(
            state.take_debugger_change_request(),
            Some((change, OwnerAnswer::yes_for_test())),
            "{context}: the change, with the answer it was recorded under"
        );
        assert_eq!(
            state.take_debugger_change_request(),
            None,
            "{context}: drained"
        );
        let Some(AppViewState::Settings(other_state)) = other.view_state_mut(other_view) else {
            unreachable!();
        };
        assert_eq!(
            other_state.take_debugger_change_request(),
            None,
            "{context}: the queued press recorded nothing"
        );
        assert!(shared.lock().unwrap().has_confirmed_for_test());
        shared.lock().unwrap().settle_confirmed();
        assert!(!shared.lock().unwrap().has_confirmed_for_test());
    }
}

#[test]
fn a_debugger_press_the_row_does_not_offer_asks_nothing() {
    use aterm_containment::consent::{DebuggerMember, DebuggerMode, SelfHardening};
    use std::sync::atomic::{AtomicUsize, Ordering};
    static ASKED: AtomicUsize = AtomicUsize::new(0);
    fn counting_yes(_title: &str, _body: &str, _proceed: &str) -> Option<bool> {
        ASKED.fetch_add(1, Ordering::AcqRel);
        Some(true)
    }
    ASKED.store(0, Ordering::Release);
    let base = debugger_facts(
        DebuggerMode::Disabled,
        DebuggerMember::Admin,
        SelfHardening::Hardened,
    );
    let cases: Vec<(&str, Option<crate::debugger_access::DebuggerFacts>, &str)> = vec![
        (
            "privacy off",
            Some(crate::debugger_access::DebuggerFacts {
                enabled: false,
                ..base
            }),
            MACOS_ACCESS_DEBUGGER_ON,
        ),
        (
            "busy",
            Some(crate::debugger_access::DebuggerFacts { busy: true, ..base }),
            MACOS_ACCESS_DEBUGGER_ON,
        ),
        (
            "in flight",
            Some(crate::debugger_access::DebuggerFacts {
                busy: true,
                in_flight: Some(crate::debugger_access::InFlightFacts {
                    change: aterm_containment::consent::DebuggerChange::On,
                    since: 1,
                    inherited: false,
                }),
                ..base
            }),
            MACOS_ACCESS_DEBUGGER_ON,
        ),
        ("already off", Some(base), MACOS_ACCESS_DEBUGGER_OFF),
        (
            "already allowed",
            Some(debugger_facts(
                DebuggerMode::Enabled,
                DebuggerMember::Admin,
                SelfHardening::Hardened,
            )),
            MACOS_ACCESS_DEBUGGER_ON,
        ),
        (
            "unrecognised",
            Some(debugger_facts(
                DebuggerMode::Unrecognized,
                DebuggerMember::Admin,
                SelfHardening::Hardened,
            )),
            MACOS_ACCESS_DEBUGGER_ON,
        ),
        (
            "not a member",
            Some(debugger_facts(
                DebuggerMode::Disabled,
                DebuggerMember::NotMember,
                SelfHardening::Hardened,
            )),
            MACOS_ACCESS_DEBUGGER_ON,
        ),
        ("nothing published", None, MACOS_ACCESS_DEBUGGER_ON),
    ];
    for (context, facts, action) in cases {
        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Security);
            if let Some(facts) = facts {
                state.replace_macos_access(debugger_access(facts));
            }
            state.arm_consent_gestures(ConsentGestures {
                confirm: ConfirmArm::StandIn(counting_yes),
                ..ConsentGestures::inert()
            });
        }
        assert!(
            press_debugger(&mut runtime, instance, view, action).is_some(),
            "{context}: the refusal is said on the page"
        );
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        assert_eq!(state.take_debugger_change_request(), None, "{context}");
        assert!(
            !state
                .owner_quiet_for_test()
                .lock()
                .unwrap()
                .is_quiet_now_for_test(),
            "{context}: not asked is not a decline"
        );
    }
    assert_eq!(
        ASKED.load(Ordering::Acquire),
        0,
        "no alert for a press the row refuses"
    );
}

#[test]
fn the_debugger_alert_says_what_the_press_changes() {
    use aterm_containment::consent::{
        DEBUGGER_ACCESS_REVERT, DebuggerChange, DebuggerMember, DebuggerMode, SelfHardening,
    };
    fn laid_out(case: &str, body: &str) {
        for paragraph in body.split("\n\n") {
            let lines: Vec<&str> = paragraph.split('\n').collect();
            assert!(
                lines.len() == 1 || lines.iter().all(|l| l.starts_with("\u{2022} ")),
                "{case}: one line or a list of bullets: {paragraph:?}"
            );
            for line in lines {
                assert!(
                    !line.is_empty() && line.trim() == line,
                    "{case}: no empty or padded line in {body:?}"
                );
                assert!(
                    !line.starts_with('\u{2022}') || line.starts_with("\u{2022} "),
                    "{case}: a bullet line starts with the bullet and a space: {line:?}"
                );
                assert!(
                    line.chars().count() <= 150,
                    "{case}: a short line, not a wall: {line:?}"
                );
            }
        }
    }
    let measured = SpikeEvidence {
        devtools_enable_measured: true,
        ..SpikeEvidence::UNMEASURED
    };
    let facts_for = |mode, hardening| debugger_facts(mode, DebuggerMember::Admin, hardening);
    let hardenings = [
        SelfHardening::Hardened,
        SelfHardening::NotHardened,
        SelfHardening::Unknown,
    ];
    for hardening in hardenings {
        for evidence in [SpikeEvidence::UNMEASURED, measured] {
            let off = facts_for(DebuggerMode::Disabled, hardening);
            let (_, body, _) = debugger_access_alert(DebuggerChange::On, &off, evidence);
            let case = format!(
                "{hardening:?} measured={}",
                evidence.devtools_enable_measured
            );
            let (_, undo) = body.rsplit_once("\n\n").expect("paragraphs");
            assert!(
                undo.contains(DEBUGGER_ACCESS_REVERT),
                "{case}: the undo carries the revert line"
            );
            let bullet = debugger_alert_not_hardened_bullet(hardening);
            assert_eq!(
                bullet.is_some_and(|bullet| body.split('\n').any(|line| line == bullet)),
                off.not_hardened(),
                "{case}: what an unhardened aterm exposes, exactly when it is one"
            );
            assert_eq!(
                body.split('\n')
                    .filter(|line| line.contains("this aterm"))
                    .count(),
                1,
                "{case}: one line speaks of this aterm, so none contradicts it"
            );
            assert!(
                body.contains("SamplingTools"),
                "{case}: the dialog's name, before it asks"
            );
        }
        let off = facts_for(DebuggerMode::Disabled, hardening);
        let on = facts_for(DebuggerMode::Enabled, hardening);
        assert_ne!(
            debugger_access_alert(DebuggerChange::On, &off, SpikeEvidence::UNMEASURED),
            debugger_access_alert(DebuggerChange::On, &off, measured),
            "the measured evidence changes the On words"
        );
        assert_ne!(
            debugger_access_alert(DebuggerChange::Off, &on, SpikeEvidence::UNMEASURED),
            debugger_access_alert(DebuggerChange::Off, &on, measured),
            "and the Off words"
        );
        for evidence in [SpikeEvidence::UNMEASURED, measured] {
            for change in [DebuggerChange::On, DebuggerChange::Off] {
                let mode = if change == DebuggerChange::On {
                    DebuggerMode::Disabled
                } else {
                    DebuggerMode::Enabled
                };
                for member in [
                    DebuggerMember::Admin,
                    DebuggerMember::Developer,
                    DebuggerMember::NotMember,
                    DebuggerMember::Unknown,
                ] {
                    let facts = debugger_facts(mode, member, hardening);
                    if !facts.offers(change) {
                        continue;
                    }
                    let (_, body, _) = debugger_access_alert(change, &facts, evidence);
                    let case = format!(
                        "{change:?} {member:?} {hardening:?} measured={}",
                        evidence.devtools_enable_measured
                    );
                    laid_out(&case, &body);
                    assert!(
                        member == DebuggerMember::Admin || !body.contains("your admin"),
                        "{case}: an account that is not an admin is not told the admin \
                         password is its own"
                    );
                    let path = "/usr/sbin/DevToolsSecurity";
                    for (at, _) in body.match_indices(path) {
                        assert!(
                            body[at + path.len()..].starts_with(" -disable"),
                            "{case}: only the revert names the tool"
                        );
                    }
                }
            }
        }
    }
}

#[test]
fn owner_confirms_with_mints_a_yes_only_from_the_alert() {
    use std::sync::atomic::{AtomicUsize, Ordering};
    static ASKED: AtomicUsize = AtomicUsize::new(0);
    fn yes(_title: &str, _body: &str, _proceed: &str) -> Option<bool> {
        ASKED.fetch_add(1, Ordering::AcqRel);
        Some(true)
    }
    fn no(_title: &str, _body: &str, _proceed: &str) -> Option<bool> {
        ASKED.fetch_add(1, Ordering::AcqRel);
        Some(false)
    }
    fn unshown(_title: &str, _body: &str, _proceed: &str) -> Option<bool> {
        ASKED.fetch_add(1, Ordering::AcqRel);
        None
    }
    type Confirm = fn(&str, &str, &str) -> Option<bool>;
    let arm = |confirm: Confirm| ConsentGestures {
        confirm: ConfirmArm::StandIn(confirm),
        ..ConsentGestures::inert()
    };
    let quiet = SharedOwnerQuiet::default();
    let ask = |confirm: Confirm| {
        owner_confirms_with(&quiet, &arm(confirm), "Title?", "Body.", "Go\u{2026}")
    };
    assert_eq!(ask(unshown), OwnerAnswer::NotAsked);
    assert!(
        !quiet.lock().unwrap().quiet_now(),
        "nobody asked is no decline"
    );
    assert_eq!(ask(yes), OwnerAnswer::yes_for_test(), "the alert's yes");
    assert_eq!(ask(no), OwnerAnswer::No);
    assert!(quiet.lock().unwrap().quiet_now(), "a no quiets the block");
    assert_eq!(ASKED.load(Ordering::Acquire), 3);
    assert_eq!(ask(yes), OwnerAnswer::Quiet, "quieted: not asked");
    assert_eq!(ASKED.load(Ordering::Acquire), 3, "no alert while quiet");
    let (mut runtime, _instance, view) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    state.arm_owner_quiet(std::sync::Arc::clone(&quiet));
    state.arm_consent_gestures(arm(yes));
    assert_eq!(
        state.owner_confirms("Title?", "Body.", "Go"),
        OwnerAnswer::Quiet
    );
    assert_eq!(ASKED.load(Ordering::Acquire), 3);
}

#[test]
fn a_debugger_alert_answered_on_the_page_settles_the_step() {
    use aterm_containment::consent::{DebuggerMember, DebuggerMode, SelfHardening};
    fn yes(_title: &str, _body: &str, _proceed: &str) -> Option<bool> {
        Some(true)
    }
    fn no(_title: &str, _body: &str, _proceed: &str) -> Option<bool> {
        Some(false)
    }
    fn unshown(_title: &str, _body: &str, _proceed: &str) -> Option<bool> {
        None
    }
    let press = |action, mode, confirm: fn(&str, &str, &str) -> Option<bool>, quiet: bool| {
        let shared = SharedOwnerQuiet::default();
        if quiet {
            shared.lock().unwrap().note_decline();
        }
        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Security);
            state.replace_macos_access(debugger_access(debugger_facts(
                mode,
                DebuggerMember::Admin,
                SelfHardening::Hardened,
            )));
            state.arm_consent_gestures(ConsentGestures {
                confirm: ConfirmArm::StandIn(confirm),
                ..ConsentGestures::inert()
            });
            state.arm_owner_quiet(std::sync::Arc::clone(&shared));
        }
        press_debugger(&mut runtime, instance, view, action);
        shared.lock().unwrap().debugger_answered()
    };
    let (on, off) = (DebuggerMode::Disabled, DebuggerMode::Enabled);
    assert!(press(MACOS_ACCESS_DEBUGGER_ON, on, yes, false), "a yes");
    assert!(press(MACOS_ACCESS_DEBUGGER_ON, on, no, false), "a no");
    assert!(
        press(MACOS_ACCESS_DEBUGGER_OFF, off, yes, false),
        "a yes to off"
    );
    assert!(
        press(MACOS_ACCESS_DEBUGGER_OFF, off, no, false),
        "a no to off"
    );
    assert!(
        !press(MACOS_ACCESS_DEBUGGER_ON, on, unshown, false),
        "nobody saw it"
    );
    assert!(!press(MACOS_ACCESS_DEBUGGER_ON, on, yes, true), "quieted");
    assert!(
        !press(MACOS_ACCESS_DEBUGGER_ON, off, yes, false),
        "a press the row refuses"
    );
    let shared = SharedOwnerQuiet::default();
    shared.lock().unwrap().note_debugger_answered();
    shared.lock().unwrap().settle_confirmed();
    assert!(shared.lock().unwrap().debugger_answered(), "never settled");
}

#[test]
fn a_declined_debugger_alert_quiets_the_block_and_records_nothing() {
    use aterm_containment::consent::{DebuggerMember, DebuggerMode, SelfHardening};
    let facts = debugger_facts(
        DebuggerMode::Disabled,
        DebuggerMember::Admin,
        SelfHardening::Hardened,
    );
    let shared = SharedOwnerQuiet::default();
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Security);
        let mut access = debugger_access(facts);
        access.warmup_offered = true;
        state.replace_macos_access(access);
        state.arm_owner_quiet(std::sync::Arc::clone(&shared));
    }
    assert!(press_debugger(&mut runtime, instance, view, MACOS_ACCESS_DEBUGGER_ON).is_some());
    assert!(!shared.lock().unwrap().is_quiet_now_for_test());
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.arm_consent_gestures(ConsentGestures {
            confirm: ConfirmArm::StandIn(|_, _, _| Some(false)),
            ..ConsentGestures::inert()
        });
    }
    assert!(press_debugger(&mut runtime, instance, view, MACOS_ACCESS_DEBUGGER_ON).is_some());
    assert!(shared.lock().unwrap().is_quiet_now_for_test());
    let quieted = OwnerAnswer::Quiet.refusal("");
    assert_eq!(
        press_debugger(&mut runtime, instance, view, MACOS_ACCESS_WARM_UP).as_deref(),
        Some(quieted),
        "a debugger Cancel quiets the warm-up too"
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    assert_eq!(state.take_debugger_change_request(), None);

    let mut quiet = OwnerQuiet::default();
    assert!(!quiet.is_quiet_now_for_test());
    quiet.note_decline();
    assert!(
        quiet.is_quiet_now_for_test(),
        "an unchanged re-probe quiets like a Cancel"
    );
}

#[test]
fn the_macos_access_block_draws_the_rows_it_measures() {
    fn walk(node: &UiNode, out: &mut Vec<(String, Option<String>)>) {
        let text = match &node.content {
            UiContent::Text(spec) => Some(spec.text.clone()),
            _ => None,
        };
        out.push((node.key.as_str().to_string(), text));
        for child in &node.children {
            walk(child, out);
        }
    }
    crate::tray_raster::prepare_ui_fonts_for_direct_view_test();
    let line_height = 24.0_f32.max(20.0 * settings_text_scale());
    let baselines = AccessLead::ALL.map(|lead| {
        let mut access = debugger_access(crate::debugger_access::DebuggerFacts::default());
        access.debugger.enabled = false;
        macos_access_height(&access, lead, f32::INFINITY)
            - debugger_row_lines(&macos_access_copy(&access).debugger).len() as f32 * line_height
    });
    for facts in every_debugger_facts().into_iter().step_by(7) {
        for (lead, baseline) in AccessLead::ALL.into_iter().zip(baselines) {
            let access = debugger_access(facts);
            let card = macos_access_card(&access, lead, f32::INFINITY);
            let mut nodes = Vec::new();
            walk(&card, &mut nodes);
            let copy = macos_access_copy(&access);
            let lines = debugger_row_lines(&copy.debugger);
            let drawn = nodes
                .iter()
                .filter(|(key, text)| {
                    key.starts_with("settings/macos-access/debugger/") && text.is_some()
                })
                .count();
            assert_eq!(drawn, lines.len(), "{facts:?} lead={lead:?}");
            let actions = nodes
                .iter()
                .any(|(key, _)| key == "settings/macos-access/debugger/actions");
            assert_eq!(actions, copy.debugger.button.is_some(), "{facts:?}");
            if let Some(button) = copy.debugger.button {
                assert!(nodes.iter().any(|(key, _)| key == button.action()));
            }
            let expected = baseline
                + lines.len() as f32 * line_height
                + if actions {
                    scaled_control_height()
                } else {
                    0.0
                };
            let Length::Fixed(height) = card.layout.height else {
                panic!("{facts:?} lead={lead:?}: the card's height is fixed");
            };
            assert!((height - expected).abs() < 0.01, "{facts:?} lead={lead:?}");
        }
    }
}

#[test]
fn a_warm_up_refusal_is_drawn_and_outlasts_the_switch_that_caused_it() {
    use aterm_containment::FdaScope;
    let (mut runtime, _instance, view) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    state.navigate(SettingsRoute::Security);
    let access = MacosAccess {
        warmup_offered: true,
        ..access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown)
    };
    state.replace_macos_access(access.clone());
    state.record_consent_warmup_for_test();
    assert!(state.take_consent_warmup_request());
    let revision = state.common.presentation_revision;
    assert!(state.note_warmup_refused("the warm-up is off"));
    assert!(state.common.presentation_revision > revision, "drawn");
    let line = state.feedback.clone();
    assert!(
        line.as_deref()
            .is_some_and(|line| line.contains("the warm-up is off")),
        "the host's reason is on the page: {line:?}"
    );
    state.replace_macos_access(MacosAccess {
        enabled: false,
        warmup_offered: false,
        ..access
    });
    assert_eq!(state.feedback, line, "the reason outlasts the switch");
    state.navigate(SettingsRoute::Appearance);
    assert!(!state.note_warmup_refused("the warm-up is off"));
    assert_eq!(state.feedback, None, "no line on another page");
}

#[test]
fn the_trash_press_records_its_plan_once() {
    use aterm_containment::FdaScope;
    let press = |access: MacosAccess| {
        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Security);
            state.replace_macos_access(access);
            state.arm_consent_gestures(ConsentGestures::confirming());
        }
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(MACOS_ACCESS_TRASH),
                    value: None,
                }),
            )
            .unwrap();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        (state.take_claimant_retire_request(), state.feedback.clone())
    };
    let mut access = access_fixture(FdaState::Granted, DrClass::Identity, FdaScope::Unknown);
    access.claimants = Some(census_fixture(true));
    let (plan, said) = press(access.clone());
    assert_eq!(
        plan,
        Some(vec![std::path::PathBuf::from(
            "/Applications/aterm.app.rollback"
        )])
    );
    assert_eq!(
        said, None,
        "the block's status row says how the move goes, not the page-wide bar"
    );

    let (plan, said) = press(MacosAccess {
        retire_live: true,
        ..access.clone()
    });
    assert_eq!(plan, None);
    assert!(said.is_some_and(|s| s.contains("already moving")));

    let (plan, said) = press(MacosAccess {
        claimants: None,
        ..access
    });
    assert_eq!(plan, None);
    assert!(said.is_some_and(|s| s.contains("no other copy")));
}

#[test]
fn a_bundle_that_is_no_longer_there_is_named_on_the_panel() {
    use aterm_containment::{FdaScope, ImageAnchor};

    let healthy = access_fixture(FdaState::Granted, DrClass::Identity, FdaScope::Unknown);
    let copy = macos_access_copy(&healthy);
    assert_eq!(copy.anchor_fault, None, "a live anchor says nothing extra");
    assert!(
        !macos_access_card(&healthy, AccessLead::Whole, f32::INFINITY)
            .children
            .iter()
            .any(|child| child.key.as_str() == "settings/macos-access/anchor-fault")
    );

    for anchor in [ImageAnchor::Displaced, ImageAnchor::Deleted] {
        let mut broken = access_fixture(FdaState::Granted, DrClass::Identity, FdaScope::Unknown);
        broken.anchor = anchor;
        let copy = macos_access_copy(&broken);
        let fault = copy
            .anchor_fault
            .as_deref()
            .expect("a broken anchor is said");
        assert!(
            !copy.identity.contains(fault),
            "the fault is its own line, not a tail past the path's ellipsis"
        );
        for lead in AccessLead::ALL {
            let card = macos_access_card(&broken, lead, f32::INFINITY);
            let painted = card
                .children
                .iter()
                .find(|child| child.key.as_str() == "settings/macos-access/anchor-fault")
                .expect("the fault line is painted");
            let UiContent::Text(spec) = &painted.content else {
                panic!("the fault is a text line")
            };
            assert_eq!(spec.text, fault);
            assert_eq!(spec.style, StyleRef::Danger);
        }
    }

    for benign in [ImageAnchor::NotBundled, ImageAnchor::Unknown] {
        let mut access = access_fixture(FdaState::Granted, DrClass::Identity, FdaScope::Unknown);
        access.anchor = benign;
        assert!(
            macos_access_copy(&access).anchor_fault.is_none(),
            "{benign:?} is not a fault"
        );
    }
}

