#[test]
fn the_devtools_card_explains_itself_on_an_ordinary_window() {
    use aterm_containment::consent::{DevToolList, DevToolListLabel as LL, DevToolListing as Li};
    use aterm_containment::{DevToolProbe, DevToolProbeLabel, DevToolState};
    let probe = DevToolProbe {
        state: DevToolState::Unlisted,
        label: DevToolProbeLabel::Observed,
        requests: Some(1),
        not_allowed: Some(1),
        answered_at_ms: Some(DEVTOOLS_ANSWERED_AT_MS),
    };
    let lists = [
        devtools_list(Li::Absent, LL::Read, None, Some(2)),
        DevToolList::refused(LL::NoFullDiskAccess),
    ];
    for (width, height, whole) in [
        (1_419.0, 908.0, true),
        (774.0, 700.0, false),
        (1_280.0, 560.0, false),
    ] {
        for list in lists {
            let facts = DevToolsFacts {
                enabled: true,
                probe,
                answer_minutes: Some(1),
                list,
                grant: aterm_containment::consent::devtool_grant(&list, &probe),
                opened_minutes: None,
                declined: None,
            };
            let context = format!("{width}x{height} {:?}", list.label);
            let access = devtools_access(facts, SpikeEvidence::UNMEASURED);
            let (mut runtime, instance, view) = setup();
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(SettingsRoute::Security);
                assert!(state.replace_macos_access(access.clone()));
            }
            let cx = view_cx_at(width, height);
            let first = compile_settings_view(&runtime, instance, view, &cx);
            first.validate_parity().unwrap();
            let mut keys = vec![
                "settings/developer-tools".to_string(),
                "settings/macos-access/heading".to_string(),
            ];
            let mut lines: Vec<&str> = devtools_card_lines(&devtools_card_copy(&access))
                .into_iter()
                .map(|(key, ..)| key)
                .collect();
            lines.sort_by_key(|key| devtools_card_priority(key));
            assert!(lines.len() > 2, "{context}");
            let kept = if whole { lines.len() } else { 2 };
            keys.extend(
                lines
                    .iter()
                    .take(kept)
                    .map(|key| format!("settings/macos-access/devtools/{key}")),
            );
            for key in &keys {
                assert!(
                    first.semantic(&UiKey::new(key.as_str())).is_some(),
                    "{key} is on the first screen: {context}"
                );
            }
            let mut reached = false;
            each_screen(&mut runtime, instance, view, &cx, |compiled, _| {
                compiled.validate_parity().unwrap();
                reached |= compiled
                    .hits
                    .iter()
                    .any(|hit| hit.key == UiKey::new(MACOS_ACCESS_OPEN_FDA));
            });
            assert!(
                reached,
                "the list scrolls on to the block's actions row: {context}"
            );
        }
    }
}

#[test]
fn open_privacy_and_security_is_on_the_first_screen_at_every_size() {
    use aterm_containment::{FdaScope, ImageAnchor};
    let denied = || {
        let mut access = access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown);
        access.warmup_rows = denied_rows();
        access
    };
    let mut rebuilt = denied();
    rebuilt.dr = DrClass::Cdhash;
    let mut anchored = access_fixture(FdaState::Granted, DrClass::Identity, FdaScope::Unknown);
    anchored.anchor = ImageAnchor::Deleted;
    let mut copies = access_fixture(FdaState::Granted, DrClass::Identity, FdaScope::Unknown);
    copies.claimants = Some(census_fixture(true));
    let fixtures = [
        ("denied", denied()),
        (
            "granted",
            access_fixture(FdaState::Granted, DrClass::Identity, FdaScope::Unknown),
        ),
        ("rebuilt", rebuilt),
        ("anchor fault", anchored),
        ("other copies", copies),
    ];
    for (name, access) in &fixtures {
        let card = macos_access_card(access, AccessLead::Whole, f32::INFINITY);
        let actions = card
            .children
            .iter()
            .position(|child| child.key.as_str() == "settings/macos-access/actions")
            .expect("the actions row");
        for detail in ["grants", "lasts", "probe", "identity", "responsible"] {
            for lead in AccessLead::ALL {
                let card = macos_access_card(access, lead, f32::INFINITY);
                let at = card
                    .children
                    .iter()
                    .position(|child| {
                        child.key.as_str() == format!("settings/macos-access/{detail}")
                    })
                    .unwrap_or_else(|| panic!("{name}: {detail} at every lead ({lead:?})"));
                assert!(at > actions, "{name}: {detail} is under the actions row");
            }
        }
    }
    let (held, cannot) = (
        std::sync::atomic::AtomicUsize::new(0),
        std::sync::atomic::AtomicUsize::new(0),
    );
    let held_at = std::sync::Mutex::new(BTreeSet::new());
    at_each_text_scale(&[1.0, 1.5, 2.0], "Open Privacy & Security", |scale| {
        for (name, access) in &fixtures {
            for (width, height) in [
                (444.0, 348.0),
                (584.0, 348.0),
                (624.0, 348.0),
                (738.0, 418.0),
                (584.0, 292.0),
                (444.0, 292.0),
                (1_074.0, 348.0),
                (1_074.0, 300.0),
                (1_074.0, 684.0),
                (1_193.0, 516.0),
                (1_564.0, 852.0),
                (1_280.0, 700.0),
                (1_280.0, 800.0),
                (1_280.0, 900.0),
            ] {
                let (width, height) = (width * scale, height * scale);
                let context = format!("{name} {width}x{height} at {scale}x");
                let (mut runtime, instance, view) = setup();
                {
                    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                        unreachable!();
                    };
                    state.navigate(SettingsRoute::Security);
                    assert!(state.replace_macos_access(access.clone()));
                }
                let cx = view_cx_at(width, height);
                let first = compile_settings_view(&runtime, instance, view, &cx);
                first.validate_parity().unwrap();
                let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
                    unreachable!();
                };
                let class = SettingsWidth::for_viewport(width);
                let text_width = settings_card_text_width(cx.viewport, class);
                let room = fields_page_list_room(state, class, cx.viewport);
                let least = scaled_control_height()
                    + 24.0
                    + settings_page_gap(state, class, cx.viewport)
                    + macos_access_reach(access, AccessLead::State, text_width, Some(1));
                let whole = |key: &str| {
                    first
                        .paint
                        .iter()
                        .find(|node| node.key.as_str() == key)
                        .is_some_and(|node| {
                            (node.clip.height - node.rect.height).abs() < 0.5
                                && first.hits.iter().any(|hit| {
                                    hit.key == UiKey::new(key)
                                        && (hit.rect.height - node.rect.height).abs() < 0.5
                                })
                        })
                };
                if least <= room + 0.01 {
                    held.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                    held_at
                        .lock()
                        .unwrap()
                        .insert(format!("{name} {width}x{height} at {scale}x"));
                    for key in [MACOS_ACCESS_OPEN_FDA, MACOS_ACCESS_OPEN_DEVTOOLS] {
                        assert!(
                            whole(key),
                            "{context}: {key} is whole and live on the first screen \
                             (it needs {least}pt of the list's {room}pt)"
                        );
                    }
                } else {
                    cannot.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                }
                if macos_access_lead(state, class, cx.viewport, access) == AccessLead::Whole {
                    let top = |key: &str| {
                        first
                            .semantic(&UiKey::new(key))
                            .unwrap_or_else(|| panic!("{context}: {key}"))
                            .rect
                            .y
                    };
                    assert!(
                        top("settings/macos-access/trade") < top(MACOS_ACCESS_OPEN_FDA),
                        "{context}: the trade over the row"
                    );
                }
                let elided = first
                    .paint_audit_lines()
                    .into_iter()
                    .filter(|line| line.contains("overflow=true"))
                    .filter(|line| line.contains("key=\"settings/macos-access/"))
                    .collect::<Vec<_>>();
                assert!(elided.is_empty(), "{context}: {elided:#?}");
            }
        }
    });
    let held_at = held_at.into_inner().unwrap();
    for (name, _) in &fixtures {
        assert!(
            held_at.contains(&format!("{name} 1074x348 at 1x")),
            "{name}: 1074x348 holds the press: {held_at:?}"
        );
    }
    for at in ["584x292", "444x292"] {
        assert!(
            held_at.contains(&format!("anchor fault {at} at 1x")),
            "a broken anchor at {at} holds the press: {held_at:?}"
        );
    }
    assert!(held.into_inner() > 0);
    assert!(cannot.into_inner() > 0);
}

#[test]
fn the_macos_access_block_is_reachable_on_a_short_landscape_window() {
    use aterm_containment::FdaScope;
    let access = access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown);
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Security);
        assert!(state.replace_macos_access(access.clone()));
    }
    let cx = view_cx_at(624.0, 348.0);
    let at = |runtime: &mut NativeRuntime, page: usize| {
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.scroll_page_to(page);
        }
        let compiled = compile_settings_view(runtime, instance, view, &cx);
        compiled.validate_parity().unwrap();
        compiled
    };
    let first = at(&mut runtime, 0);
    assert!(
        first
            .semantic(&UiKey::new("settings/developer-tools"))
            .is_some(),
        "the list leads with the DEVELOPER TOOLS card"
    );
    for key in [MACOS_ACCESS_OPEN_DEVTOOLS, MACOS_ACCESS_OPEN_FDA] {
        assert!(
            first.hits.iter().any(|hit| hit.key == UiKey::new(key)),
            "{key} is a hit target on the first screen"
        );
    }
    assert!(
        first
            .semantic(&UiKey::new("settings/macos-access/heading"))
            .is_some(),
        "the block follows the card on the first screen"
    );
    let compiled = at(&mut runtime, 1);
    assert!(
        compiled
            .semantic(&UiKey::new("settings/macos-access/heading"))
            .is_some(),
        "the second stop leads with the block"
    );
    assert!(
        compiled
            .semantic(&UiKey::new(MACOS_ACCESS_OPEN_FDA))
            .is_some(),
        "and its Open Privacy & Security button is a hit target there"
    );
    let mut rows = false;
    each_screen(&mut runtime, instance, view, &cx, |compiled, _| {
        compiled.validate_parity().unwrap();
        rows |= compiled
            .semantics
            .iter()
            .any(|node| node.key.as_str().starts_with("settings/row/"));
    });
    assert!(rows, "the list reaches a permission toggle");
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.scroll_page_to(0);
    }
    let tall_cx = view_cx_at(1_280.0, 900.0);
    let mut carried = BTreeSet::new();
    each_screen(&mut runtime, instance, view, &tall_cx, |compiled, _| {
        compiled.validate_parity().unwrap();
        carried.extend(
            compiled
                .semantics
                .iter()
                .map(|node| node.key.as_str().to_string()),
        );
    });
    for key in [
        "settings/macos-access/identity",
        "settings/macos-access/responsible",
        "settings/macos-access/service/0",
        "settings/macos-access/service/6",
        MACOS_ACCESS_OPEN_FDA,
        MACOS_ACCESS_OPEN_DEVTOOLS,
    ] {
        assert!(carried.contains(key), "{key}");
    }
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.scroll_page_to(0);
    }
    let tall = compile_settings_view(&runtime, instance, view, &tall_cx);
    tall.validate_parity().unwrap();
    let top = |key: &str| {
        tall.semantic(&UiKey::new(key))
            .unwrap_or_else(|| panic!("{key}"))
            .rect
            .y
    };
    assert!(
        top("settings/developer-tools") < top("settings/macos-access/heading"),
        "the DEVELOPER TOOLS card leads the page"
    );
}

#[test]
fn the_reset_offer_follows_the_denials_the_identity_the_tool_and_the_subject() {
    use aterm_containment::FdaScope;
    let denied = |dr| {
        let mut access = access_fixture(FdaState::Denied, dr, FdaScope::Unknown);
        access.warmup_rows = denied_rows();
        access
    };
    let actions = |access: &MacosAccess| -> Vec<UiKey> {
        macos_access_card(access, AccessLead::Whole, f32::INFINITY)
            .children
            .iter()
            .find(|node| node.key == UiKey::new("settings/macos-access/actions"))
            .expect("the action rows")
            .children
            .iter()
            .flat_map(|row| row.children.iter().map(|node| node.key.clone()))
            .collect()
    };
    let ask_again = UiKey::new(MACOS_ACCESS_ASK_AGAIN);
    let open_files = UiKey::new(MACOS_ACCESS_OPEN_FILES);

    let access = denied(DrClass::Identity);
    assert_eq!(
        macos_access_copy(&access).folders.len(),
        Folder::ALL.len(),
        "one line per refused folder"
    );
    assert!(access.shows_reset_button());
    let keys = actions(&access);
    assert!(keys.contains(&open_files) && keys.contains(&ask_again));
    assert!(
        !MacosAccess {
            enabled: false,
            ..access.clone()
        }
        .shows_reset_button(),
        "checks off: no reset"
    );
    let quiet = MacosAccess {
        warmup_rows: Vec::new(),
        ..access
    };
    assert!(!quiet.shows_reset_button());
    assert!(
        !actions(&quiet).contains(&ask_again),
        "a reset is offered only for folders macOS actually refused"
    );

    for dr in [DrClass::Cdhash, DrClass::Unsigned] {
        let access = denied(dr);
        assert_eq!(access.reset_offer(), ResetOffer::ExplainRebuild, "{dr:?}");
        assert!(!access.shows_reset_button(), "{dr:?}");
        assert!(
            access.reset_plan().is_none(),
            "{dr:?}: no argv is even built"
        );
        assert!(
            macos_access_copy(&access).rebuild.is_some(),
            "{dr:?}: the rebuild is explained"
        );
        let keys = actions(&access);
        assert!(!keys.contains(&ask_again), "{dr:?}: no button at all");
        assert!(
            keys.contains(&open_files),
            "{dr:?}: the deep link stays — it is the repair that still works"
        );
    }
    let unknown = denied(DrClass::Unknown);
    assert_eq!(unknown.reset_offer(), ResetOffer::Offer);
    assert!(macos_access_copy(&unknown).rebuild.is_none());

    for tccutil in [
        TccutilPresence::Missing,
        TccutilPresence::NotExecutable,
        TccutilPresence::Unknown,
    ] {
        let access = MacosAccess {
            tccutil,
            ..denied(DrClass::Identity)
        };
        assert_eq!(access.reset_offer(), ResetOffer::HideNoTool, "{tccutil:?}");
        assert!(!access.shows_reset_button(), "{tccutil:?}");
    }
    let access = MacosAccess {
        bundle_id: None,
        ..denied(DrClass::Identity)
    };
    assert_eq!(access.reset_offer(), ResetOffer::HideNoBundleId);
    assert!(!access.shows_reset_button());
}

#[test]
fn the_reset_plan_names_the_running_bundle_and_only_the_refused_folders() {
    use crate::consent_warmup::WarmupRow;
    use aterm_containment::FdaScope;
    let mut access = access_fixture(FdaState::Denied, DrClass::Identity, FdaScope::Unknown);
    access.bundle_id = Some(fixture_subject("com.example.running"));
    access.warmup_rows = vec![
        (Folder::Documents, WarmupRow::Denied),
        (Folder::Desktop, WarmupRow::Allowed),
        (Folder::Downloads, WarmupRow::Denied),
    ];
    let plan = access.reset_plan().expect("a plan for the refused folders");
    assert_eq!(plan.bundle_id(), "com.example.running");
    assert_eq!(plan.folders(), &[Folder::Documents, Folder::Downloads]);
    for (folder, argv) in plan.commands() {
        assert_eq!(
            argv.len(),
            4,
            "{folder:?}: the dangerous every-app form is unreachable"
        );
        assert_eq!(argv[3], "com.example.running");
        assert!(argv.contains(&folder.tcc_service().to_string()));
    }
}

#[test]
fn a_partial_reset_is_reported_as_partial_with_one_line_per_failure() {
    let all = MacosAccessReset::from_attempts(&[
        ResetAttempt::from_exit_status(Folder::Documents, Some(0)),
        ResetAttempt::from_exit_status(Folder::Desktop, Some(0)),
    ]);
    assert_eq!(all.outcome, ResetOutcome::AllReset);
    let lines = macos_access_reset_lines(&all, true);
    assert!(lines[0].contains("every folder asked"));
    assert_eq!(lines.len(), 1, "nothing declined, so no failure line");

    let partial = MacosAccessReset::from_attempts(&[
        ResetAttempt::from_exit_status(Folder::Documents, Some(0)),
        ResetAttempt::from_exit_status(Folder::Desktop, Some(1)),
        ResetAttempt::from_exit_status(Folder::Downloads, None),
    ]);
    assert_eq!(partial.outcome, ResetOutcome::Partial);
    let lines = macos_access_reset_lines(&partial, true);
    assert!(
        !lines[0].contains("every folder"),
        "a partial success never speaks for the set: {}",
        lines[0]
    );
    assert!(lines[0].contains("Documents"));
    assert!(!lines[0].contains("Desktop"));
    assert_eq!(lines.len(), 3, "one line per declined invocation");
    assert!(lines[1].contains("Desktop") && lines[1].contains("exit status 1"));
    assert!(lines[2].contains("Downloads") && lines[2].contains("signal"));

    let none = MacosAccessReset::from_attempts(&[ResetAttempt::from_exit_status(
        Folder::Documents,
        Some(70),
    )]);
    assert_eq!(none.outcome, ResetOutcome::NoneReset);
    assert!(macos_access_reset_lines(&none, true)[0].contains("cleared no saved answer"));

    let absent = MacosAccessReset::from_attempts(&[ResetAttempt::tool_absent(Folder::Documents)]);
    assert_eq!(absent.outcome, ResetOutcome::ToolAbsent);
    assert!(
        absent.declined.is_empty(),
        "an absent tool is not a decline"
    );

    assert_eq!(
        MacosAccessReset::from_attempts(&[]).outcome,
        ResetOutcome::NotAttempted
    );
    assert!(macos_access_reset_lines(&MacosAccessReset::from_attempts(&[]), true).is_empty());
}

#[test]
fn an_unpublished_or_unarmed_settings_view_reaches_no_os_consent_surface() {
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Security);
        assert!(
            state.macos_access.is_none(),
            "nothing is published until a windowed host publishes it"
        );
        assert!(
            !state.consent_gestures.is_live(),
            "a view is born with the arms that cannot reach the OS"
        );
        assert!(!prefers_macos_access(state));
    }
    let cx = view_cx_at(1_280.0, 900.0);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    for key in [
        "settings/macos-access",
        "settings/developer-tools",
        MACOS_ACCESS_OPEN_DEVTOOLS,
    ] {
        assert!(
            compiled.semantic(&UiKey::new(key)).is_none(),
            "no card, and therefore no button, on an unpublished view: {key}"
        );
    }

    assert!(
        !ConsentGestures::inert().is_live(),
        "the default arms are the inert ones"
    );
    assert_eq!(
        (ConsentGestures::inert().open_settings)(crate::menu::PrivacyPane::FullDiskAccess),
        crate::menu::SettingsOpen::Refused
    );
    let plan = ResetPlan::new(&fixture_subject("com.example.fixture"), Folder::ALL).unwrap();
    let attempts = (ConsentGestures::inert().run_reset)(&plan);
    assert_eq!(attempts.len(), Folder::ALL.len());
    assert_eq!(
        MacosAccessReset::from_attempts(&attempts).outcome,
        ResetOutcome::ToolAbsent,
        "the inert arm reports that nothing ran, never that a reset happened"
    );
}

fn devtools_access(facts: DevToolsFacts, evidence: SpikeEvidence) -> MacosAccess {
    MacosAccess {
        devtools: facts,
        evidence,
        ..access_fixture(
            FdaState::Granted,
            DrClass::Identity,
            aterm_containment::FdaScope::Unknown,
        )
    }
}

const DEVTOOLS_ANSWERED_AT_MS: i64 = 1_791_381_501_820;

fn devtools_list(
    listing: aterm_containment::consent::DevToolListing,
    label: aterm_containment::consent::DevToolListLabel,
    modified_at_s: Option<i64>,
    rows: Option<u32>,
) -> aterm_containment::consent::DevToolList {
    aterm_containment::consent::DevToolList {
        listing,
        label,
        modified_at_s,
        rows,
    }
}

fn every_devtools_list() -> Vec<aterm_containment::consent::DevToolList> {
    use aterm_containment::consent::{DevToolList, DevToolListLabel as LL, DevToolListing as Li};
    vec![
        devtools_list(Li::On, LL::Read, Some(1_791_000_000), Some(2)),
        devtools_list(Li::On, LL::Read, Some(1_792_000_000), Some(2)),
        devtools_list(Li::Off, LL::Read, Some(1_791_000_000), Some(2)),
        devtools_list(Li::Off, LL::Read, Some(1_792_000_000), Some(2)),
        devtools_list(Li::Absent, LL::Read, None, Some(2)),
        devtools_list(Li::Absent, LL::Read, None, Some(0)),
        DevToolList::refused(LL::NoFullDiskAccess),
        DevToolList::refused(LL::TimedOut),
        DevToolList::pending(),
        DevToolList::refused(LL::RefusedDisabled),
    ]
}

fn every_devtools_facts() -> Vec<DevToolsFacts> {
    use aterm_containment::{DevToolProbe, DevToolProbeLabel as L, DevToolState as S};
    let labels = [
        L::Pending,
        L::Observed,
        L::NoRecentRequest,
        L::LogUnavailable,
        L::LogFailed,
        L::FormatUnrecognized,
        L::TimedOut,
        L::SpawnFailed,
        L::OutputUnreadable,
        L::RefusedDisabled,
        L::RefusedObserverOff,
        L::RefusedOutOfBundle,
        L::RefusedNoExe,
        L::RefusedNoSubject,
        L::UnsupportedPlatform,
    ];
    let mut out = Vec::new();
    let off_probe = DevToolProbe::refused(L::RefusedDisabled);
    let off_list = aterm_containment::consent::DevToolList::refused(
        aterm_containment::consent::DevToolListLabel::RefusedDisabled,
    );
    for opened_minutes in [None, Some(0), Some(30)] {
        out.push(DevToolsFacts {
            enabled: false,
            probe: off_probe,
            answer_minutes: None,
            list: off_list,
            grant: aterm_containment::consent::devtool_grant(&off_list, &off_probe),
            opened_minutes,
            declined: None,
        });
    }
    for label in labels {
        let observed = label == L::Observed;
        let states: &[S] = if observed {
            &[S::Allowed, S::Denied, S::Unlisted, S::Unknown]
        } else {
            &[S::Unknown]
        };
        let counts: &[Option<u32>] = if observed {
            &[None, Some(0), Some(1), Some(233)]
        } else {
            &[None, Some(233)]
        };
        let ages: &[Option<u64>] = if observed {
            &[None, Some(1), Some(45)]
        } else {
            &[None, Some(45)]
        };
        for &state in states {
            for &not_allowed in counts {
                for &answer_minutes in ages {
                    let probe = DevToolProbe {
                        state,
                        label,
                        requests: not_allowed,
                        not_allowed,
                        answered_at_ms: answer_minutes.map(|_| DEVTOOLS_ANSWERED_AT_MS),
                    };
                    for list in every_devtools_list() {
                        let read = list.label == aterm_containment::consent::DevToolListLabel::Read;
                        let opened: &[Option<u64>] = if read {
                            &[None, Some(30)]
                        } else {
                            &[None, Some(0), Some(30)]
                        };
                        for &opened_minutes in opened {
                            out.push(DevToolsFacts {
                                enabled: true,
                                probe,
                                answer_minutes,
                                list,
                                grant: aterm_containment::consent::devtool_grant(&list, &probe),
                                opened_minutes,
                                declined: None,
                            });
                        }
                    }
                }
            }
        }
    }
    out
}

#[test]
fn the_devtools_card_draws_what_it_measures() {
    fn walk(node: &UiNode, out: &mut Vec<String>) {
        out.push(node.key.as_str().to_string());
        for child in &node.children {
            walk(child, out);
        }
    }
    let line_height = 24.0_f32.max(20.0 * settings_text_scale());
    let heading = 28.0_f32.max(22.0 * settings_text_scale());
    let chrome = heading + scaled_control_height() + 24.0;
    let wide = DevToolsCardFit {
        text_width: 640.0,
        line_budget: 400,
    };
    let (mut state_whole, mut state_floor) = (0_usize, 0_usize);
    for facts in every_devtools_facts().into_iter().step_by(11) {
        let access = devtools_access(facts, SpikeEvidence::UNMEASURED);
        let copy = devtools_card_copy(&access);
        {
            let context = format!("{facts:?}");
            let (card, height) = devtools_card(&access, wide);
            assert_eq!(card.key, UiKey::new("settings/developer-tools"));
            assert_eq!(card.layout.height, Length::Fixed(height), "{context}");
            let mut keys = Vec::new();
            walk(&card, &mut keys);
            assert!(
                keys.iter().any(|key| key == MACOS_ACCESS_OPEN_DEVTOOLS),
                "{context}"
            );
            assert!(
                keys.iter()
                    .filter(|key| key.as_str() != "settings/developer-tools")
                    .all(|key| key.starts_with(MACOS_ACCESS_GESTURE_PREFIX)),
                "every key `act` could name is refused: {context}"
            );
            let lines = devtools_card_lines(&copy);
            let drawn = keys.iter().filter(|key| key.contains("/line-")).count();
            for (key, ..) in &lines {
                assert!(
                    keys.contains(&format!("settings/macos-access/devtools/{key}")),
                    "{key} is kept with room for everything: {context}"
                );
            }
            assert!(drawn >= lines.len(), "{context}");
            assert!(
                (height - (chrome + drawn as f32 * line_height)).abs() < 0.01,
                "{context}"
            );
            if copy.granted {
                assert_eq!(lines.len(), 2, "{context}");
            }
            let (short, short_height) = devtools_card(
                &access,
                DevToolsCardFit {
                    text_width: 300.0,
                    line_budget: 1,
                },
            );
            let mut short_keys = Vec::new();
            walk(&short, &mut short_keys);
            assert_eq!(
                short_keys
                    .iter()
                    .filter(|key| key.contains("/line-"))
                    .count(),
                1,
                "{context}"
            );
            assert!(
                short_keys.contains(&"settings/macos-access/devtools/state".to_string()),
                "{context}"
            );
            let state_line = {
                fn find(node: &UiNode) -> Option<String> {
                    if node.key == UiKey::new("settings/macos-access/devtools/state/line-0")
                        && let UiContent::Text(spec) = &node.content
                    {
                        return Some(spec.text.clone());
                    }
                    node.children.iter().find_map(find)
                }
                find(&short).expect("the state's line")
            };
            assert!(
                state_line == copy.state
                    || state_line == devtools_floor_state(copy.state_short, 300.0),
                "the state whole, or the floor's words: {state_line:?} {context}"
            );
            assert!(
                !state_line.ends_with('\u{2026}') || copy.state == state_line,
                "{context}"
            );
            if state_line == copy.state {
                state_whole += 1;
            } else {
                state_floor += 1;
            }
            assert!(
                short_keys
                    .iter()
                    .any(|key| key == MACOS_ACCESS_OPEN_DEVTOOLS),
                "the button stays: {context}"
            );
            assert!(
                (short_height - (chrome + line_height)).abs() < 0.01,
                "{context}"
            );
            let floor_text = |node: &UiNode| {
                fn find(node: &UiNode) -> Option<String> {
                    if node.key == UiKey::new("settings/macos-access/devtools/state")
                        && let UiContent::Text(spec) = &node.content
                    {
                        return Some(spec.text.clone());
                    }
                    node.children.iter().find_map(find)
                }
                find(node).expect("the floor's state")
            };
            let room = |width: f32| {
                width
                    - (crate::native_ui::native_button_label_width("Open Developer Tools\u{2026}")
                        + 28.0)
                    - 8.0
            };
            for width in [300.0, 640.0] {
                let (floor, _) = devtools_card(
                    &access,
                    DevToolsCardFit {
                        text_width: width,
                        line_budget: 0,
                    },
                );
                let text = floor_text(&floor);
                assert_eq!(
                    crate::native_ui::fit_native_text_label(&text, room(width)),
                    text,
                    "the floor's words are whole at {width}: {context}"
                );
                assert!(
                    text.to_lowercase().ends_with(copy.state_short),
                    "{text:?}: {context}"
                );
            }
            let (wide_floor, _) = devtools_card(
                &access,
                DevToolsCardFit {
                    text_width: 640.0,
                    line_budget: 0,
                },
            );
            assert!(
                floor_text(&wide_floor).starts_with("Developer Tools \u{2014} "),
                "named where it fits: {context}"
            );
            let (floor, floor_height) = devtools_card(
                &access,
                DevToolsCardFit {
                    text_width: 300.0,
                    line_budget: 0,
                },
            );
            let mut floor_keys = Vec::new();
            walk(&floor, &mut floor_keys);
            assert_eq!(
                floor_keys,
                [
                    "settings/developer-tools",
                    "settings/macos-access/devtools/actions",
                    "settings/macos-access/devtools/state",
                    MACOS_ACCESS_OPEN_DEVTOOLS,
                ],
                "{context}"
            );
            assert!(
                (floor_height - (scaled_control_height() + 24.0)).abs() < 0.01,
                "{context}"
            );
        }
        for lead in AccessLead::ALL {
            let mut keys = Vec::new();
            walk(&macos_access_card(&access, lead, f32::INFINITY), &mut keys);
            assert!(
                !keys
                    .iter()
                    .any(|key| key.starts_with("settings/macos-access/devtools")
                        || key == MACOS_ACCESS_OPEN_DEVTOOLS),
                "{facts:?} lead={lead:?}"
            );
        }
    }
    assert!(
        state_whole > 0 && state_floor > 0,
        "both forms drawn: {state_whole} whole, {state_floor} in the floor's words"
    );
    let shorts = every_devtools_facts()
        .into_iter()
        .map(|facts| {
            devtools_card_copy(&devtools_access(facts, SpikeEvidence::UNMEASURED)).state_short
        })
        .collect::<std::collections::BTreeSet<_>>();
    let room = 300.0
        - (crate::native_ui::native_button_label_width("Open Developer Tools\u{2026}") + 28.0)
        - 8.0;
    for short in shorts {
        let text = devtools_floor_state(short, room);
        assert_eq!(
            crate::native_ui::fit_native_text_label(&text, room),
            text,
            "{short:?} is whole at 300"
        );
    }
    let access = devtools_access(
        DevToolsFacts {
            enabled: true,
            list: aterm_containment::consent::DevToolList {
                listing: aterm_containment::consent::DevToolListing::Absent,
                label: aterm_containment::consent::DevToolListLabel::Read,
                modified_at_s: None,
                rows: Some(2),
            },
            grant: aterm_containment::DevToolGrant::NotGranted,
            ..DevToolsFacts::default()
        },
        SpikeEvidence::UNMEASURED,
    );
    let reading = ["state", "kind", "why", "how", "only", "route", "trade"];
    let priority = ["state", "how", "trade", "kind", "why", "route", "only"];
    let mut kept_before = 1;
    for budget in 1..200 {
        let (card, _) = devtools_card(
            &access,
            DevToolsCardFit {
                text_width: 640.0,
                line_budget: budget,
            },
        );
        let kept = card
            .children
            .iter()
            .filter_map(|child| {
                child
                    .key
                    .as_str()
                    .strip_prefix("settings/macos-access/devtools/")
            })
            .filter(|key| reading.contains(key))
            .collect::<Vec<_>>();
        let mut by_priority = kept.clone();
        by_priority.sort_by_key(|key| priority.iter().position(|p| p == key));
        assert_eq!(
            by_priority,
            priority[..kept.len()],
            "budget {budget}: a prefix of the priority order"
        );
        let positions = kept
            .iter()
            .map(|key| reading.iter().position(|name| name == key))
            .collect::<Vec<_>>();
        assert!(
            positions.windows(2).all(|w| w[0] < w[1]),
            "budget {budget}: reading order {kept:?}"
        );
        assert!(kept.len() >= kept_before, "budget {budget}: {kept:?}");
        kept_before = kept.len();
        if kept.len() == reading.len() {
            break;
        }
    }
    assert_eq!(
        kept_before,
        reading.len(),
        "every line fits a big enough budget"
    );
}

#[test]
fn the_developer_tools_button_asks_the_host_for_the_one_hand_over() {
    use crate::devtools_helper::{HandOver, Refusal};
    use std::sync::atomic::{AtomicU8, Ordering};
    static OPENS: AtomicU8 = AtomicU8::new(0);
    fn recording(_pane: crate::menu::PrivacyPane) -> crate::menu::SettingsOpen {
        OPENS.fetch_add(1, Ordering::AcqRel);
        crate::menu::SettingsOpen::Anchored
    }
    fn never_confirm(_: &str, _: &str, _: &str) -> Option<bool> {
        panic!("opening a pane changes nothing, so it asks nothing")
    }
    assert!(MACOS_ACCESS_OPEN_DEVTOOLS.starts_with(MACOS_ACCESS_GESTURE_PREFIX));
    let words = crate::menu::privacy_settings_path_words(crate::menu::PrivacyPane::DeveloperTools);
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Security);
        state.replace_macos_access(access_fixture(
            FdaState::Unknown,
            DrClass::Identity,
            aterm_containment::FdaScope::Unknown,
        ));
        state.arm_consent_gestures(ConsentGestures {
            open_settings: recording,
            confirm: ConfirmArm::StandIn(never_confirm),
            asks_devtools_hand_over: || true,
            ..ConsentGestures::inert()
        });
        assert!(
            !state.take_devtools_hand_over_request(),
            "nothing pressed yet"
        );
    }
    for _ in 0..2 {
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(MACOS_ACCESS_OPEN_DEVTOOLS),
                    value: None,
                }),
            )
            .unwrap();
    }
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    assert_eq!(
        state.feedback.as_deref(),
        Some(format!("Opening System Settings at {words}\u{2026}").as_str())
    );
    assert_eq!(
        OPENS.load(Ordering::Acquire),
        0,
        "the host opens it, not the reducer"
    );
    assert!(
        !state.take_consent_open_request(),
        "the Developer Tools pane is not the access card's Open Settings"
    );
    assert!(state.take_devtools_hand_over_request(), "one request");
    assert!(
        !state.take_devtools_hand_over_request(),
        "two presses before the park are one request"
    );
    for (outcome, said) in [
        (
            HandOver::Opened,
            "Opened System Settings \u{2014} look under",
        ),
        (
            HandOver::Listing,
            "Asking macOS to show the Developer Tools list",
        ),
        (
            HandOver::OpenFailed,
            "System Settings did not open. The setting is at",
        ),
        (
            HandOver::Headless,
            "System Settings did not open. The setting is at",
        ),
        (
            HandOver::Refused(Refusal::Declined),
            "System Settings did not open. The setting is at",
        ),
    ] {
        assert!(state.note_devtools_hand_over(outcome, None));
        let feedback = state.feedback.clone().expect("feedback");
        assert!(feedback.starts_with(said), "{outcome:?}: {feedback}");
        assert!(feedback.contains(words), "{outcome:?}: {feedback}");
    }
    assert!(state.note_devtools_hand_over(HandOver::Opened, Some("spctl exited 1")));
    let feedback = state.feedback.clone().expect("feedback");
    assert!(
        feedback.starts_with(
            "Opened System Settings, but macOS did not show the Developer Tools list \
             (spctl exited 1)."
        ) && feedback.contains(words),
        "{feedback}"
    );
    state.navigate(SettingsRoute::Appearance);
    let before = state.feedback.clone();
    assert!(!state.note_devtools_hand_over(HandOver::Opened, None));
    assert_eq!(state.feedback, before);

    for (published, armed) in [(false, true), (true, false)] {
        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Security);
            if published {
                state.replace_macos_access(access_fixture(
                    FdaState::Unknown,
                    DrClass::Identity,
                    aterm_containment::FdaScope::Unknown,
                ));
            }
            if armed {
                state.arm_consent_gestures(ConsentGestures {
                    asks_devtools_hand_over: || true,
                    ..ConsentGestures::inert()
                });
            }
        }
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(MACOS_ACCESS_OPEN_DEVTOOLS),
                    value: None,
                }),
            )
            .unwrap();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        let context = format!("published={published} armed={armed}");
        assert!(!state.take_devtools_hand_over_request(), "{context}");
        assert_eq!(
            state.feedback.as_deref(),
            Some(format!("System Settings did not open. The setting is at {words}.").as_str()),
            "{context}"
        );
    }
}

#[test]
fn an_async_access_check_preserves_the_security_pages_observed_facts() {
    use aterm_containment::FdaScope;
    let mut access = access_fixture(FdaState::Unknown, DrClass::Identity, FdaScope::Unknown);
    access.probe = ProbeLabel::Pending;
    let pending = macos_access_copy(&access);
    access.fda = FdaState::Denied;
    access.probe = ProbeLabel::OpenEperm;
    let denied = macos_access_copy(&access);
    assert_ne!(denied.headline, pending.headline);
    assert_eq!(denied.services, pending.services);
    assert_eq!(denied.identity, pending.identity);
    assert_eq!(denied.responsible, pending.responsible);
}

fn exiting_child(code: i32) -> aterm_uds::spawnfd::Command {
    if cfg!(windows) {
        let mut cmd = aterm_uds::spawnfd::command("cmd");
        cmd.args(["/c", &format!("exit {code}")]);
        cmd
    } else {
        aterm_uds::spawnfd::command(if code == 0 {
            "/usr/bin/true"
        } else {
            "/usr/bin/false"
        })
    }
}

fn never_exiting_child() -> aterm_uds::spawnfd::Command {
    let mut cmd = if cfg!(windows) {
        let mut cmd = aterm_uds::spawnfd::command("ping");
        cmd.args(["-n", "601", "127.0.0.1"]);
        cmd
    } else {
        let mut cmd = aterm_uds::spawnfd::command("/bin/sleep");
        cmd.arg("600");
        cmd
    };
    cmd.stdout(aterm_uds::spawnfd::Stdio::null());
    cmd
}

#[test]
fn a_reset_invocation_can_never_hold_the_main_thread_open_ended() {
    let ceiling = std::time::Duration::from_millis(150);
    let mut child = never_exiting_child()
        .spawn()
        .expect("spawn a child that will not exit on its own");

    let started = std::time::Instant::now();
    let code = wait_bounded(&mut child, ceiling);
    let waited = started.elapsed();

    assert!(
        waited < aterm_spec::wait::MUST_HAPPEN,
        "the bounded wait returned after {waited:?}; it must give up at the ceiling"
    );
    let killed = if cfg!(windows) { Some(1) } else { None };
    assert_eq!(
        code, killed,
        "a killed child reports what the host's kill leaves, which folds to a decline"
    );
    assert!(
        !ResetAttempt::from_exit_status(Folder::Documents, code).is_reset(),
        "a timed-out invocation must never read as a successful reset"
    );
}

#[test]
fn a_prompt_invocation_is_reported_by_its_own_exit_code() {
    const CEILING: std::time::Duration = std::time::Duration::from_secs(60);
    let started = std::time::Instant::now();
    let mut ok = exiting_child(0).spawn().expect("spawn the exit-0 child");
    assert_eq!(wait_bounded(&mut ok, CEILING), Some(0));

    let mut bad = exiting_child(1).spawn().expect("spawn the exit-1 child");
    let code = wait_bounded(&mut bad, CEILING);
    assert!(matches!(code, Some(n) if n != 0), "got {code:?}");
    assert!(!ResetAttempt::from_exit_status(Folder::Desktop, code).is_reset());
    let took = started.elapsed();
    assert!(
        took < aterm_spec::wait::MUST_HAPPEN,
        "two prompt children took {took:?}: the ceiling was spent as a delay"
    );
}

fn compile_settings_view(
    runtime: &NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    cx: &ViewCx<'_>,
) -> crate::native_ui::CompiledUi {
    runtime
        .render(instance, view, cx)
        .expect("Settings renders")
        .compile(cx.viewport)
        .expect("Settings compiles")
}

fn walk_open_choice_picker(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    cx: &ViewCx<'_>,
    key: &str,
    mut check: impl FnMut(&crate::native_ui::CompiledUi, usize),
) {
    let count = match runtime.view_state(view) {
        Some(AppViewState::Settings(state)) => state
            .choice_picker
            .as_ref()
            .expect("an open picker")
            .options
            .len(),
        _ => unreachable!(),
    };
    let prefix = format!("settings/choice/{key}/");
    let mut seen = BTreeSet::new();
    let _ = compile_settings_view(runtime, instance, view, cx);
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::TextInput(TextInputEvent::Home { extend: false }),
        )
        .unwrap();
    for index in 0..count {
        if index > 0 {
            runtime
                .dispatch(
                    instance,
                    view,
                    AppEvent::TextInput(TextInputEvent::Right { extend: false }),
                )
                .unwrap();
        }
        let compiled = compile_settings_view(runtime, instance, view, cx);
        let highlighted = UiKey::new(format!("{prefix}{index}"));
        assert!(
            compiled.hits.iter().any(|hit| hit.key == highlighted),
            "{key}: highlighted option {index} is on glass and pressable"
        );
        seen.extend(
            compiled
                .hits
                .iter()
                .filter(|hit| hit.key.as_str().starts_with(&prefix))
                .map(|hit| hit.key.as_str().to_string()),
        );
        check(&compiled, index);
    }
    assert_eq!(seen.len(), count, "{key}: every option is reachable");
}

#[test]
fn top_settings_rainbow_banner_present_and_yielding() {
    let key = UiKey::new("settings/top/rainbow");
    let (runtime, instance, view) = setup();
    let roomy = if crate::trail_audio::output_available() {
        1_000.0
    } else {
        1_050.0
    };
    let cx = view_cx_at(1_200.0, roomy);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let painted =
        |compiled: &crate::native_ui::CompiledUi| compiled.paint.iter().any(|node| node.key == key);
    assert!(
        painted(&compiled),
        "roomy Home page shows the rainbow banner"
    );
    assert!(
        compiled.semantic(&key).is_none(),
        "the banner is pure decoration: nothing for a screen reader to read out"
    );
    assert!(
        compiled.hits.iter().all(|hit| hit.key != key),
        "the banner has no action"
    );
    assert_zero_top_paint(&compiled, &format!("rainbow banner at 1200x{roomy} 1x"));

    let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_200.0, 700.0));
    assert!(!painted(&compiled), "short hosts must not gain the banner");

    let mut serious = view_cx_at(1_200.0, roomy);
    serious.motion = crate::native_app::ViewMotionCx {
        serious: true,
        ..crate::native_app::ViewMotionCx::default()
    };
    let compiled = compile_settings_view(&runtime, instance, view, &serious);
    assert!(!painted(&compiled), "Serious Mode must not show the banner");
}

