#[test]
fn top_card_preview_yields_only_for_a_control_row() {
    for (width, height) in [(584.0, 350.0), (738.0, 418.0), (1_193.0, 518.0)] {
        let cx = view_cx_at(width, height);
        let (runtime, _, view) = setup();
        let state = settings_state(&runtime, view);
        let layout = SettingsWidth::for_viewport(width);
        let text_width = settings_card_text_width(cx.viewport, layout);
        let natural = if height < 460.0 {
            96.0
        } else {
            renderer_preview_height(layout).min(132.0)
        };
        let gap = settings_page_gap(state, layout, cx.viewport);
        let body = settings_list_body_height(state, layout, cx.viewport);
        let (_, used) = pinned_heading(
            state,
            layout,
            cx.viewport,
            gap,
            "Top Settings",
            "Every control saves immediately.",
        );
        let room = (body - used).max(0.0);
        let cards = top_cards(
            state,
            layout,
            &cx,
            text_width,
            TopPreviews {
                theme: natural,
                text: natural,
                trail: natural,
            },
        );
        for card in cards {
            let key = card.key.clone();
            let fitted = constrain_top_split_card(card, room, 0.0, text_width);
            let Some(index) = fitted
                .rows
                .iter()
                .position(|(node, _)| matches!(node.content, UiContent::SettingsPreview(_)))
            else {
                continue;
            };
            let UiContent::SettingsPreview(spec) = &fitted.rows[index].0.content else {
                unreachable!();
            };
            let spec = (**spec).clone();
            let shown = fitted.rows[index].1;
            let floor = spec.minimum_height(48.0);
            let with = |height: f32| {
                let mut trial = fitted.clone();
                trial.rows[index].1 = height;
                trial
            };
            let at_floor = with(floor);
            let context = format!("{width}x{height} {key}: {shown}pt (floor {floor})");
            assert_eq!(
                fitted.first_screen_controls(room),
                at_floor.first_screen_controls(room),
                "{context}: the specimen cost a control"
            );
            if (shown - spec.whole_rows_at_most(natural)).abs() > 0.5 {
                let mut taller = shown + 1.0;
                while spec.whole_rows_at_most(taller) <= shown + 0.01 && taller < natural {
                    taller += 1.0;
                }
                let taller = spec.whole_rows_at_most(taller);
                let next = with(taller);
                let costs = if at_floor.height() <= room + 0.01 {
                    next.height() > room + 0.01
                } else {
                    next.first_screen_controls(room) < at_floor.first_screen_controls(room)
                };
                assert!(costs, "{context}: a {taller}pt specimen would cost nothing");
            }
        }
    }
}

#[test]
fn top_settings_cards_show_one_preview_each() {
    let (runtime, instance, view) = setup();
    for font_px in [12.0, 9.0] {
        for (width, height) in [(738.0, 418.0), (1_074.0, 684.0), (1_600.0, 900.0)] {
            let mut cx = view_cx_at(width, height);
            cx.terminal_font_px = font_px;
            let compiled = compile_settings_view(&runtime, instance, view, &cx);
            let context = format!("{width}x{height} at {font_px}px");
            let previews = compiled
                .semantics
                .iter()
                .filter(|node| node.label == "Appearance preview")
                .map(|node| node.key.as_str().to_string())
                .collect::<Vec<_>>();
            assert_eq!(
                previews,
                ["settings/top/theme/preview"],
                "one color preview at {context}"
            );
            let typography = compiled
                .semantics
                .iter()
                .filter(|node| node.label == "Typography preview")
                .map(|node| node.key.as_str().to_string())
                .collect::<Vec<_>>();
            assert!(
                typography.is_empty() || typography == ["settings/top/text/preview"],
                "one type specimen at {context}: {typography:?}"
            );
            let preview = compiled
                .semantic(&UiKey::new("settings/top/theme/preview"))
                .expect("color preview");
            if width >= 1_000.0 && font_px == 12.0 {
                let card = compiled
                    .semantic(&UiKey::new("settings/top/theme"))
                    .expect("colors card");
                let last = [
                    "settings/top/theme/preview".to_string(),
                    format!("settings/control/{}", prefs::EDIT_THEME),
                    format!("settings/control/{}", prefs::EDIT_WINDOW_THEME),
                ]
                .iter()
                .filter_map(|key| compiled.semantic(&UiKey::new(key.as_str())))
                .map(|node| node.rect.bottom())
                .fold(0.0, f32::max);
                assert!(
                    card.rect.bottom() - last <= 24.0,
                    "no blank band under the colors card's rows at {context}: card {:?}, rows end {last}",
                    card.rect
                );
                let usual = compiled
                    .paint
                    .iter()
                    .find_map(|node| match &node.content {
                        UiContent::SettingsPreview(spec)
                            if node.key.as_str() == "settings/top/theme/preview" =>
                        {
                            spec.color_sample_height_at_most(132.0)
                        }
                        _ => None,
                    })
                    .expect("the colour sample");
                assert!(
                    preview.rect.height + 0.01 >= usual,
                    "{context}: {:?} under {usual}",
                    preview.rect
                );
            }
            let whole = compiled
                .paint
                .iter()
                .find_map(|paint| match &paint.content {
                    UiContent::SettingsPreview(spec)
                        if paint.key.as_str() == "settings/top/theme/preview" =>
                    {
                        spec.whole_color_sample_height()
                    }
                    _ => None,
                })
                .expect("the colors card paints a color sample");
            assert!(
                preview.rect.height <= whole + 0.01,
                "{context}: a {}pt preview for a {whole}pt sample",
                preview.rect.height
            );
        }
    }
}

fn at_each_text_scale(rungs: &[f32], what: &str, rung: impl Fn(f32) + Sync) {
    let rung = &rung;
    let failed = std::thread::scope(|scope| {
        let runs = rungs
            .iter()
            .map(|&scale| {
                let run = std::thread::Builder::new()
                    .name(format!("{what} at {scale}\u{d7}"))
                    .stack_size(8 << 20)
                    .spawn_scoped(scope, move || {
                        crate::native_appearance::install_preferences(
                            crate::native_appearance::AppearancePreferences {
                                text_scale: scale,
                                ..crate::native_appearance::current_preferences()
                            },
                        );
                        rung(scale);
                    })
                    .unwrap_or_else(|error| panic!("launch {what} at {scale}\u{d7}: {error}"));
                (scale, run)
            })
            .collect::<Vec<_>>();
        runs.into_iter()
            .filter_map(|(scale, run)| {
                let payload = run.join().err()?;
                let said = payload
                    .downcast_ref::<String>()
                    .map(String::as_str)
                    .or_else(|| payload.downcast_ref::<&str>().copied())
                    .unwrap_or("a non-text panic");
                Some(format!("{scale}\u{d7} ({said})"))
            })
            .collect::<Vec<_>>()
    });
    assert!(failed.is_empty(), "{what} failed at {}", failed.join(", "));
}

const SWEEP_WORKERS: usize = 3;

fn on_workers<T: Sync + std::fmt::Debug>(items: &[T], what: &str, job: impl Fn(&T) + Sync) {
    on_n_workers(SWEEP_WORKERS, items, what, job);
}

fn on_n_workers<T: Sync + std::fmt::Debug>(
    workers: usize,
    items: &[T],
    what: &str,
    job: impl Fn(&T) + Sync,
) {
    let preferences = crate::native_appearance::current_preferences();
    let next = std::sync::atomic::AtomicUsize::new(0);
    let failed = std::sync::Mutex::new(Vec::new());
    std::thread::scope(|scope| {
        for worker in 0..workers.min(items.len()) {
            let (next, failed, job) = (&next, &failed, &job);
            std::thread::Builder::new()
                .name(format!("{what} worker {worker}"))
                .stack_size(8 << 20)
                .spawn_scoped(scope, move || {
                    crate::native_appearance::install_preferences(preferences);
                    loop {
                        let at = next.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                        let Some(item) = items.get(at) else {
                            return;
                        };
                        if let Err(payload) =
                            std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| job(item)))
                        {
                            let said = payload
                                .downcast_ref::<String>()
                                .map(String::as_str)
                                .or_else(|| payload.downcast_ref::<&str>().copied())
                                .unwrap_or("a non-text panic");
                            failed
                                .lock()
                                .unwrap_or_else(std::sync::PoisonError::into_inner)
                                .push(format!("{item:?} ({said})"));
                        }
                    }
                })
                .unwrap_or_else(|error| panic!("launch {what} worker {worker}: {error}"));
        }
    });
    let failed = failed
        .into_inner()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    assert!(failed.is_empty(), "{what} failed at {}", failed.join(", "));
}

fn sample_where_it_changes<T: PartialEq + Copy>(
    from: f32,
    to: f32,
    coarse: f32,
    resolution: f32,
    mut at: impl FnMut(f32) -> T,
) {
    let mut points = Vec::new();
    let mut x = from;
    while x <= to {
        points.push((x, at(x)));
        x += coarse;
    }
    let mut open: Vec<((f32, T), (f32, T))> = points
        .windows(2)
        .filter(|pair| pair[0].1 != pair[1].1)
        .map(|pair| (pair[0], pair[1]))
        .collect();
    while let Some(((lo, at_lo), (hi, at_hi))) = open.pop() {
        if hi - lo <= resolution {
            continue;
        }
        let mid = (lo + hi) / 2.0;
        let at_mid = at(mid);
        if at_mid != at_lo {
            open.push(((lo, at_lo), (mid, at_mid)));
        }
        if at_mid != at_hi {
            open.push(((mid, at_mid), (hi, at_hi)));
        }
    }
}

fn assert_zero_top_paint(compiled: &crate::native_ui::CompiledUi, context: &str) {
    compiled
        .validate_parity()
        .unwrap_or_else(|error| panic!("{context}: {error:?}"));
    let failures = compiled.fit_failures();
    assert!(
        failures.is_empty(),
        "{context}: renderer text overflow or clip:\n{}\n\nfull paint audit:\n{}",
        failures.join("\n"),
        compiled.paint_audit_lines().join("\n")
    );
    for node in compiled
        .semantics
        .iter()
        .filter(|node| node.action.is_some() && !node.offscreen)
    {
        assert!(
            node.rect.x >= compiled.bounds.x - 0.01
                && node.rect.y >= compiled.bounds.y - 0.01
                && node.rect.right() <= compiled.bounds.right() + 0.01
                && node.rect.bottom() <= compiled.bounds.bottom() + 0.01,
            "{context}: actionable {:?} escapes {:?}: {:?}",
            node.key,
            compiled.bounds,
            node.rect
        );
    }
}

fn assert_picker_descendants_contained(
    compiled: &crate::native_ui::CompiledUi,
    key: &str,
    context: &str,
) {
    let picker = compiled
        .semantic(&UiKey::new(format!("settings/choice-picker/{key}")))
        .unwrap_or_else(|| panic!("{context}: missing picker"));
    let contains = |rect: LogicalRect| {
        rect.x >= picker.rect.x - 0.01
            && rect.y >= picker.rect.y - 0.01
            && rect.right() <= picker.rect.right() + 0.01
            && rect.bottom() <= picker.rect.bottom() + 0.01
    };
    for node in compiled.semantics.iter().filter(|node| {
        node.key.as_str().starts_with("settings/choice/")
            || node.key.as_str() == "settings/choice-close"
    }) {
        assert!(
            contains(node.rect),
            "{context}: semantic {:?} escapes picker {:?}: {:?}",
            node.key,
            picker.rect,
            node.rect
        );
    }
    for hit in compiled.hits.iter().filter(|hit| {
        hit.key.as_str().starts_with("settings/choice/")
            || hit.key.as_str() == "settings/choice-close"
    }) {
        assert!(
            contains(hit.rect),
            "{context}: hit {:?} escapes picker {:?}: {:?}",
            hit.key,
            picker.rect,
            hit.rect
        );
    }
}

fn list_cuts(compiled: &crate::native_ui::CompiledUi, key: &UiKey) -> bool {
    let cut = |rect: LogicalRect, of: LogicalRect| {
        rect.y > of.y + 0.01 || rect.bottom() + 0.01 < of.bottom()
    };
    compiled.paint.iter().any(|paint| {
        paint.key == *key
            && paint.peek
            && (cut(paint.clip, paint.rect)
                || compiled
                    .semantic(key)
                    .is_some_and(|node| cut(node.rect, paint.rect)))
    })
}

fn row_name_scrolled_out(compiled: &crate::native_ui::CompiledUi, key: &str) -> bool {
    let suffix = format!("/{key}");
    let label = format!("settings/label/{key}");
    compiled.paint.iter().any(|paint| {
        paint.key.as_str().starts_with("settings/row/")
            && paint.key.as_str().ends_with(&suffix)
            && paint.clip.y > paint.rect.y + 0.01
    }) && !compiled
        .paint
        .iter()
        .any(|paint| paint.key.as_str() == label)
}

fn hit_matches_paint(
    compiled: &crate::native_ui::CompiledUi,
    hit: &crate::native_ui::HitRegion,
) -> bool {
    compiled.paint.iter().any(|paint| {
        paint.key == hit.key
            && (paint.rect == hit.rect
                || (list_cuts(compiled, &hit.key)
                    && hit.rect.x >= paint.clip.x - 0.01
                    && hit.rect.y >= paint.clip.y - 0.01
                    && hit.rect.right() <= paint.clip.right() + 0.01
                    && hit.rect.bottom() <= paint.clip.bottom() + 0.01))
    })
}

fn assert_material_hit(compiled: &crate::native_ui::CompiledUi, key: &str, context: &str) {
    let semantic = compiled
        .semantic(&UiKey::new(key))
        .unwrap_or_else(|| panic!("{context}: missing semantic action {key}"));
    assert!(
        semantic.action.is_some(),
        "{context}: {key} lost its semantic action"
    );
    let hit = compiled
        .hits
        .iter()
        .find(|hit| hit.key.as_str() == key)
        .unwrap_or_else(|| panic!("{context}: missing hit region {key}"));
    assert!(
        hit.rect.width >= 20.0 && hit.rect.height >= 20.0,
        "{context}: {key} is not a material hit target: {:?}",
        hit.rect
    );
    assert!(
        hit.rect.x >= compiled.bounds.x - 0.01
            && hit.rect.y >= compiled.bounds.y - 0.01
            && hit.rect.right() <= compiled.bounds.right() + 0.01
            && hit.rect.bottom() <= compiled.bounds.bottom() + 0.01,
        "{context}: {key} hit escapes {:?}: {:?}",
        compiled.bounds,
        hit.rect
    );
}

fn assert_all_hits_material_and_contained(compiled: &crate::native_ui::CompiledUi, context: &str) {
    for hit in &compiled.hits {
        assert!(
            list_cuts(compiled, &hit.key) || (hit.rect.width >= 20.0 && hit.rect.height >= 20.0),
            "{context}: {:?} is not a material hit target: {:?}",
            hit.key,
            hit.rect
        );
        assert!(
            hit.rect.x >= compiled.bounds.x - 0.01
                && hit.rect.y >= compiled.bounds.y - 0.01
                && hit.rect.right() <= compiled.bounds.right() + 0.01
                && hit.rect.bottom() <= compiled.bounds.bottom() + 0.01,
            "{context}: {:?} hit escapes {:?}: {:?}",
            hit.key,
            compiled.bounds,
            hit.rect
        );
    }
}

fn assert_short_landscape_geometry(
    compiled: &crate::native_ui::CompiledUi,
    scale: f32,
    context: &str,
) {
    const WIDTH: f32 = 568.0;
    const HEIGHT: f32 = 320.0;
    compiled
        .validate_parity()
        .unwrap_or_else(|error| panic!("{context}: {error:?}"));
    for semantic in compiled
        .semantics
        .iter()
        .filter(|semantic| semantic.action.is_some())
    {
        assert!(
            semantic.rect.x >= -0.01
                && semantic.rect.y >= -0.01
                && semantic.rect.right() <= WIDTH + 0.01
                && semantic.rect.bottom() <= HEIGHT + 0.01,
            "{context}: actionable semantic {:?} escapes the viewport: {:?}",
            semantic.key,
            semantic.rect
        );
        if scale >= 2.0 && !list_cuts(compiled, &semantic.key) {
            assert!(
                semantic.rect.height >= scaled_control_height_at_scale(2.0) - 0.01,
                "{context}: {:?} was clipped below its 2× control allocation: {:?}",
                semantic.key,
                semantic.rect
            );
        }
    }
    for hit in &compiled.hits {
        let paint = compiled
            .paint
            .iter()
            .find(|paint| paint.key == hit.key)
            .unwrap_or_else(|| panic!("{context}: {:?} has no paint", hit.key));
        assert!(
            hit_matches_paint(compiled, hit),
            "{context}: {:?} hit parity: paint {:?} clip {:?}, hit {:?}",
            hit.key,
            paint.rect,
            paint.clip,
            hit.rect
        );
        assert!(
            hit.rect.x >= -0.01
                && hit.rect.y >= -0.01
                && hit.rect.right() <= WIDTH + 0.01
                && hit.rect.bottom() <= HEIGHT + 0.01,
            "{context}: {:?} escapes the viewport: {:?}",
            hit.key,
            hit.rect
        );
    }
}

fn pager_totals(compiled: &crate::native_ui::CompiledUi) -> Vec<(String, usize)> {
    compiled
        .semantics
        .iter()
        .filter_map(|node| {
            let (window, total) = node.label.rsplit_once(" of ")?;
            let total = total.trim().parse::<usize>().ok()?;
            let numbered = window
                .strip_prefix("Page ")
                .map(|page| page.trim().parse::<usize>().is_ok())
                .unwrap_or_else(|| {
                    window.split_once('\u{2013}').is_some_and(|(first, last)| {
                        first.trim().parse::<usize>().is_ok()
                            && last.trim().parse::<usize>().is_ok()
                    })
                });
            numbered.then(|| (node.key.as_str().to_string(), total))
        })
        .collect()
}

#[test]
fn every_settings_list_bounds_the_reducer_at_its_last_full_screen() {
    at_each_text_scale(&[1.0, 1.25, 2.0], "Dynamic Type list-bound rung", |scale| {
        list_bound_sweep(scale)
    });
}

fn list_bound_sweep(scale: f32) {
    let (mut runtime, instance, view) = setup();
    const WIDTHS: [f32; 6] = [320.0, 480.0, 744.0, 760.0, 1040.0, 1200.0];
    const HEIGHTS: [f32; 9] = [98.0, 200.0, 240.0, 320.0, 420.0, 437.0, 522.0, 700.0, 900.0];
    let mut cell = 0usize;
    for (query, routes) in [
        ("", SettingsRoute::ALL.as_slice()),
        ("cursor", &[SettingsRoute::Home]),
        ("font", &[SettingsRoute::Home]),
        ("padding", &[SettingsRoute::Home]),
    ] {
        for route in routes.iter().copied() {
            for width in WIDTHS {
                for height in HEIGHTS {
                    cell += 1;
                    let cx = view_cx_at(width, height);
                    {
                        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view)
                        else {
                            unreachable!()
                        };
                        state.navigate(route);
                        state.search = query.to_string();
                        state.scroll_page_to(0);
                    }
                    let mut page = 0;
                    loop {
                        {
                            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view)
                            else {
                                unreachable!()
                            };
                            state.search = query.to_string();
                            state.scroll_page_to(page);
                        }
                        let compiled = compile_settings_view(&runtime, instance, view, &cx);
                        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
                            unreachable!()
                        };
                        let limit = state.result_page_limit.get();
                        assert!(pager_totals(&compiled).is_empty(), "no page has a pager");
                        if let Some(plan) = state.scroll_plan() {
                            let context = format!(
                                "{scale}× {} {width}×{height} screen {page}",
                                if query.is_empty() {
                                    route.path()
                                } else {
                                    "search"
                                }
                            );
                            assert_eq!(limit, Some(plan.limit()), "{context}: one bound");
                            let last = plan.limit();
                            assert_eq!(plan.screen(last).view.end, plan.len(), "{context}");
                            assert!(plan.ends_on(last) || last + 1 == plan.len(), "{context}");
                            assert!(
                                last == 0 || !plan.ends_on(last - 1),
                                "{context}: the last screen is full"
                            );
                        }
                        match limit {
                            Some(limit) if page < limit => {
                                page = if page == 0 && limit >= 2 {
                                    1 + cell % (limit - 1)
                                } else {
                                    limit
                                };
                            }
                            _ => break,
                        }
                    }
                }
            }
        }
    }
}

fn apply_real_config_patch(
    service: &mut VersionedConfigService,
    patch: &ConfigPatch,
) -> (ConfigSnapshot, Option<u64>) {
    let request = ConfigPatchRequest {
        base_revision: patch.base_revision,
        edits: patch
            .edits
            .iter()
            .map(|edit| ConfigKeyEdit {
                key: edit.key.clone(),
                expected: {
                    let ExpectedConfigValue::Exact(value) = &edit.expected;
                    ExpectedValue::Exact(value.clone())
                },
                value: edit.value.clone(),
            })
            .collect(),
    };
    match service.patch(request) {
        ConfigPatchResult::Applied { snapshot, undo } => (snapshot, Some(undo.get())),
        other => panic!("real config service rejected Settings patch: {other:?}"),
    }
}

fn attach_second_settings_view(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    snapshot: &ConfigSnapshot,
) -> crate::native_app::ViewId {
    let mut core_views = ViewStore::default();
    let _ = core_views.insert_native(instance).unwrap();
    let second = core_views.insert_native(instance).unwrap();
    runtime
        .attach_view(
            second,
            instance,
            AppViewState::Settings(Box::new(
                SettingsViewState::from_snapshot(snapshot).unwrap(),
            )),
        )
        .unwrap();
    second
}

fn enter_font_family_draft(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    draft: &str,
) {
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_FONT_FAMILY)),
                value: None,
            }),
        )
        .unwrap();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::TextInput(TextInputEvent::SelectAll),
        )
        .unwrap();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::TextInput(TextInputEvent::Commit(draft.to_string())),
        )
        .unwrap();
}

fn emitted_config_patch(outcome: &crate::native_app::DispatchOutcome) -> ConfigPatch {
    outcome
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::ConfigPatch { patch, .. } => Some(patch.clone()),
            _ => None,
        })
        .expect("one config patch")
}

#[test]
fn byte_equal_or_stale_snapshot_publications_preserve_active_settings_work() {
    let (mut runtime, instance, view) = setup();
    let mut service = VersionedConfigService::new(String::new()).unwrap();
    let snapshot = match service.patch(ConfigPatchRequest {
        base_revision: 1,
        edits: vec![ConfigKeyEdit {
            key: prefs::EDIT_THEME.to_string(),
            expected: ExpectedValue::Exact(None),
            value: Some("\"Nord\"".to_string()),
        }],
    }) {
        ConfigPatchResult::Applied { snapshot, .. } => snapshot,
        other => panic!("theme fixture patch failed: {other:?}"),
    };
    runtime
        .dispatch(instance, view, AppEvent::ConfigChanged(snapshot.clone()))
        .unwrap();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_THEME)),
                value: None,
            }),
        )
        .unwrap();
    let selected = match runtime.view_state(view).unwrap() {
        AppViewState::Settings(state) => state.choice_picker.as_ref().unwrap().selected,
        _ => panic!("Settings view"),
    };

    let mut environment_only = snapshot.clone();
    environment_only.analysis_generation = environment_only.analysis_generation.saturating_add(1);
    runtime
        .dispatch(instance, view, AppEvent::ConfigChanged(environment_only))
        .unwrap();
    let mut stale = snapshot.clone();
    stale.revision = 1;
    stale.analysis_generation = 1;
    runtime
        .dispatch(instance, view, AppEvent::ConfigChanged(stale))
        .unwrap();

    let AppViewState::Settings(state) = runtime.view_state(view).unwrap() else {
        panic!("Settings view");
    };
    assert_eq!(state.snapshot_revision, snapshot.revision);
    assert_eq!(
        state.raw_value(prefs::EDIT_THEME).as_deref(),
        Some("\"Nord\"")
    );
    assert_eq!(state.choice_picker.as_ref().unwrap().selected, selected);
}

#[test]
fn unrelated_two_view_publication_preserves_a_blurred_draft() {
    let mut service =
        VersionedConfigService::new("font_family = \"Committed Mono\"\n".to_string()).unwrap();
    let snapshot = service.snapshot();
    let (mut runtime, instance, first) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(first) else {
        unreachable!()
    };
    **state = SettingsViewState::from_snapshot(&snapshot).unwrap();
    state.navigate(SettingsRoute::TextFonts);
    let second = attach_second_settings_view(&mut runtime, instance, &snapshot);

    enter_font_family_draft(&mut runtime, instance, first, "Draft Mono");
    runtime
        .dispatch(
            instance,
            first,
            AppEvent::FocusChanged(Some(UiKey::new(format!(
                "settings/control/{}",
                prefs::EDIT_CURSOR_BLINK
            )))),
        )
        .unwrap();
    let AppViewState::Settings(state) = runtime.view_state(first).unwrap() else {
        unreachable!()
    };
    assert!(
        state.editing_field.is_none(),
        "premise: the draft is blurred"
    );

    let outcome = runtime
        .dispatch(
            instance,
            second,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_THEME)),
                value: Some(SemanticInput::Text("Nord".to_string())),
            }),
        )
        .unwrap();
    let patch = emitted_config_patch(&outcome);
    let (published, _) = apply_real_config_patch(&mut service, &patch);
    let feedback_before = {
        let AppViewState::Settings(state) = runtime.view_state(first).unwrap() else {
            unreachable!()
        };
        state.feedback.clone()
    };
    runtime
        .dispatch(instance, first, AppEvent::ConfigChanged(published))
        .unwrap();
    let AppViewState::Settings(state) = runtime.view_state(first).unwrap() else {
        unreachable!()
    };
    assert_eq!(
        state.field_inputs[prefs::EDIT_FONT_FAMILY].value(),
        "Draft Mono"
    );
    assert!(state.editing_field.is_none());
    assert_eq!(
        state.feedback, feedback_before,
        "an unrelated publication is not a draft conflict"
    );
    let presentation = runtime.presentation(instance, first).unwrap();
    assert!(presentation.indicators.dirty);
    assert!(!presentation.closable);
}

#[test]
fn same_key_two_view_publication_preserves_draft_and_requires_explicit_return() {
    let mut service =
        VersionedConfigService::new("font_family = \"Committed Mono\"\n".to_string()).unwrap();
    let snapshot = service.snapshot();
    let (mut runtime, instance, first) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(first) else {
        unreachable!()
    };
    **state = SettingsViewState::from_snapshot(&snapshot).unwrap();
    let second = attach_second_settings_view(&mut runtime, instance, &snapshot);
    enter_font_family_draft(&mut runtime, instance, first, "My Unsaved Mono");

    let outcome = runtime
        .dispatch(
            instance,
            second,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_FONT_FAMILY)),
                value: Some(SemanticInput::Text("External Mono".to_string())),
            }),
        )
        .unwrap();
    let patch = emitted_config_patch(&outcome);
    let (published, _) = apply_real_config_patch(&mut service, &patch);
    runtime
        .dispatch(instance, first, AppEvent::ConfigChanged(published))
        .unwrap();

    let AppViewState::Settings(state) = runtime.view_state(first).unwrap() else {
        unreachable!()
    };
    assert_eq!(
        state.editing_field.as_deref(),
        Some(prefs::EDIT_FONT_FAMILY)
    );
    assert_eq!(
        state.field_inputs[prefs::EDIT_FONT_FAMILY].value(),
        "My Unsaved Mono"
    );
    assert_eq!(
        state.raw_value(prefs::EDIT_FONT_FAMILY).as_deref(),
        Some("External Mono")
    );
    assert!(
        state
            .feedback
            .as_deref()
            .is_some_and(|message| message.contains("unsaved draft is preserved"))
    );

    let outcome = runtime
        .dispatch(instance, first, AppEvent::TextInput(TextInputEvent::Submit))
        .unwrap();
    let confirmation = emitted_config_patch(&outcome);
    assert_eq!(confirmation.edits.len(), 1);
    assert_eq!(confirmation.edits[0].key, prefs::EDIT_FONT_FAMILY);
    assert_eq!(
        confirmation.edits[0].expected,
        ExpectedConfigValue::Exact(Some("External Mono".to_string()))
    );
    assert_eq!(
        confirmation.edits[0].value.as_deref(),
        Some("My Unsaved Mono")
    );
}

