#[test]
fn visual_preview_matrix_covers_four_viewports_at_three_text_scales() {
    at_each_text_scale(
        &[1.0, 1.5, 2.0],
        "Settings viewport/scale matrix",
        visual_preview_matrix_covers_four_viewports_at_three_text_scales_at_scale,
    );
}

fn visual_preview_matrix_covers_four_viewports_at_three_text_scales_at_scale(scale: f32) {
    let mut renderer = aterm_render::Renderer::from_bytes(
        include_bytes!("../../aterm-render/tests/fixtures/jetbrains-mono.ttf"),
        14.0,
        aterm_render::Theme::default(),
    )
    .expect("matrix semantic renderer");
    renderer.set_runtime_font_discovery(false);
    renderer.prepare_semantic_typography("Bold Italic != => 你好 ∑✓♥ 😀 🚀 👩‍💻");
    crate::tray_raster::install_settled_chrome_fonts_for_test(renderer);

    let compile = |runtime: &NativeRuntime,
                   instance: crate::native_app::AppInstanceId,
                   view: crate::native_app::ViewId,
                   width: f32,
                   height: f32| {
        let mut cx = view_cx_at(width, height);
        let state = match runtime.view_state(view) {
            Some(AppViewState::Settings(state)) => state,
            _ => panic!("Settings view state"),
        };
        cx.semantic_font = state
            .preview_font_candidate(cx.animation_phase_ms, cx.motion, cx.terminal_font_px)
            .map(|candidate| crate::tray_raster::prepare_semantic_font(&candidate));
        runtime
            .render(instance, view, &cx)
            .expect("Settings renders")
            .compile(cx.viewport)
            .expect("Settings compiles")
    };
    let assert_whole =
        |compiled: &crate::native_ui::CompiledUi, width: f32, height: f32, context: &str| {
            compiled
                .validate_parity()
                .unwrap_or_else(|error| panic!("{context}: {error:?}"));
            for hit in &compiled.hits {
                let paint = compiled
                    .paint
                    .iter()
                    .find(|paint| paint.key == hit.key)
                    .unwrap_or_else(|| panic!("{context}: {:?} has no paint", hit.key));
                let parity_delta = (paint.rect.x - hit.rect.x).abs()
                    + (paint.rect.y - hit.rect.y).abs()
                    + (paint.rect.width - hit.rect.width).abs()
                    + (paint.rect.height - hit.rect.height).abs();
                assert!(
                    parity_delta < 0.001 || hit_matches_paint(compiled, hit),
                    "{context}: {:?} parity differs by {parity_delta}: paint={:?}, hit={:?}",
                    hit.key,
                    paint.rect,
                    hit.rect,
                );
                assert!(
                    hit.rect.x >= -0.01
                        && hit.rect.y >= -0.01
                        && hit.rect.right() <= width + 0.01
                        && hit.rect.bottom() <= height + 0.01,
                    "{context}: {:?} is clipped: {:?}",
                    hit.key,
                    hit.rect,
                );
            }
        };

    let viewports = [
        (624.0, 404.0),
        (320.0, 568.0),
        (390.0, 844.0),
        (568.0, 320.0),
        (1_280.0, 800.0),
    ];
    let routes = [
        SettingsRoute::Appearance,
        SettingsRoute::TextFonts,
        SettingsRoute::CursorMotion,
    ];
    for (width, height) in viewports {
        for route in routes {
            let (mut runtime, instance, view) = setup();
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!()
            };
            state.navigate(route);
            let compiled = compile(&runtime, instance, view, width, height);
            let context = format!("{} {width}×{height} at {scale}×", route.label());
            assert_whole(&compiled, width, height, &context);
            let preview_key = UiKey::new(format!("settings/preview{}", route.path()));
            let expected_height =
                renderer_preview_height(SettingsWidth::for_viewport_at_scale(width, scale));
            let preview = compiled.semantic(&preview_key);
            if preview.is_none() {
                assert!(
                    scale > 1.25 || height < 400.0,
                    "{context}: live preview is visible"
                );
            }
            if let Some(preview) = preview {
                if route == SettingsRoute::TextFonts && preview.rect.height >= expected_height {
                    assert!(
                        preview.rect.bottom() <= height + 0.01,
                        "{context}: whole specimen card"
                    );
                    let paint = compiled
                        .paint
                        .iter()
                        .find(|paint| paint.key == preview_key)
                        .unwrap();
                    let UiContent::SettingsPreview(spec) = &paint.content else {
                        unreachable!()
                    };
                    let mut prims = Vec::new();
                    spec.paint(
                        &mut prims,
                        paint.rect,
                        aterm_render::Theme::default(),
                        crate::settings::Roles::from_theme(aterm_render::Theme::default()),
                    );
                    let (y, specimen) = prims
                        .iter()
                        .find_map(|prim| match prim {
                            crate::widget::DrawPrim::TerminalSpecimen { y, spec, .. } => {
                                Some((*y, spec))
                            }
                            _ => None,
                        })
                        .expect("typography paints complete specimen rows");
                    if width == 624.0 && height == 404.0 && scale == 1.0 {
                        assert!(
                            specimen.input.rows >= 2,
                            "a short desktop window still shows whole specimen rows"
                        );
                    }
                    let pill_y = prims
                        .iter()
                        .find_map(|prim| match prim {
                            crate::widget::DrawPrim::Panel { y, radius, .. } if *radius == 6.0 => {
                                Some(*y)
                            }
                            _ => None,
                        })
                        .unwrap_or(paint.rect.bottom() - 10.0);
                    for dpi in [1.0, 1.25, 2.0, 3.0] {
                        let variations = specimen
                            .variations
                            .iter()
                            .map(|v| (v.tag, v.value()))
                            .collect::<Vec<_>>();
                        let row_h = specimen
                            .prepared_font
                            .specimen_cell_height(
                                specimen.font_px * dpi,
                                specimen.line_height,
                                &variations,
                            )
                            .unwrap() as f32
                            / dpi;
                        assert!(
                            y + specimen.input.rows as f32 * row_h <= pill_y - 4.0,
                            "{context} at {dpi}dpi: specimen rows never meet the status badge"
                        );
                    }
                } else {
                    let floor = compiled
                        .paint
                        .iter()
                        .find_map(|paint| match &paint.content {
                            UiContent::SettingsPreview(spec) if paint.key == preview_key => {
                                Some(spec.minimum_height(48.0))
                            }
                            _ => None,
                        })
                        .expect("the preview paints a specimen");
                    assert!(
                        preview.rect.height >= floor - 0.01,
                        "{context}: preview height is {:?}, floor {floor}",
                        preview.rect,
                    );
                    if route != SettingsRoute::TextFonts {
                        assert!(
                            preview.rect.height <= expected_height + 0.01,
                            "{context}: preview height is {:?}, natural {expected_height}",
                            preview.rect,
                        );
                    }
                }
            }

            assert!(
                compiled.semantics.iter().any(|node| {
                    node.parent
                        .as_ref()
                        .is_some_and(|parent| parent.as_str() == "settings/list")
                }),
                "{context}: the first screen holds more than the preview"
            );
            let section = route.section().expect("preview route has a section");
            let last_key = {
                let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
                    unreachable!()
                };
                let mut fields = state
                    .legacy
                    .fields
                    .iter()
                    .enumerate()
                    .filter(|(_, field)| prefs::section_of(field.key) == section)
                    .filter(|(_, field)| field_visible(field.key, false, false))
                    .filter(|(_, field)| {
                        !(route == SettingsRoute::TextFonts
                            && field.key == prefs::EDIT_DISPLAY_FONT)
                    })
                    .collect::<Vec<_>>();
                fields.sort_by_key(|(index, field)| (prefs::group_of(field.key).1, *index));
                fields.last().expect("preview route has fields").1.key
            };
            let last_control = UiKey::new(format!("settings/control/{last_key}"));
            let mut screen_cx = view_cx_at(width, height);
            screen_cx.semantic_font = {
                let state = match runtime.view_state(view) {
                    Some(AppViewState::Settings(state)) => state,
                    _ => panic!("Settings view state"),
                };
                state
                    .preview_font_candidate(
                        screen_cx.animation_phase_ms,
                        screen_cx.motion,
                        screen_cx.terminal_font_px,
                    )
                    .map(|candidate| crate::tray_raster::prepare_semantic_font(&candidate))
            };
            let mut reached_last = false;
            let screens = each_screen(&mut runtime, instance, view, &screen_cx, |screen, top| {
                assert_whole(screen, width, height, &format!("{context}, screen {top}"));
                reached_last |= screen.semantic(&last_control).is_some();
            });
            assert!(
                reached_last,
                "{context}: last field {last_key} is reachable in {screens} screens"
            );
        }

        let (mut runtime, instance, view) = setup();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.set_search("font".to_string());
        state.common.last_focus = Some(UiKey::new("settings/search"));
        let searched = compile(&runtime, instance, view, width, height);
        let context = format!("font search {width}×{height} at {scale}×");
        assert_whole(&searched, width, height, &context);
        assert!(
            searched
                .semantic(&UiKey::new("settings/preview/search"))
                .is_some()
                || ((scale > 1.25 || height < 400.0)
                    && searched.semantics.iter().any(|node| {
                        node.parent
                            .as_ref()
                            .is_some_and(|parent| parent.as_str() == "settings/list")
                    })),
            "{context}: global search retains the matching contextual preview"
        );
        assert!(
            searched.semantic(&UiKey::new("settings/search")).is_some(),
            "{context}: the full search surface remains present"
        );
    }
}

#[test]
fn about_paints_the_copied_tagline_and_lists_each_fact_whole() {
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::About),
                value: None,
            }),
        )
        .unwrap();
    let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_200.0, 900.0));
    let tagline = compiled
        .paint
        .iter()
        .filter(|node| node.key.as_str().starts_with("about/tagline/line-"))
        .map(|node| match &node.content {
            UiContent::Text(text) => text.text.trim().to_string(),
            other => panic!("{other:?}"),
        })
        .collect::<Vec<_>>()
        .join(" ");
    assert_eq!(tagline, crate::build_info::TAGLINE);
    assert_eq!(
        compiled
            .semantic(&UiKey::new("about/tagline"))
            .map(|node| node.label.as_str()),
        Some(crate::build_info::TAGLINE)
    );
    assert!(
        crate::about::provenance_text()
            .contains(&format!("tagline: {}\n", crate::build_info::TAGLINE)),
        "the copied block says the same sentence"
    );
    for (width, height) in [(1_200.0, 900.0), (474.0, 900.0), (320.0, 900.0)] {
        let mut blocks = 0;
        each_screen(
            &mut runtime,
            instance,
            view,
            &view_cx_at(width, height),
            |compiled, _| {
                for line in compiled.paint.iter().filter(|node| {
                    !node.peek && node.key.as_str().starts_with("about/provenance/value/")
                }) {
                    let fact = line.key.as_str()["about/provenance/value/".len()..]
                        .split('/')
                        .next()
                        .unwrap_or_default();
                    let block = compiled
                        .semantic(&UiKey::new(format!("about/provenance/row/{fact}")))
                        .unwrap_or_else(|| panic!("{fact}'s block ({width})"));
                    assert!(
                        line.rect.y >= block.rect.y - 0.01
                            && line.rect.bottom() <= block.rect.bottom() + 0.01,
                        "{} inside its fact's block at {width}",
                        line.key.as_str()
                    );
                    blocks += 1;
                }
            },
        );
        assert!(blocks > 0, "facts are listed at {width}");
    }
}

/// Where a Linux-layout test takes its UI face from ([`linux_layout_cx`]).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum LinuxLayoutFace {
    Host,
    LinuxLadder,
    NoUiFace,
}

fn linux_layout_cx(face: LinuxLayoutFace, width: f32, height: f32) -> Option<ViewCx<'static>> {
    let cx = view_cx_at(width, height);
    match face {
        LinuxLayoutFace::Host => {}
        LinuxLayoutFace::LinuxLadder => {
            let root = std::env::var_os("ATERM_TEST_LINUX_UI_FONTS").map(std::path::PathBuf::from);
            crate::tray_raster::install_linux_ui_fonts_for_test(root.as_deref())?;
        }
        LinuxLayoutFace::NoUiFace => crate::tray_raster::clear_ui_fonts_for_test(),
    }
    Some(cx)
}

#[test]
fn linux_update_status_settings_preserves_manual_authority_and_effective_policy() {
    let facts = |staged: Option<u64>| aterm_update::LinuxUpdateStatus {
        installed_build: 1,
        installed_version: String::new(),
        staged_build: staged,
        staged_version: staged.map(|_| "0.2.0".to_string()),
        staged_commit: staged.map(|_| "ab".repeat(20)),
        trial_phase: None,
        trial_starts: 0,
        trial_healthy: false,
        refused_newer: false,
    };
    let mut status = update_status(false);
    status.linux = Some(facts(Some(2)));
    let (mut runtime, instance, view) =
        setup_with_update(UpdateState::from_status(1, "0.1.0", Some(&status), false));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_200.0, 820.0));
    assert_zero_top_paint(&compiled, "wide Linux downloaded update");
    let apply = compiled
        .semantic(&UiKey::new("updates/install-now"))
        .unwrap();
    assert!(!apply.state.unwrap().enabled);
    assert!(apply.label.contains("aterm update apply"));
    for key in [
        "settings/control/update.enabled",
        "settings/control/update.auto_apply",
    ] {
        let switch = compiled.semantic(&UiKey::new(key)).unwrap();
        assert!(switch.state.unwrap().enabled, "{key} is live on Linux");
    }

    let mut trial = facts(None);
    trial.installed_build = 2;
    trial.trial_phase = Some("Installed".into());
    trial.trial_starts = 1;
    let mut attention = update_status(false);
    attention.linux = Some(facts(None));
    attention.failing_checks = 1;
    attention.outcome = "linux-update: GitHub answered 503 Service Unavailable while \
                         listing releases for alabsystems/aterm"
        .into();
    let mut states = Vec::new();
    for (running, saved) in [(true, true), (false, false), (false, true), (true, false)] {
        for (name, linux) in [("idle", facts(None)), ("downloaded", facts(Some(2)))] {
            let mut status = update_status(false);
            status.linux = Some(linux);
            states.push((
                format!("{name} r{running} s{saved}"),
                status,
                running,
                saved,
            ));
        }
    }
    let mut pending = update_status(false);
    pending.linux = Some(trial);
    states.push(("trial r0 s0".to_string(), pending, false, false));
    states.push(("attention".to_string(), attention, true, true));

    let mut measured_linux_faces = false;
    let mut revision = 1;
    for face in [
        LinuxLayoutFace::Host,
        LinuxLayoutFace::LinuxLadder,
        LinuxLayoutFace::NoUiFace,
    ] {
        for (state, status, running, saved) in &states {
            revision += 1;
            assert!(
                runtime.replace_settings_update(
                    UpdateState::from_status(1, "0.1.0", Some(status), false)
                        .with_automatic_checks(*running, *saved),
                    revision,
                )
            );
            for (size, width, height) in [
                ("wide", 1_200.0, 820.0),
                ("medium", 849.0, 513.0),
                ("compact", 600.0, 820.0),
                ("short compact", 600.0, 560.0),
            ] {
                let Some(cx) = linux_layout_cx(face, width, height) else {
                    continue;
                };
                measured_linux_faces |= face == LinuxLayoutFace::LinuxLadder;
                let context = format!("{face:?} {size} Linux {state}");
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                if face == LinuxLayoutFace::NoUiFace {
                    let clipped = compiled
                        .paint_audit_lines()
                        .into_iter()
                        .filter(|line| {
                            line.contains("clipped=true") && line.contains("key=\"updates/")
                        })
                        .collect::<Vec<_>>();
                    assert!(
                        clipped.is_empty(),
                        "{context}: a card outgrows its section:\n{}",
                        clipped.join("\n")
                    );
                } else {
                    assert_zero_top_paint(&compiled, &context);
                }
            }
        }
    }
    if !measured_linux_faces {
        crate::logging::stderr_line!(
            "NOTICE: the Linux UI faces (Noto Sans, DejaVu Sans) are not readable on this \
             host, so the Linux update page was measured in the host's face and with no UI \
             face only; point ATERM_TEST_LINUX_UI_FONTS at a directory holding \
             NotoSans-Regular.ttf and NotoSans-Bold.ttf to measure it in Linux's own"
        );
    }
}

fn update_route_pages(
    update: UpdateState,
    width: f32,
    height: f32,
) -> Vec<crate::native_ui::CompiledUi> {
    let (mut runtime, instance, view) = setup_with_update(update);
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    let cx = view_cx_at(width, height);
    let mut screens = Vec::new();
    each_screen(&mut runtime, instance, view, &cx, |compiled, _| {
        screens.push(compiled.clone());
    });
    screens
}

fn painted_texts(compiled: &crate::native_ui::CompiledUi) -> Vec<String> {
    compiled
        .paint
        .iter()
        .filter_map(|node| match &node.content {
            UiContent::Text(text) => Some(text.text.clone()),
            _ => None,
        })
        .collect()
}

#[test]
fn the_status_card_fits_its_section_beside_a_failed_check_under_every_switch_state() {
    let outcome = "check failed (network): error sending request for url \
                   (https://api.github.com/repos/alabsystems/aterm/releases?per_page=20): \
                   operation timed out";
    let failed_check = |running: bool, saved: bool| {
        let mut status = update_status(false);
        status.failing_checks = 1;
        status.failing_kind = "network".into();
        status.failing_checks_kind = "network".into();
        status.outcome = outcome.into();
        UpdateState::from_status(1, "0.1.0", Some(&status), false)
            .with_automatic_checks(running, saved)
    };
    let (mut runtime, instance, view) = setup_with_update(failed_check(true, true));
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::SoftwareUpdate),
                value: None,
            }),
        )
        .unwrap();
    let mut revision = 1;
    for face in [LinuxLayoutFace::Host, LinuxLayoutFace::NoUiFace] {
        for (running, saved) in [(true, true), (false, false), (false, true), (true, false)] {
            revision += 1;
            let state = failed_check(running, saved);
            let projection = state.projection();
            assert!(
                !projection.failing_persistent && update_outcome_line(&projection).is_some(),
                "the fixture is one failed check, a non-routine outcome the card paints"
            );
            assert!(runtime.replace_settings_update(state, revision));
            for (size, width, height) in [
                ("wide", 1_200.0, 820.0),
                ("medium", 849.0, 513.0),
                ("compact", 600.0, 820.0),
                ("short compact", 600.0, 560.0),
            ] {
                let Some(cx) = linux_layout_cx(face, width, height) else {
                    continue;
                };
                let context = format!("{face:?} {size} macOS r{running} s{saved}");
                let compiled = compile_settings_view(&runtime, instance, view, &cx);
                if face == LinuxLayoutFace::NoUiFace {
                    let clipped = compiled
                        .paint_audit_lines()
                        .into_iter()
                        .filter(|line| {
                            line.contains("clipped=true") && line.contains("key=\"updates/")
                        })
                        .collect::<Vec<_>>();
                    assert!(
                        clipped.is_empty(),
                        "{context}: a card outgrows its section:\n{}",
                        clipped.join("\n")
                    );
                } else {
                    assert_zero_top_paint(&compiled, &context);
                }
                if matches!(size, "wide" | "medium") {
                    let painted = compiled
                        .semantic(&UiKey::new("updates/outcome"))
                        .unwrap_or_else(|| {
                            panic!("{context}: the failed check's cause stays on the card")
                        });
                    assert_eq!(painted.label, outcome, "{context}");
                }
            }
        }
    }
}

