fn each_screen(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    cx: &ViewCx<'_>,
    mut each: impl FnMut(&crate::native_ui::CompiledUi, usize),
) -> usize {
    each_screen_of(runtime, instance, view, cx, |_, compiled, top| {
        each(compiled, top);
    })
}

fn each_screen_of(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    cx: &ViewCx<'_>,
    mut each: impl FnMut(&SettingsViewState, &crate::native_ui::CompiledUi, usize),
) -> usize {
    let (first, limit) = walk_start(runtime, instance, view, cx);
    let mut first = Some(first);
    for top in 0..=limit {
        let screen = first.take().unwrap_or_else(|| {
            set_walk_top(runtime, view, top);
            compile_settings_view(runtime, instance, view, cx)
        });
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!();
        };
        each(state, &screen, top);
    }
    limit + 1
}

fn set_walk_top(runtime: &mut NativeRuntime, view: crate::native_app::ViewId, top: usize) {
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    state.scroll_page_to(top);
    state.page_reveal = None;
}

/// The screen [`each_screen_of`] visits first, at the list's top, and the last top it goes on to:
/// a page whose first render seats the list lower is rendered at the top again.
fn walk_start(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    cx: &ViewCx<'_>,
) -> (crate::native_ui::CompiledUi, usize) {
    set_walk_top(runtime, view, 0);
    let first = compile_settings_view(runtime, instance, view, cx);
    let (limit, drawn) = match runtime.view_state(view) {
        Some(AppViewState::Settings(state)) => (
            state.result_page_limit.get().unwrap_or(0),
            state
                .scroll_record
                .borrow()
                .as_ref()
                .map_or(0, scroll::ScrollRecord::top),
        ),
        _ => unreachable!(),
    };
    if drawn == 0 {
        return (first, limit);
    }
    set_walk_top(runtime, view, 0);
    (compile_settings_view(runtime, instance, view, cx), limit)
}

fn screen_showing(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    cx: &ViewCx<'_>,
    key: &str,
) -> Option<crate::native_ui::CompiledUi> {
    let mut found = None;
    let mut wanted = None;
    each_screen(runtime, instance, view, cx, |compiled, top| {
        if wanted.is_none() && compiled.semantic(&UiKey::new(key)).is_some() {
            wanted = Some(top);
        }
    });
    if let Some(top) = wanted {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.scroll_page_to(top);
        state.page_reveal = None;
        found = Some(compile_settings_view(runtime, instance, view, cx));
    }
    found
}

fn keys_with_prefix(compiled: &crate::native_ui::CompiledUi, prefix: &str) -> Vec<String> {
    compiled
        .semantics
        .iter()
        .filter(|node| node.key.as_str().starts_with(prefix))
        .map(|node| node.key.as_str().to_string())
        .collect()
}

fn short_landscape_audit_reaches_every_control_with_feedback_at_scale(scale: f32) {
    let cx = view_cx_at(568.0, 320.0);

    for feedback_present in [false, true] {
        let feedback = feedback_present.then(|| "Settings status changed".to_string());
        let variant = if feedback_present {
            "with feedback"
        } else {
            "without feedback"
        };

        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.compact_navigation = true;
            state.feedback = feedback.clone();
        }
        let mut categories = BTreeSet::new();
        each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
            let context = format!("categories {top} at {scale}× {variant}");
            assert_short_landscape_geometry(compiled, scale, &context);
            categories.extend(keys_with_prefix(compiled, "settings/categories/"));
        });
        for route in SettingsRoute::ALL
            .into_iter()
            .filter(|route| route.on_rail())
        {
            assert!(
                categories.contains(&format!("settings/categories{}", route.path())),
                "categories at {scale}× {variant}: missing {}",
                route.label()
            );
        }

        for route in [
            SettingsRoute::Appearance,
            SettingsRoute::TextFonts,
            SettingsRoute::CursorMotion,
            SettingsRoute::Sound,
            SettingsRoute::WindowTabs,
            SettingsRoute::KeyboardInput,
            SettingsRoute::Terminal,
            SettingsRoute::Security,
        ] {
            let leading = usize::from(matches!(
                route,
                SettingsRoute::CursorMotion | SettingsRoute::Sound
            ));
            let (mut runtime, instance, view) = setup();
            let (total, expected_controls) = {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(route);
                state.feedback = feedback.clone();
                let expected_controls = state
                    .legacy
                    .fields
                    .iter()
                    .filter(|field| field_visible(field.key, false, false))
                    .filter(|field| {
                        route
                            .section()
                            .is_some_and(|section| prefs::section_of(field.key) == section)
                    })
                    .count()
                    + leading;
                (
                    expected_controls + usize::from(focused_preview_key(state).is_some()),
                    expected_controls,
                )
            };
            assert!(total >= expected_controls && total > 0, "{route:?}");
            let mut seen_controls = BTreeSet::new();
            each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
                let context = format!("{} screen {top} at {scale}× {variant}", route.label());
                assert_short_landscape_geometry(compiled, scale, &context);
                seen_controls.extend(keys_with_prefix(compiled, "settings/control/"));
                if compiled
                    .semantics
                    .iter()
                    .any(|node| theme_card_control_key(node.key.as_str()))
                {
                    seen_controls.insert(format!("settings/control/{}", prefs::EDIT_THEME));
                }
            });
            assert_eq!(
                seen_controls.len(),
                expected_controls,
                "{} at {scale}× {variant}",
                route.label()
            );
        }

        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Manual);
            state.feedback = feedback.clone();
        }
        let manual = compile_settings_view(&runtime, instance, view, &cx);
        let context = format!("Manual at {scale}× {variant}");
        assert_short_landscape_geometry(&manual, scale, &context);
        assert!(
            manual
                .semantic(&UiKey::new("settings/manual/open"))
                .is_some(),
            "{context}"
        );

        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Home);
            state.feedback = feedback.clone();
        }
        let mut top_keys = BTreeSet::new();
        each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
            let context = format!("Top Settings screen {top} at {scale}× {variant}");
            assert_short_landscape_geometry(compiled, scale, &context);
            top_keys.extend(keys_with_prefix(compiled, "settings/"));
        });
        for key in [
            prefs::EDIT_THEME,
            prefs::EDIT_WINDOW_THEME,
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            prefs::EDIT_TRAIL_SOUNDS,
            SPARKLE_WORDS_KEY,
            KEYWORD_KITTIES_KEY,
        ] {
            assert!(
                top_keys.contains(&format!("settings/control/{key}")),
                "Top Settings {key} at {scale}× {variant}"
            );
        }
        for preview in [
            "settings/top/theme/preview",
            "settings/top/cursor-trail/preview",
        ] {
            assert!(
                top_keys.contains(preview),
                "Top Settings {preview} at {scale}× {variant}"
            );
        }

        let mut source = (0..7)
            .map(|index| format!("future_{index} = {index}\n"))
            .collect::<String>();
        source.push_str("[keybindings]\n\"cmd+t\" = \"new_tab\"\n");
        let snapshot = VersionedConfigService::new(source).unwrap().snapshot();
        let (mut runtime, instance, view) = setup();
        let overrides = {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            **state = SettingsViewState::from_snapshot(&snapshot).unwrap();
            state.navigate(SettingsRoute::Modified);
            state.feedback = feedback.clone();
            authored_manual_overrides(state)
        };
        assert_eq!(
            settings_field_result_count(match runtime.view_state(view) {
                Some(AppViewState::Settings(state)) => state,
                _ => unreachable!(),
            }),
            overrides.len()
        );
        let mut modified_keys = BTreeSet::new();
        each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
            let context = format!("Modified screen {top} at {scale}× {variant}");
            assert_short_landscape_geometry(compiled, scale, &context);
            modified_keys.extend(keys_with_prefix(compiled, "settings/modified/"));
        });
        for authored in &overrides {
            let fragment = key_fragment(&authored.key);
            let context = format!("Modified {} at {scale}× {variant}", authored.key);
            assert!(
                modified_keys.contains(&format!("settings/modified/manual/label/{fragment}")),
                "{context}: label"
            );
            assert!(
                modified_keys.contains(&format!("settings/modified/manual/open/{fragment}")),
                "{context}: Manual escape hatch"
            );
            if authored.reset_safe {
                assert!(
                    modified_keys.contains(&format!("settings/modified/manual/reset/{fragment}")),
                    "{context}: exact Reset"
                );
            }
        }

        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::About);
            state.feedback = feedback.clone();
        }
        let mut about_keys = BTreeSet::new();
        each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
            let context = format!("About screen {top} at {scale}× {variant}");
            assert_short_landscape_geometry(compiled, scale, &context);
            about_keys.extend(keys_with_prefix(compiled, "about/"));
        });
        for key in [
            "about/copy-build-info",
            "about/open-site",
            "about/provenance/row/version",
            "about/provenance/row/build",
            "about/provenance/row/commit",
            "about/provenance/row/built",
            "about/provenance/row/arch",
            "about/provenance/row/compiler",
            "about/provenance/row/signature",
        ] {
            assert!(
                about_keys.contains(key),
                "About missing {key} at {scale}× {variant}; saw {about_keys:?}"
            );
        }

        for staged in [false, true] {
            let status = update_status(staged);
            let update_state = UpdateState::from_status(1, "0.1.0", Some(&status), false);
            let (mut runtime, instance, view) = setup_with_update(update_state);
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(SettingsRoute::SoftwareUpdate);
                state.feedback = feedback.clone();
            }
            let mut keys = BTreeSet::new();
            each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
                let context = format!("Update staged={staged} screen {top} at {scale}× {variant}");
                assert_short_landscape_geometry(compiled, scale, &context);
                keys.extend(keys_with_prefix(compiled, "updates/"));
            });
            for key in [
                "updates/hero",
                "updates/install-now",
                "updates/automatic",
                "updates/release-notes",
            ] {
                assert!(
                    keys.contains(key),
                    "Update missing {key}: {staged} {scale}× {variant}"
                );
            }
            assert!(
                !keys.contains("updates/check"),
                "the retired Check button reappeared: {staged} {scale}× {variant}"
            );
        }

        let packages_state = live_packages_state(None);
        let (mut runtime, instance, view) = setup();
        assert!(runtime.replace_settings_packages(packages_state, 2));
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::Packages);
            state.feedback = feedback;
        }
        let mut package_keys = BTreeSet::new();
        each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
            let context = format!("Packages screen {top} at {scale}× {variant}");
            assert_short_landscape_geometry(compiled, scale, &context);
            package_keys.extend(
                compiled
                    .semantics
                    .iter()
                    .filter(|node| {
                        node.key.as_str().starts_with("packages/")
                            || node.key.as_str().starts_with("settings/control/packages.")
                            || node.key.as_str().starts_with("settings/control/reroute.")
                    })
                    .map(|node| node.key.as_str().to_string()),
            );
        });
        for key in [
            "packages/hero",
            "packages/check",
            "packages/install-default",
            "packages/service-line",
            "settings/control/packages.enabled",
            "settings/control/packages.auto_install",
            "settings/control/reroute.announce",
            "packages/consent-note",
            "packages/programs/ay",
            "packages/activity/open-log",
        ] {
            assert!(
                package_keys.contains(key),
                "Packages missing {key} at {scale}× {variant}"
            );
        }
    }
}

#[test]
fn the_packages_verbs_stay_inside_their_card_at_every_width() {
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(live_packages_state(None), 2));
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Packages);
    }
    for width in [774.0_f32, 860.0, 1_040.0, 1_300.0] {
        let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(width, 900.0));
        let hero = compiled
            .semantic(&UiKey::new("packages/hero"))
            .unwrap_or_else(|| panic!("the hero at {width}"))
            .rect;
        let rects: Vec<_> = [
            "packages/check",
            "packages/install-default",
            "packages/uninstall-all",
        ]
        .iter()
        .map(|key| {
            compiled
                .semantic(&UiKey::new(*key))
                .unwrap_or_else(|| panic!("{key} at {width}"))
                .rect
        })
        .collect();
        for (key, rect) in ["check", "install", "remove"].iter().zip(&rects) {
            assert!(
                rect.x >= hero.x && rect.right() <= hero.right() + 0.5,
                "{key} leaves the card at {width}: {rect:?} in {hero:?}"
            );
        }
        if width >= 1_300.0 {
            assert!(
                rects.iter().all(|r| (r.y - rects[0].y).abs() < 0.5),
                "one row on a wide page: {rects:?}"
            );
        }
    }
}

#[test]
fn unset_text_setting_semantics_report_the_effective_default_while_paint_stays_quiet() {
    let state = SettingsViewState::new(&Config::default());
    let field = state
        .legacy
        .fields
        .iter()
        .find(|field| field.key == prefs::EDIT_SHELL)
        .expect("shell field");
    assert!(field.seed.is_none());
    assert!(!field.placeholder.is_empty());
    let row = setting_row(&state, 0, field, false, SettingsWidth::Compact);
    let compiled = UiTree::new(row)
        .compile(LogicalRect::new(0.0, 0.0, 390.0, 72.0))
        .unwrap();
    let key = UiKey::new(format!("settings/control/{}", field.key));
    assert_eq!(
        compiled.semantic(&key).expect("semantic text field").value,
        SemanticValue::Text(field.placeholder.clone())
    );
    let paint = compiled
        .paint
        .iter()
        .find(|node| node.key == key)
        .expect("paint text field");
    let UiContent::TextField(control) = &paint.content else {
        panic!("the shell is a text field")
    };
    assert_eq!(control.spec.visual_value.as_deref(), Some(""));
}

fn injected_font_families() -> Arc<aterm_render::font_catalog::MonospaceFamilies> {
    Arc::new(aterm_render::font_catalog::MonospaceFamilies {
        automatic: Some("SF Mono".to_string()),
        automatic_has_ligatures: false,
        bundled: vec!["Iosevka Term".to_string()],
        installed: vec!["Menlo".to_string(), "Monaco".to_string()],
        bold: vec!["Menlo Bold".to_string()],
        italic: Vec::new(),
        bold_italic: Vec::new(),
        symbol: vec!["Apple Symbols".to_string()],
        emoji: vec!["Apple Color Emoji".to_string()],
        ligatures: [("menlo", false), ("monaco", false), ("iosevkaterm", true)]
            .into_iter()
            .map(|(family, ligatures)| (family.to_string(), ligatures))
            .collect(),
    })
}

fn font_picker_labels(runtime: &NativeRuntime, view: crate::native_app::ViewId) -> Vec<String> {
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!()
    };
    let picker = state.choice_picker.as_ref().expect("a font picker is open");
    picker
        .shown
        .iter()
        .map(|index| picker.options[*index].label.clone())
        .collect()
}

fn settings_action(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    id: &str,
) -> crate::native_app::DispatchOutcome {
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(id),
                value: None,
            }),
        )
        .unwrap()
}

#[test]
fn a_font_picker_paints_its_automatic_and_other_rows_by_their_names() {
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.navigate(SettingsRoute::TextFonts);
        assert!(state.replace_font_families(injected_font_families()));
    }
    settings_action(
        &mut runtime,
        instance,
        view,
        "settings/font-picker/font_family",
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!()
    };
    let picker = state.choice_picker.as_ref().expect("a font picker is open");
    assert!(picker.fonts);
    let painted: Vec<String> = picker
        .options
        .iter()
        .map(|option| {
            choice_option_button(option, 400.0, picker.fonts)
                .visual_label
                .expect("a painted label")
        })
        .collect();
    let named: Vec<String> = picker
        .options
        .iter()
        .map(|option| option.label.clone())
        .collect();
    assert_eq!(painted, named);
    let generic = ChoicePicker::new(
        prefs::EDIT_WINDOW_THEME,
        ["dark".to_string()],
        "dark",
        true,
        true,
        "auto",
    );
    let reset = generic
        .options
        .iter()
        .find(|option| option.value.is_none())
        .expect("a reset row");
    let painted = choice_option_button(reset, 400.0, generic.fonts)
        .visual_label
        .expect("a painted label");
    assert_ne!(painted, "Use default");
    let automatic = setting_choice_label(prefs::EDIT_WINDOW_THEME, "auto");
    assert!(painted.contains(&automatic), "{painted}");
}

#[test]
fn unset_style_rows_name_the_faces_the_terminal_draws() {
    let drawn = aterm_render::DrawnFaces {
        regular: Some("SF Mono".to_string()),
        regular_has_ligatures: false,
        styles: [
            aterm_render::StyleDraw {
                face: Some("SF Mono Bold".to_string()),
                synthetic: aterm_render::StyleBits::REGULAR,
            },
            aterm_render::StyleDraw {
                face: Some("SF Mono Italic".to_string()),
                synthetic: aterm_render::StyleBits::REGULAR,
            },
            aterm_render::StyleDraw {
                face: Some("SF Mono Italic".to_string()),
                synthetic: aterm_render::StyleBits::BOLD,
            },
        ],
        symbol: Some("Noto Sans Symbols 2".to_string()),
        emoji: Some("Apple Color Emoji".to_string()),
    };
    let row_value = |runtime: &mut NativeRuntime,
                     instance: crate::native_app::AppInstanceId,
                     view: crate::native_app::ViewId,
                     key: &str| {
        let cx = view_cx_at(900.0, 2400.0);
        let compiled = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        match compiled
            .semantic(&UiKey::new(format!("settings/control/{key}")))
            .map(|row| row.value.clone())
        {
            Some(SemanticValue::Text(text)) => text,
            other => panic!("{key}: {other:?}"),
        }
    };
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.navigate(SettingsRoute::TextFonts);
        assert!(state.replace_font_families(injected_font_families()));
    }
    assert_eq!(
        row_value(&mut runtime, instance, view, prefs::EDIT_FONT_FAMILY_BOLD),
        "Automatic",
        "no report yet"
    );
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        assert!(state.replace_drawn_faces(Some(drawn.clone())));
        assert!(!state.replace_drawn_faces(Some(drawn.clone())), "unchanged");
    }
    for (key, expected) in [
        (prefs::EDIT_FONT_FAMILY, "Automatic (SF Mono)"),
        (prefs::EDIT_FONT_FAMILY_BOLD, "Automatic (SF Mono Bold)"),
        (prefs::EDIT_FONT_FAMILY_ITALIC, "Automatic (SF Mono Italic)"),
        (
            prefs::EDIT_FONT_FAMILY_BOLD_ITALIC,
            "Automatic (SF Mono Italic)",
        ),
        (prefs::EDIT_SYMBOL_FONT, "Automatic (Noto Sans Symbols 2)"),
        (prefs::EDIT_EMOJI_FONT, "Automatic (Apple Color Emoji)"),
    ] {
        assert_eq!(
            row_value(&mut runtime, instance, view, key),
            expected,
            "{key}"
        );
    }
    let row_label = |runtime: &mut NativeRuntime, key: &str| {
        let cx = view_cx_at(900.0, 2400.0);
        let compiled = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        compiled
            .semantic(&UiKey::new(format!("settings/label/{key}")))
            .map(|label| label.label.clone())
            .unwrap_or_else(|| panic!("{key} has a label"))
    };
    assert_eq!(
        row_label(&mut runtime, prefs::EDIT_FONT_FAMILY_BOLD_ITALIC),
        format!("Bold italic font family{FACT_SEPARATOR}Synthetic bold")
    );
    assert_eq!(
        row_label(&mut runtime, prefs::EDIT_FONT_FAMILY_BOLD),
        "Bold font family"
    );
    settings_action(
        &mut runtime,
        instance,
        view,
        "settings/font-picker/font_family_bold",
    );
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!()
        };
        let picker = state
            .choice_picker
            .as_ref()
            .expect("the bold picker is open");
        assert_eq!(picker.options[0].label, "Automatic (SF Mono Bold)");
    }

    let mut named = SettingsViewState::new(&Config {
        font_family_bold: Some("Menlo Bold".to_string()),
        ..Config::default()
    });
    named.replace_drawn_faces(Some(drawn));
    assert_eq!(
        font_automatic_label(&named, prefs::EDIT_FONT_FAMILY_BOLD),
        "Automatic"
    );
    assert_eq!(
        font_automatic_label(&named, prefs::EDIT_FONT_FAMILY_ITALIC),
        "Automatic (SF Mono Italic)"
    );
}

