    let row = compiled
        .semantic(&UiKey::new("settings/control/font_family"))
        .unwrap();
    assert_eq!(row.role, SemanticRole::Button);
    assert_eq!(
        row.value,
        SemanticValue::Text("Automatic (SF Mono)".to_string())
    );

    settings_action(
        &mut runtime,
        instance,
        view,
        "settings/font-picker/font_family",
    );
