#[test]
fn manual_route_identity_and_every_action_open_the_typed_editor() {
    let (mut runtime, instance, view) = setup();
    assert_eq!(
        route_action(SettingsRoute::Manual).as_str(),
        "settings/route/manual"
    );
    let commands = runtime.commands(instance, view).unwrap();
    for id in ["settings/route/manual", "settings/manual/open"] {
        assert!(
            commands
                .iter()
                .any(|command| command.id.as_str() == id && command.enabled),
            "{id} participates in the native command surface"
        );
    }
    let went = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Manual),
                value: None,
            }),
        )
        .unwrap();
    assert!(
        went.effects
            .iter()
            .all(|effect| !matches!(effect, AppEffect::OpenConfigEditor { .. })),
        "going to the Manual page opens nothing"
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view")
    };
    assert_eq!(state.route, SettingsRoute::Manual);

    let open = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("settings/manual/open"),
                value: None,
            }),
        )
        .unwrap();
    let operation = open
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::OpenConfigEditor { reply, .. } => Some(reply.operation),
            _ => None,
        })
        .expect("Open aterm.toml emits exactly one path-free editor effect");
    let commands = runtime.commands(instance, view).unwrap();
    assert!(
        !commands
            .iter()
            .find(|command| command.id.as_str() == "settings/manual/open")
            .unwrap()
            .enabled,
        "a duplicate open is disabled only while the typed request is pending"
    );
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::ConfigEditorFinished {
                operation,
                outcome: ConfigEditorOutcome::Failed {
                    message: "test denial".to_string(),
                },
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view")
    };
    assert!(state.pending.is_empty());
    assert!(state.feedback.as_deref().unwrap().contains("test denial"));
    let commands = runtime.commands(instance, view).unwrap();
    assert!(
        commands
            .iter()
            .find(|command| command.id.as_str() == "settings/manual/open")
            .unwrap()
            .enabled,
        "the Manual command reopens its editor while Settings remains on /manual"
    );
}

#[test]
fn native_sound_menu_is_one_box_on_one_route() {
    let shown: Vec<&str> = prefs::SOUND_MENU_KEYS
        .iter()
        .copied()
        .filter(|key| field_visible(key, false, false))
        .collect();

    for required in [
        prefs::EDIT_TRAIL_SOUND_VOLUME,
        prefs::EDIT_TRAIL_SOUND_STYLE,
        prefs::EDIT_TONE_MELODY,
        prefs::EDIT_TRAIL_SOUND_BED,
        prefs::EDIT_TRAIL_SOUND_RIFF,
        prefs::EDIT_SPARKLE_BONK,
        prefs::EDIT_SPARKLE_BONK_DETONATION,
        prefs::EDIT_OUTPUT_STREAK_SOUND,
    ] {
        assert!(
            shown.contains(&required),
            "{required} is not reachable from the native Sound menu"
        );
    }

    assert_eq!(
        shown.contains(&prefs::EDIT_BELL_SOUND),
        cfg!(any(target_os = "macos", windows, target_os = "linux")),
        "the terminal bell row must not promise a beep this platform never makes"
    );

    assert!(
        !field_visible(prefs::EDIT_TRAIL_SOUNDS, false, false),
        "the master is the shared Top control, not a second Advanced row"
    );
    assert!(
        field_visible(prefs::EDIT_TRAIL_SOUNDS, false, true),
        "the master must still answer a global search for sound"
    );
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Sound),
                value: None,
            }),
        )
        .unwrap();
    let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_024.0, 768.0));
    assert!(
        compiled
            .semantic(&UiKey::new(format!(
                "settings/control/{}",
                prefs::EDIT_TRAIL_SOUNDS
            )))
            .is_some(),
        "the Sound page leads with the Music effects switch"
    );

    for sibling in [
        "sparkle_words.profanity.density",
        "sparkle_words.profanity.intensity",
    ] {
        assert!(
            !field_visible(sibling, false, false),
            "{sibling} must stay a Manual-only keyword-toy internal"
        );
    }
}

#[test]
fn reduce_motion_reads_as_its_option_label_on_every_surface() {
    let words = reduce_motion_words();
    assert_eq!(words, "Reduce motion", "the picker's own label");
    let stale = [
        "Motion: Reduced",
        "set to Reduced",
        "Motion reduced",
        "Reduced motion",
    ];
    assert!(
        stale
            .iter()
            .any(|old| "On, currently suppressed by Motion: Reduced.".contains(old))
    );
    let snapshot = VersionedConfigService::new(trail_drawn("motion = \"reduced\"\n"))
        .unwrap()
        .snapshot();
    for route in [
        SettingsRoute::Sound,
        SettingsRoute::CursorMotion,
        SettingsRoute::Home,
    ] {
        let mut state = SettingsViewState::from_snapshot(&snapshot).unwrap();
        state.navigate(route);
        let compiled = settings_route_at(&state, &view_cx_at(1_200.0, 1_600.0));
        let mut said: Vec<String> = painted_texts(&compiled);
        for node in &compiled.semantics {
            said.push(node.label.clone());
            if let SemanticValue::Text(value) = &node.value {
                said.push(value.clone());
            }
        }
        let said = said.join("\n");
        if route != SettingsRoute::Sound || crate::trail_audio::output_available() {
            assert!(said.contains(&words), "{route:?} names {words:?}:\n{said}");
        }
        for old in stale {
            assert!(!said.contains(old), "{route:?} still says {old:?}:\n{said}");
        }
    }
    let state = SettingsViewState::from_snapshot(&snapshot).unwrap();
    let status = top_music_suppression_reason_for_output(
        &state,
        crate::native_app::ViewMotionCx::default(),
        true,
    )
    .expect("the music status names the pause");
    assert!(status.full().contains(&words), "{}", status.full());
}

#[test]
fn sound_rows_say_inactive_exactly_where_their_voices_are_silent() {
    use crate::motion::{MotionEffect, MotionMode, MotionPolicy};
    use aterm_effects::sound_policy::{Voice, VoiceTerms, voice_gain};
    let availability = audited_availability();
    let base = "cursor_trail = true\ncursor_trail_style = \"rainbow kitty pet\"\n\
                [output_streak]\nenabled = true\n";
    let rows: [(&str, &[Voice]); 7] = [
        (prefs::EDIT_TRAIL_SOUNDS, &Voice::ALL),
        (prefs::EDIT_TRAIL_SOUND_VOLUME, &Voice::ALL),
        (prefs::EDIT_TONE_MELODY, &[Voice::Keystroke]),
        (prefs::EDIT_TRAIL_SOUND_BED, &[Voice::Keystroke]),
        (prefs::EDIT_TRAIL_SOUND_RIFF, &[Voice::Riff]),
        (prefs::EDIT_SPARKLE_BONK, &[Voice::Bonk]),
        (prefs::EDIT_OUTPUT_STREAK_SOUND, &[Voice::StreakPip]),
    ];
    let still = crate::native_app::ViewMotionCx::default();
    type Playing = fn(MotionEffect) -> MotionPolicy;
    let cases: [(&str, &str, crate::native_app::ViewMotionCx, Playing); 5] = [
        ("nothing", "", still, |_| MotionPolicy::Full),
        ("Reduce motion", "motion = \"reduced\"\n", still, |_| {
            MotionPolicy::resolve(MotionMode::Reduced, false, true)
        }),
        (
            "system Reduce Motion",
            "",
            crate::native_app::ViewMotionCx {
                system_reduced: true,
                ..still
            },
            |_| MotionPolicy::resolve(MotionMode::Auto, true, true),
        ),
        (
            "heavy load",
            "",
            crate::native_app::ViewMotionCx {
                performance_reduced: true,
                ..still
            },
            |effect| {
                if effect.load_shed_exempt() {
                    MotionPolicy::Full
                } else {
                    MotionPolicy::Reduced
                }
            },
        ),
        (
            "this window unfocused",
            "",
            crate::native_app::ViewMotionCx {
                focused: false,
                ..still
            },
            |_| MotionPolicy::Full,
        ),
    ];
    let mut idled = 0;
    for (case, extra, cx, playing) in cases {
        let source = format!("{extra}{base}");
        for (key, voices) in rows {
            let silent = voices.iter().all(|voice| {
                voice_gain(
                    *voice,
                    &VoiceTerms {
                        master: true,
                        own: true,
                        volume: 0.4,
                        raw_focused: true,
                        reduced_motion: voice
                            .motion_twin()
                            .is_some_and(|twin| !playing(twin).animate(twin)),
                    },
                )
                .is_none()
            });
            let effect = projected_effect(&source, &[], key, availability, cx);
            let inactive = effect
                .notes
                .iter()
                .any(|note| note.kind == EffectNoteKind::Inactive);
            assert_eq!(
                inactive, silent,
                "{case}: {key} says Inactive exactly when its voices are silent: {effect:?}"
            );
            idled += usize::from(inactive);
        }
    }
    assert!(
        idled >= 6,
        "non-vacuous: the bonk and the pip idle under each reduction"
    );
}

#[test]
fn sound_rows_disclose_their_real_gates_and_no_false_ones() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();

    for key in [prefs::EDIT_TONE_MELODY, prefs::EDIT_TRAIL_SOUND_BED] {
        let effect = projected_effect("cursor_trail = false\n", &[], key, availability, motion);
        assert!(
            effect_note_contains(&effect, "Cursor style Off"),
            "{key} must disclose the trail gate it actually has: {effect:?}"
        );
        let style_off = projected_effect(
            "cursor_trail = true\ncursor_trail_style = \"off\"\n",
            &[],
            key,
            availability,
            motion,
        );
        assert!(
            effect_note_contains(&style_off, "Cursor style Off"),
            "{key}: {style_off:?}"
        );
        assert!(!effect.has_live_effect, "{key}");
    }

    let trail_off = projected_effect(
        "cursor_trail = false\n",
        &[],
        prefs::EDIT_TRAIL_SOUND_RIFF,
        availability,
        motion,
    );
    assert!(
        !effect_note_contains(&trail_off, "cursor effects off"),
        "the riff still sings with the trail off; claiming otherwise is a lie: {trail_off:?}"
    );

    for source in [
        "cursor_trail = true\ncursor_trail_style = \"comet\"\n",
        "cursor_trail = true\ncursor_trail_style = \"off\"\n",
    ] {
        let riff = projected_effect(
            source,
            &[],
            prefs::EDIT_TRAIL_SOUND_RIFF,
            availability,
            motion,
        );
        assert!(
            effect_note_contains(&riff, "companion styles only"),
            "{source}{riff:?}"
        );
        assert!(!riff.has_live_effect, "{source}");
    }

    for source in [
        "cursor_trail = false\n",
        "cursor_trail = true\ncursor_trail_style = \"off\"\n",
    ] {
        let volume = projected_effect(
            source,
            &[],
            prefs::EDIT_TRAIL_SOUND_VOLUME,
            availability,
            motion,
        );
        assert!(volume.has_live_effect, "{source}{volume:?}");
        assert!(volume.notes.is_empty(), "{source}{volume:?}");
    }
    let volume_music_off = projected_effect(
        "trail_sounds = false\n",
        &[],
        prefs::EDIT_TRAIL_SOUND_VOLUME,
        availability,
        motion,
    );
    assert!(
        effect_note_contains(&volume_music_off, "Music effects is Off"),
        "{volume_music_off:?}"
    );
    assert!(!volume_music_off.has_live_effect);

    let music_off = projected_effect(
        "trail_sounds = false\n",
        &[],
        prefs::EDIT_TRAIL_SOUND_RIFF,
        availability,
        motion,
    );
    assert!(
        effect_note_contains(&music_off, "Music effects is Off"),
        "the riff must disclose the master switch that does silence it: {music_off:?}"
    );
    assert!(!music_off.has_live_effect);

    let bonk_trail_off = projected_effect(
        "cursor_trail = false\n",
        &[],
        prefs::EDIT_SPARKLE_BONK,
        availability,
        motion,
    );
    assert!(
        !effect_note_contains(&bonk_trail_off, "cursor effects off"),
        "the bonk fires with the trail off: {bonk_trail_off:?}"
    );
    let bonk_master_off = projected_effect(
        "[sparkle_words]\nenabled = false\n",
        &[],
        prefs::EDIT_SPARKLE_BONK,
        availability,
        motion,
    );
    assert!(
        effect_note_contains(&bonk_master_off, "all word effects are switched off"),
        "the bonk must disclose the sparkle master that does silence it: {bonk_master_off:?}"
    );
    for key in [
        prefs::EDIT_SPARKLE_BONK,
        prefs::EDIT_SPARKLE_BONK_DETONATION,
    ] {
        let music_off = projected_effect("trail_sounds = false\n", &[], key, availability, motion);
        assert!(
            effect_note_contains(&music_off, "Music effects is Off"),
            "{key} must disclose the Music-effects master that does silence it: {music_off:?}"
        );
        assert!(!music_off.has_live_effect, "{key}");
    }

    let silent = SettingsAvailability {
        trail_audio: false,
        ..availability
    };
    for key in [
        prefs::EDIT_TRAIL_SOUND_RIFF,
        prefs::EDIT_OUTPUT_STREAK_SOUND,
    ] {
        let muted = projected_effect("", &[], key, silent, motion);
        assert!(
            effect_note_contains(&muted, "Audio unavailable"),
            "{key}: {muted:?}"
        );
        assert!(
            !muted.has_live_effect,
            "{key}: no device cannot play a synth voice"
        );
        let available = projected_effect(
            "[output_streak]\nenabled = true\n",
            &[],
            key,
            availability,
            motion,
        );
        assert!(
            !effect_note_contains(&available, "Audio unavailable"),
            "{key}: {available:?}"
        );
    }
    let bell = projected_effect("", &[], prefs::EDIT_BELL_SOUND, silent, motion);
    assert!(
        !effect_note_contains(&bell, "Audio unavailable"),
        "the OS bell does not need the trail-audio device: {bell:?}"
    );
}

#[test]
fn a_box_says_why_its_rows_are_idle_only_where_all_of_them_are() {
    let state_for = |source: &str| {
        let service = VersionedConfigService::new(source.to_string()).unwrap();
        SettingsViewState::from_snapshot(&service.snapshot()).unwrap()
    };
    let sound_box: Vec<&str> = prefs::SOUND_MENU_KEYS
        .iter()
        .copied()
        .filter(|key| prefs::group_of(key).0 == "Sound effects" && field_visible(key, false, false))
        .collect();
    assert!(sound_box.len() >= 2 && sound_box.contains(&prefs::EDIT_TRAIL_SOUND_VOLUME));
    assert_eq!(
        shared_inactive_reason(&state_for("cursor_trail = false\n"), &sound_box),
        None,
        "cursor effects off idles two of the box's rows, not Sound volume"
    );
    assert_eq!(
        shared_inactive_reason(&state_for("trail_sounds = false\n"), &sound_box)
            .map(|(_, sentence)| sentence),
        crate::trail_audio::output_available()
            .then(|| "These are inactive for now: Music effects is Off.".to_string()),
        "Music effects off idles every row of the box"
    );
    let rainbow = state_for(&trail_drawn(""));
    assert_eq!(
        shared_inactive_reason(
            &rainbow,
            &[
                prefs::EDIT_CURSOR_TRAIL_MS,
                prefs::EDIT_CURSOR_TRAIL_INTENSITY,
                prefs::EDIT_CURSOR_TRAIL_LENGTH,
                prefs::EDIT_CURSOR_TRAIL_RADIUS,
            ],
        ),
        None,
        "Rainbow kitty reads the duration and intensity"
    );
    assert_eq!(
        shared_inactive_reason(
            &rainbow,
            &[
                prefs::EDIT_CURSOR_TRAIL_COLOR,
                prefs::EDIT_CURSOR_TRAIL_ACCENT
            ],
        )
        .map(|(_, sentence)| sentence),
        Some("Rainbow kitty does not use these.".to_string())
    );

    let (mut runtime, instance, view) = setup();
    replace_settings_source(&mut runtime, view, "cursor_trail = false\n".to_string());
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Sound),
                value: None,
            }),
        )
        .unwrap();
    let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_200.0, 1_600.0));
    let painted = |prefixes: &[String]| -> String {
        compiled
            .paint
            .iter()
            .filter(|node| {
                !node.peek
                    && prefixes
                        .iter()
                        .any(|prefix| node.key.as_str().starts_with(prefix.as_str()))
            })
            .filter_map(|node| match &node.content {
                UiContent::Text(spec) => Some(spec.text.clone()),
                _ => None,
            })
            .collect::<Vec<_>>()
            .join(" ")
    };
    assert_eq!(
        painted(&["settings/group-reason/".to_string()]),
        "",
        "no sentence heads a box whose other rows still work"
    );
    let idle_tag = if crate::trail_audio::output_available() {
        "Inactive"
    } else {
        "Audio unavailable"
    };
    for key in [prefs::EDIT_TONE_MELODY, prefs::EDIT_TRAIL_SOUND_BED] {
        let row = painted(&[
            format!("settings/label/{key}/visual"),
            format!("settings/detail/{key}/line-"),
        ]);
        assert!(row.contains(idle_tag), "{key} paints its own tag: {row:?}");
    }
    let volume = painted(&[
        format!("settings/label/{}/visual", prefs::EDIT_TRAIL_SOUND_VOLUME),
        format!("settings/detail/{}/line-", prefs::EDIT_TRAIL_SOUND_VOLUME),
    ]);
    assert!(
        !volume.contains("Inactive"),
        "Sound volume works: {volume:?}"
    );
}

#[test]
fn bloom_rows_say_they_have_no_effect_on_a_light_theme() {
    let project = |source: &str, key: &str| {
        let service = VersionedConfigService::new(source.to_string()).unwrap();
        let state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
        setting_effect_projection(
            &state,
            None,
            key,
            audited_availability(),
            crate::native_app::ViewMotionCx {
                system_dark: true,
                ..crate::native_app::ViewMotionCx::default()
            },
        )
    };
    for key in [
        prefs::EDIT_CURSOR_TRAIL_BLOOM,
        prefs::EDIT_CURSOR_TRAIL_BLOOM_STRENGTH,
        prefs::EDIT_CURSOR_TRAIL_BLOOM_RADIUS,
    ] {
        let light = project(
            &trail_drawn("theme = \"GitHub Light\"\ncursor_trail_style = \"comet\"\n"),
            key,
        );
        assert!(
            effect_note_contains(&light, "dark themes only") && !light.has_live_effect,
            "{key} on a light theme: {light:?}"
        );
        let dark = project(&trail_drawn("cursor_trail_style = \"comet\"\n"), key);
        assert!(
            !effect_note_contains(&dark, "dark themes only"),
            "{key} on the default dark theme: {dark:?}"
        );
    }
    let off = project(
        &trail_drawn("cursor_trail_style = \"comet\"\ncursor_trail_bloom = false\n"),
        prefs::EDIT_CURSOR_TRAIL_BLOOM_STRENGTH,
    );
    assert!(effect_note_contains(&off, "Bloom Off"), "{off:?}");
}

#[test]
fn serious_mode_is_disclosed_on_the_sound_rows_it_silences() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();
    const TRAIL_ON: &str = "cursor_trail = true\n";
    const TRAIL_ON_SERIOUS: &str = "cursor_trail = true\nserious_mode = true\n";

    for key in [
        prefs::EDIT_TRAIL_SOUND_VOLUME,
        prefs::EDIT_TRAIL_SOUND_STYLE,
        prefs::EDIT_TONE_MELODY,
        prefs::EDIT_TRAIL_SOUND_BED,
        prefs::EDIT_TRAIL_SOUND_RIFF,
        prefs::EDIT_BELL_SOUND,
        prefs::EDIT_SPARKLE_BONK,
        prefs::EDIT_SPARKLE_BONK_DETONATION,
    ] {
        let quiet = projected_effect(TRAIL_ON, &[], key, availability, motion);
        assert!(
            !effect_note_contains(&quiet, "Serious Mode"),
            "{key} must not claim Serious Mode with Serious Mode off: {quiet:?}"
        );
        let serious = projected_effect(TRAIL_ON_SERIOUS, &[], key, availability, motion);
        assert!(
            effect_note_contains(&serious, "Serious Mode"),
            "{key} is silent under Serious Mode and must say so: {serious:?}"
        );
        assert!(!serious.has_live_effect, "{key}");
    }

    let master = projected_effect(
        TRAIL_ON_SERIOUS,
        &[],
        prefs::EDIT_TRAIL_SOUNDS,
        availability,
        motion,
    );
    assert!(
        effect_note_contains(&master, "Serious Mode"),
        "Music effects On is silent under Serious Mode and must say so: {master:?}"
    );
}

#[test]
fn every_cursor_style_spelling_reads_as_its_list_name() {
    for (spelling, name) in [
        ("rainbow kitty pet", "Rainbow kitty"),
        ("rainbow kitty", "Rainbow kitty"),
        ("Rainbow Kitty Tall", "Rainbow kitty"),
        ("kitty", "Rainbow kitty"),
        ("rainbow kitty underline", "Rainbow underline"),
        ("  nyan underline  ", "Rainbow underline"),
        ("nyan", "Flying kitty"),
        ("dog pet", "Rainbow dog"),
        ("rainbow dog", "Rainbow dog"),
        ("laser", "Lightning"),
        ("lightning", "Lightning"),
        ("classic lumen", "Classic"),
        ("classic mono", "Classic"),
        ("off", "Off"),
        ("plasma", "Rainbow kitty (unknown \"plasma\")"),
    ] {
        assert_eq!(
            setting_choice_label(prefs::EDIT_CURSOR_TRAIL_STYLE, spelling),
            name,
            "{spelling:?}"
        );
    }
    for &value in prefs::CURSOR_TRAIL_STYLES {
        let label = setting_choice_label(prefs::EDIT_CURSOR_TRAIL_STYLE, value);
        assert_eq!(
            prefs::cursor_trail_style_canonical(&label.to_ascii_lowercase()),
            Some(value),
            "{value:?} is labelled {label:?}"
        );
    }
    assert_eq!(
        setting_choice_label(prefs::EDIT_WINDOW_THEME, "rainbow kitty underline"),
        "Rainbow kitty underline"
    );
    assert_ne!(
        setting_choice_label(prefs::EDIT_THEME, "laser"),
        setting_choice_label(prefs::EDIT_CURSOR_TRAIL_STYLE, "laser")
    );
}

#[test]
fn visual_forms_hide_inert_and_compatibility_only_effect_controls() {
    for key in [
        "matrix_rain.materialize",
        "matrix_rain.ink_text",
        "matrix_rain.phosphor",
        SPARKLE_MASTER_KEY,
    ] {
        assert!(!field_visible(key, false, false), "{key}");
        assert!(!field_visible(key, false, true), "{key}");
        assert!(!field_visible(key, true, false), "{key}");
    }
    assert!(field_visible(SPARKLE_WORDS_KEY, true, false));
    assert!(field_visible(prefs::EDIT_THEME, false, false));
    assert!(field_visible(prefs::EDIT_WINDOW_THEME, false, false));
    assert!(!field_visible(prefs::EDIT_TRAIL_SOUNDS, false, false));
    assert!(field_visible(prefs::EDIT_THEME, true, false));
    for macos_only in [
        prefs::EDIT_FONT_THICKEN,
        prefs::EDIT_BACKGROUND_OPACITY,
        prefs::EDIT_SECURE_KEYBOARD_ENTRY,
    ] {
        assert_eq!(
            field_visible(macos_only, false, false),
            cfg!(target_os = "macos"),
            "{macos_only} belongs in ordinary Advanced only where it has a live consumer"
        );
        assert!(
            field_visible(macos_only, true, false),
            "Modified preserves authored cross-platform configuration"
        );
    }
    assert!(
        field_visible(prefs::EDIT_ALLOW_OSC52_QUERY, false, false),
        "OSC 52 query has a live host: the GUI clipboard callback answers \
         authorized queries, so the switch is an ordinary security policy"
    );
    assert!(
        field_visible(prefs::EDIT_ALLOW_OSC52_QUERY, true, false),
        "Modified still lists the authored value"
    );
    assert!(
        field_visible(prefs::EDIT_CONFIRM_MULTILINE_PASTE, false, false),
        "the pastejacking confirm has a live host on every platform now \
         (macOS sheet / Windows dialog / Linux in-window banner)"
    );
    {
        let (key, supported) = (
            prefs::EDIT_ALLOW_NOTIFICATIONS,
            crate::notify::delivery_available(),
        );
        assert_eq!(
            field_visible(key, false, false),
            supported,
            "{key} belongs in ordinary Advanced only with a real platform host"
        );
        assert_eq!(field_visible(key, false, true), supported);
        assert!(
            field_visible(key, true, false),
            "Modified preserves authored cross-platform configuration"
        );
    }

    for key in ["update.owner", "matrix_rain.fps", prefs::EDIT_STEM_GAMMA] {
        assert!(!field_visible(key, false, false), "{key}");
        assert!(!field_visible(key, false, true), "{key}");
        assert!(!field_visible(key, true, false), "{key}");
    }
    for key in [
        prefs::EDIT_SHELL,
        prefs::EDIT_SHOW_BUILD_BADGE,
        prefs::EDIT_COLUMNS,
        prefs::EDIT_LINES,
        prefs::EDIT_GPU,
        prefs::EDIT_TEMPORAL_RECORDING,
        prefs::EDIT_CURSOR_GLOW_SDR_BOOST,
    ] {
        assert!(field_visible(key, false, false), "{key}");
        assert!(field_visible(key, false, true), "{key}");
        assert!(field_visible(key, true, false), "{key}");
    }
    for (key, here) in [
        (
            prefs::EDIT_HDR_GLOW,
            cfg!(any(target_os = "macos", windows)),
        ),
        (prefs::EDIT_FOCUS_BOOST, cfg!(windows)),
    ] {
        assert_eq!(field_visible(key, false, false), here, "{key}");
        assert_eq!(field_visible(key, false, true), here, "{key}");
        assert!(field_visible(key, true, false), "{key}");
    }
    for key in [prefs::EDIT_SHELL_ARGS, prefs::EDIT_FONT_VARIATION] {
        assert!(prefs::manual_collection_key(key), "{key}");
        assert!(
            !field_visible(key, true, false),
            "lossless collection {key} stays in Manual instead of a scalar row"
        );
    }
    assert!(prefs::config_asset_source_key(
        prefs::EDIT_CURSOR_NYAN_SPRITE
    ));
    assert!(prefs::manual_only_key(prefs::EDIT_CURSOR_NYAN_SPRITE));
    assert!(
        !field_visible(prefs::EDIT_CURSOR_NYAN_SPRITE, true, true),
        "host-backed sprite source is edited through Manual's worker-validated path"
    );

    let fields = prefs::editable_fields(&Config::default());
    let ordinary_advanced_field = |field: &EditField| {
        field_visible(field.key, false, false)
            && SettingsRoute::ALL
                .into_iter()
                .filter_map(SettingsRoute::section)
                .any(|section| section == prefs::section_of(field.key))
    };
    for field in fields.iter().filter(|field| ordinary_advanced_field(field)) {
        assert!(
            native_advanced_effect(field.key).is_some(),
            "Advanced row {} has no audited shipping consumer",
            field.key
        );
    }
    for restart_only in [prefs::EDIT_COLUMNS, prefs::EDIT_LINES, prefs::EDIT_GPU] {
        assert!(
            native_advanced_effect(restart_only).is_some()
                && prefs::application_timing(restart_only).is_some(),
            "restart-only {restart_only} is a row that says when it applies"
        );
    }
    for route in SettingsRoute::ALL {
        let Some(section) = route.section() else {
            continue;
        };
        let has_ordinary_row = fields.iter().any(|field| {
            prefs::section_of(field.key) == section && field_visible(field.key, false, false)
        });
        assert!(
            has_ordinary_row,
            "{} must not be an empty Advanced destination",
            route.label()
        );
    }
}

#[test]
fn restart_only_overrides_disclose_timing_in_rows_and_apply_feedback() {
    let snapshot =
        VersionedConfigService::new("columns = 96\nlines = 30\ngpu = false\n".to_string())
            .unwrap()
            .snapshot();
    let state = SettingsViewState::from_snapshot(&snapshot).unwrap();
    for key in [prefs::EDIT_COLUMNS, prefs::EDIT_LINES, prefs::EDIT_GPU] {
        let expected_timing = prefs::application_timing(key)
            .expect("restart-only timing")
            .words();
        let (index, field) = state
            .legacy
            .fields
            .iter()
            .enumerate()
            .find(|(_, field)| field.key == key)
            .unwrap();
        let compiled = UiTree::new(setting_row(&state, index, field, true, SettingsWidth::Wide))
            .compile(LogicalRect::new(0.0, 0.0, 720.0, 80.0))
            .unwrap();
        assert!(
            compiled
                .semantic(&UiKey::new(format!("settings/label/{key}")))
                .unwrap()
                .label
                .contains(expected_timing),
            "Modified visibly discloses timing for {key}"
        );
        assert!(
            compiled
                .semantic(&UiKey::new(format!("settings/control/{key}")))
                .unwrap()
                .label
                .contains(expected_timing),
            "the native control name discloses timing for {key}"
        );
    }

    let (mut runtime, instance, view) = setup();
    let mut snapshot = snapshot;
    snapshot.revision = 2;
    runtime
        .dispatch(instance, view, AppEvent::ConfigChanged(snapshot))
        .unwrap();
    let requested = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_GPU)),
                value: Some(SemanticInput::Bool(true)),
            }),
        )
        .unwrap();
    let operation = requested
        .effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::ConfigPatch { reply, .. } => Some(reply.operation),
            _ => None,
        })
        .expect("restart-only edit reaches the shared config service");
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::ConfigPatchFinished {
                operation,
                outcome: ConfigPatchOutcome::Applied {
                    revision: 3,
                    undo: Some(7),
                },
            },
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view")
    };
    let timing = prefs::application_timing(prefs::EDIT_GPU)
        .expect("restart-only timing")
        .words();
    assert!(
        state
            .feedback
            .as_deref()
            .is_some_and(|feedback| feedback.contains(timing)),
        "the apply feedback discloses the timing: {:?}",
        state.feedback
    );
}

#[test]
fn configured_draft_and_pinned_font_sizes_reach_paint_at_their_size_times_the_scale() {
    for size in [6.0_f32, 36.0, 200.0] {
        for scale in [1.0, 1.25, 2.0, 3.0] {
            for source in ["configured", "draft", "environment"] {
                let mut state = SettingsViewState::new(&Config {
                    font_px: Some(if source == "configured" { size } else { 14.0 }),
                    ..Config::default()
                });
                if source == "draft" {
                    state.field_inputs.insert(
                        prefs::EDIT_FONT_PX.to_string(),
                        crate::native_text_input::TextInputState::new(size.to_string()),
                    );
                } else if source == "environment" {
                    state.environment_overrides.insert(
                        prefs::EDIT_FONT_PX.to_string(),
                        crate::app_config::ActiveEnvironmentOverride {
                            variable: "--font-px",
                            effective: size.to_string(),
                        },
                    );
                }
                let spec = renderer_preview_spec_for_key_with_font(
                    &state,
                    prefs::EDIT_FONT_PX,
                    0,
                    crate::native_app::ViewMotionCx::default(),
                    24.0,
                    scale,
                    None,
                )
                .unwrap();
                assert_eq!(spec.font_px, size);
                let height = spec.preferred_height(108.0).min(600.0);
                let compiled = UiTree::new(crate::settings_preview::preview_node(
                    "physical-font-preview",
                    spec,
                    height,
                ))
                .compile(LogicalRect::new(0.0, 0.0, 900.0, 700.0))
                .unwrap();
                let painted_px = compiled
                    .tray(aterm_render::Theme::default(), 13.0)
                    .prims
                    .into_iter()
                    .find_map(|prim| match prim {
                        crate::widget::DrawPrim::TerminalSpecimen { spec, .. } => {
                            Some(spec.font_px * scale)
                        }
                        _ => None,
                    })
                    .expect("one complete specimen row reaches paint");
                let device = (size * scale).min(crate::FONT_PX_MAX);
                assert!(
                    (painted_px - device).abs() < 0.001,
                    "{source} {size}px at {scale}x painted {painted_px}px, not {device}px"
                );
            }
        }
    }
}

