#[test]
fn a_packages_switch_note_wraps_under_the_name_beside_resets_place() {
    let (label_px, label_face) =
        crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Primary);
    for source in [
        "[packages]\nenabled = false\n",
        "[packages]\nenabled = false\nauto_install = true\n",
    ] {
        let config: Config = aterm_toml::from_str(source).unwrap();
        let state = SettingsViewState::new(&config);
        state
            .presented_package_admission
            .set(PackageAdmission::Ready);
        let text_width = 512.0;
        let (row, _) = registry_switch_row(
            &state,
            prefs::EDIT_PACKAGES_AUTO_INSTALL,
            SettingsWidth::Medium,
            SettingsWidth::Medium.row_height(),
            text_width,
            "packages/switch-row/test".to_string(),
            "packages",
        )
        .expect("the row");
        let mut nodes = vec![&row];
        let mut lines = Vec::new();
        let mut detail = None;
        let line_prefix = format!(
            "settings/label/{}/visual/line-",
            prefs::EDIT_PACKAGES_AUTO_INSTALL
        );
        while let Some(node) = nodes.pop() {
            if node.key.as_str().starts_with(&line_prefix)
                && let UiContent::Text(spec) = &node.content
            {
                lines.push(spec.text.clone());
            }
            if node.key.as_str() == format!("packages/detail/{}", prefs::EDIT_PACKAGES_AUTO_INSTALL)
            {
                detail = Some(node);
            }
            nodes.extend(node.children.iter());
        }
        assert!(!lines.is_empty(), "{source}: the label");
        for label in &lines {
            assert!(
                crate::tray_raster::ui_text_width_for(label_face, label, label_px)
                    <= inline_row_label_width(&EditKind::Bool, text_width, true),
                "{source}: {label}"
            );
            assert!(!label.contains('\u{2026}'), "{source}: cut off: {label}");
            assert!(!label.contains("Waits"), "{source}: {label}");
        }
        assert!(detail.is_some(), "{source}: the note goes under the name");
    }
}

#[test]
fn effect_projection_exhaustively_gates_disabled_effect_families() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();
    let sample = |kind: EditKind| match kind {
        EditKind::Bool => "true",
        EditKind::Integer => "5",
        EditKind::Float => "0.7",
        EditKind::Color => "#44ccff",
        EditKind::Enum { options } => options
            .first()
            .copied()
            .expect("registered native enum has an option"),
        EditKind::Text | EditKind::Theme => "matrix",
    };

    for leaf in prefs::NESTED_LEAVES.iter().filter(|leaf| {
        leaf.key.starts_with("matrix_rain.")
            && leaf.key != prefs::EDIT_MATRIX_RAIN_ENABLED
            && !native_compatibility_only_key(leaf.key)
    }) {
        let effect = projected_effect(
            "[matrix_rain]\nenabled = false\n",
            &[(leaf.key, sample(leaf.kind))],
            leaf.key,
            availability,
            motion,
        );
        assert!(
            effect_note_contains(&effect, "Matrix rain is Off"),
            "{}: {effect:?}",
            leaf.key
        );
        assert!(!effect.has_live_effect, "{}", leaf.key);
    }

    for source in ["cursor_trail_style = \"off\"\n", "cursor_trail = false\n"] {
        for key in TRAIL_TUNING_KEYS {
            let kind = prefs::edit_kind(key);
            let effect =
                projected_effect(source, &[(key, sample(kind))], key, availability, motion);
            assert!(
                effect_note_contains(&effect, "Cursor style Off"),
                "{source}{key}: {effect:?}"
            );
            assert!(!effect.has_live_effect, "{key}");
        }
    }

    for leaf in prefs::NESTED_LEAVES.iter().filter(|leaf| {
        leaf.key.starts_with("sparkle_words.")
            && leaf.key != SPARKLE_MASTER_KEY
            && !native_compatibility_only_key(leaf.key)
    }) {
        let effect = projected_effect(
            "[sparkle_words]\nenabled = false\n",
            &[(leaf.key, sample(leaf.kind))],
            leaf.key,
            availability,
            motion,
        );
        assert!(
            effect_note_contains(&effect, "all word effects are switched off"),
            "{}: {effect:?}",
            leaf.key
        );
        assert!(!effect.has_live_effect, "{}", leaf.key);
    }
}

#[test]
fn an_unknown_trail_style_leaves_the_tuning_rows_live() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx {
        system_dark: true,
        ..crate::native_app::ViewMotionCx::default()
    };
    let sample = |kind: EditKind| match kind {
        EditKind::Bool => "true",
        EditKind::Integer => "5",
        EditKind::Float => "0.7",
        EditKind::Color => "#44ccff",
        EditKind::Enum { options } => options
            .first()
            .copied()
            .expect("registered native enum has an option"),
        EditKind::Text | EditKind::Theme => "matrix",
    };
    let typo = "phasr";
    assert_eq!(
        crate::prefs::cursor_trail_style_canonical(typo),
        None,
        "the probe value must really be unrecognized"
    );
    let good = crate::prefs::DEFAULT_CURSOR_TRAIL_STYLE;

    let mut any_live = 0usize;
    for key in TRAIL_TUNING_KEYS {
        let kind = prefs::edit_kind(key);
        let project = |style: &str| {
            projected_effect(
                &format!("cursor_trail = true\ncursor_trail_style = \"{style}\"\n"),
                &[(key, sample(kind))],
                key,
                availability,
                motion,
            )
        };
        let baseline = project(good);
        let fallback = project(typo);
        assert_eq!(
            fallback.has_live_effect, baseline.has_live_effect,
            "{key}: the unrecognized style changed the live verdict\n  valid: {baseline:?}\n  typo: {fallback:?}"
        );
        assert!(
            !effect_note_contains(&fallback, "outside this setting's registered choices"),
            "{key}: a tuning row must not be told ITS value is unregistered: {fallback:?}"
        );
        if fallback.has_live_effect {
            any_live += 1;
            assert!(
                effect_note_contains(&fallback, "this tuning applies to that fallback trail"),
                "{key}: a live tuning row must name the trail it is tuning: {fallback:?}"
            );
        } else if *key == prefs::EDIT_CURSOR_FIRE_SHIMMER {
            assert!(
                effect_note_contains(&fallback, "Fire style only"),
                "{fallback:?}"
            );
        } else if *key == prefs::EDIT_HDR_GLOW {
            assert!(
                effect_note_contains(&fallback, "no HDR display here"),
                "{fallback:?}"
            );
        } else {
            assert!(
                effect_note_contains(&fallback, "not used by Rainbow kitty"),
                "{key}: {fallback:?}"
            );
        }
    }
    let fallback_style = crate::app_config::resolve_trail_style(good);
    let read = TRAIL_TUNING_KEYS
        .iter()
        .filter(|key| **key != prefs::EDIT_HDR_GLOW)
        .filter(|key| {
            !prefs::CURSOR_STYLE_TUNING_KEYS.contains(key)
                || trail_style_uses(&fallback_style, key, false)
        })
        .count();
    assert_eq!(
        any_live, read,
        "{any_live} of the {read} rows the fallback trail reads stayed live"
    );
    let edr = crate::native_app::ViewMotionCx {
        display_edr: true,
        ..motion
    };
    for (key, motion) in [
        (prefs::EDIT_CURSOR_TRAIL_INTENSITY, motion),
        (prefs::EDIT_HDR_GLOW, edr),
        (prefs::EDIT_CURSOR_TRAIL_MS, motion),
    ] {
        let effect = projected_effect(
            &format!("cursor_trail = true\ncursor_trail_style = \"{typo}\"\n"),
            &[(key, sample(prefs::edit_kind(key)))],
            key,
            availability,
            motion,
        );
        assert!(effect.has_live_effect, "{key}: {effect:?}");
    }

    let key = prefs::EDIT_TRAIL_SOUNDS;
    let project = |style: &str| {
        projected_effect(
            &format!("cursor_trail = true\ncursor_trail_style = \"{style}\"\n"),
            &[(key, "true")],
            key,
            availability,
            motion,
        )
    };
    let baseline = project(good);
    let fallback = project(typo);
    assert_eq!(
        fallback.has_live_effect, baseline.has_live_effect,
        "{key}: the unrecognized style changed the live verdict\n  valid: {baseline:?}\n  typo: {fallback:?}"
    );
    assert!(fallback.has_live_effect, "{key}: {fallback:?}");
    assert!(
        !effect_note_contains(&fallback, "outside this setting's registered choices"),
        "{key}: a switch must not be told ITS value is unregistered: {fallback:?}"
    );

    let style_row = projected_effect(
        "cursor_trail = true\n",
        &[(prefs::EDIT_CURSOR_TRAIL_STYLE, typo)],
        prefs::EDIT_CURSOR_TRAIL_STYLE,
        availability,
        motion,
    );
    assert!(
        effect_note_contains(&style_row, "Invalid trail style: runtime fallback active"),
        "{style_row:?}"
    );
    assert!(!style_row.has_live_effect, "{style_row:?}");

    for key in TRAIL_TUNING_KEYS {
        let effect = projected_effect(
            &format!("cursor_trail = false\ncursor_trail_style = \"{typo}\"\n"),
            &[(key, sample(prefs::edit_kind(key)))],
            key,
            availability,
            motion,
        );
        assert!(
            effect_note_contains(&effect, "Cursor style Off"),
            "{key}: {effect:?}"
        );
        assert!(!effect.has_live_effect, "{key}");
    }
}

