#[test]
fn load_adaptive_motion_row_discloses_always_animate_and_nothing_else() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();
    let key = prefs::EDIT_LOAD_ADAPTIVE_MOTION;
    let always = setting_choice_label(prefs::EDIT_MOTION, "full");
    assert_eq!(always, "Always animate");
    for value in ["true", "false"] {
        for (source, edits) in [
            ("motion = \"full\"\n", vec![(key, value)]),
            ("", vec![(prefs::EDIT_MOTION, "full"), (key, value)]),
        ] {
            let effect = projected_effect(source, &edits, key, availability, motion);
            assert!(
                effect
                    .notes
                    .iter()
                    .any(|note| note.kind == EffectNoteKind::Inactive
                        && note.visual == format!("Inactive: {always}")
                        && note.feedback.contains(&always)),
                "{source:?} {edits:?}: {effect:?}"
            );
            assert!(!effect.has_live_effect, "{source:?} {edits:?}: {effect:?}");
        }
        for (source, motion) in [
            ("", motion),
            ("motion = \"auto\"\n", motion),
            ("motion = \"reduced\"\n", motion),
            (
                "motion = \"auto\"\n",
                crate::native_app::ViewMotionCx {
                    system_reduced: true,
                    ..motion
                },
            ),
        ] {
            let effect = projected_effect(source, &[(key, value)], key, availability, motion);
            assert!(
                !effect_note_contains(&effect, &always) && effect.has_live_effect,
                "{source:?} {motion:?}: {effect:?}"
            );
        }
    }
}

#[test]
fn effect_projection_covers_live_motion_and_specific_child_dependencies() {
    let availability = audited_availability();
    for (source, motion, expected) in [
        (
            "motion = \"reduced\"\ncursor_trail = true\ncursor_trail_style = \"comet\"\n",
            crate::native_app::ViewMotionCx::default(),
            "Inactive: Reduce motion",
        ),
        (
            "motion = \"auto\"\ncursor_trail = true\ncursor_trail_style = \"comet\"\n",
            crate::native_app::ViewMotionCx {
                system_reduced: true,
                ..crate::native_app::ViewMotionCx::default()
            },
            "System Reduce Motion",
        ),
        (
            "motion = \"auto\"\nload_adaptive_motion = true\ncursor_trail = true\ncursor_trail_style = \"comet\"\n",
            crate::native_app::ViewMotionCx {
                performance_reduced: true,
                ..crate::native_app::ViewMotionCx::default()
            },
            "heavy load",
        ),
        (
            "motion = \"full\"\ncursor_trail = true\ncursor_trail_style = \"comet\"\n",
            crate::native_app::ViewMotionCx {
                focused: false,
                ..crate::native_app::ViewMotionCx::default()
            },
            "window unfocused",
        ),
    ] {
        let effect = projected_effect(
            source,
            &[(prefs::EDIT_CURSOR_TRAIL_RADIUS, "1.1")],
            prefs::EDIT_CURSOR_TRAIL_RADIUS,
            availability,
            motion,
        );
        assert!(effect_note_contains(&effect, expected), "{effect:?}");
        assert!(!effect.has_live_effect);
    }

    let cases = [
        (
            "cursor_trail = true\ncursor_trail_style = \"off\"\n",
            prefs::EDIT_CURSOR_TRAIL_RADIUS,
            "1.0",
            "Cursor style Off",
        ),
        (
            "cursor_trail = true\ncursor_trail_style = \"water\"\n",
            prefs::EDIT_CURSOR_FIRE_SHIMMER,
            "true",
            "needs the Fire style",
        ),
        (
            "theme = \"Dracula\"\ncursor_trail = true\ncursor_trail_bloom = false\n",
            prefs::EDIT_CURSOR_TRAIL_BLOOM_RADIUS,
            "2.4",
            "Bloom is Off",
        ),
        (
            "[packages]\nenabled = false\n",
            prefs::EDIT_PACKAGES_AUTO_INSTALL,
            "true",
            "Waits until Keep ALab tools up to date is on",
        ),
        (
            "ligatures = false\n",
            prefs::EDIT_CURSOR_BREAK_LIGATURES,
            "true",
            "ligatures are Off",
        ),
        (
            "[sparkle_words.profanity]\nstyle = \"nova\"\n",
            "sparkle_words.profanity.supernova_chance",
            "50",
            "Rainbow style",
        ),
        (
            "[sparkle_words.profanity]\nstyle = \"rainbow\"\n",
            "sparkle_words.profanity.magic",
            "true",
            "Nova style",
        ),
        (
            "[sparkle_words.feline]\nstyle = \"paw\"\n",
            "sparkle_words.feline.magic",
            "true",
            "Cat graphic",
        ),
        (
            "[sparkle_words.profanity]\nenabled = false\n[sparkle_words.feline]\nenabled = true\n",
            "sparkle_words.ink.strength",
            "0.8",
            "Sparkle words is Off",
        ),
        (
            "[sparkle_words.profanity]\nenabled = true\nstyle = \"rainbow\"\n[sparkle_words.feline]\nenabled = true\n",
            "sparkle_words.ink.sweep_ms",
            "1200",
            "TwoTone ink",
        ),
        (
            "[sparkle_words.emphasis]\nenabled = true\n",
            "sparkle_words.emphasis.enabled",
            "true",
            "default Emphasis",
        ),
    ];
    for (source, key, value, expected) in cases {
        let effect = projected_effect(
            source,
            &[(key, value)],
            key,
            availability,
            crate::native_app::ViewMotionCx::default(),
        );
        assert!(effect_note_contains(&effect, expected), "{key}: {effect:?}");
        assert!(!effect.has_live_effect, "{key}");
    }

    let auto_install = projected_effect(
        "[packages]\nenabled = true\n",
        &[(prefs::EDIT_PACKAGES_AUTO_INSTALL, "false")],
        prefs::EDIT_PACKAGES_AUTO_INSTALL,
        availability,
        crate::native_app::ViewMotionCx::default(),
    );
    assert!(
        !effect_note_contains(&auto_install, "Keep ALab tools up to date is Off"),
        "the consent is not dormant while the switch is on: {auto_install:?}"
    );
}

#[test]
fn custom_spec_dependencies_use_typed_reachable_consumers() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();
    let custom = |recipe: &str| {
        format!(
            "[sparkle_words.profanity]\nstyle = \"rainbow\"\n\
             [[sparkle_words.custom]]\nwords = [\"typedword\"]\n{recipe}\n"
        )
    };
    let effect = |source: &str, key: &str, value: &str| {
        projected_effect(source, &[(key, value)], key, availability, motion)
    };

    for (recipe, expected_live) in [
        ("burst = { kind = \"nova\", chance = 1 }", true),
        (
            "ink = { colorway = \"twotone:#112233,#445566\" }\n\
             burst = { kind = \"nova\", chance = 0 }",
            true,
        ),
        ("burst = { kind = \"nova\", chance = 0 }", false),
        ("burst = { kind = \"glow\", chance = 100 }", false),
        ("burst = { kind = \"supernova\", chance = 100 }", false),
        ("graphic = { collection = \"cats\" }", false),
    ] {
        let projected = effect(&custom(recipe), "sparkle_words.profanity.magic", "true");
        assert_eq!(
            !effect_note_contains(&projected, "Nova style"),
            expected_live,
            "magic consumer mismatch for {recipe}: {projected:?}"
        );
    }
    let ink_off_nova_twotone = concat!(
        "[sparkle_words.profanity]\nstyle = \"rainbow\"\n",
        "[sparkle_words.ink]\nenabled = false\n",
        "[[sparkle_words.custom]]\nwords = [\"typedword\"]\n",
        "ink = \"twotone:#112233,#445566\"\n",
        "burst = { kind = \"nova\", chance = 0 }\n",
    );
    let projected = effect(
        ink_off_nova_twotone,
        "sparkle_words.profanity.magic",
        "true",
    );
    assert!(
        effect_note_contains(&projected, "Nova style"),
        "TwoTone can consume Nova magic only while global keyword ink is On"
    );

    for (recipe, expected_live) in [
        ("burst = { kind = \"sparkle\", chance = 1 }", true),
        ("burst = { kind = \"starburst\", chance = 1 }", true),
        ("burst = { kind = \"sparkle\", chance = 0 }", false),
        ("burst = { kind = \"nova\", chance = 100 }", false),
        ("burst = { kind = \"glow\", chance = 100 }", false),
        ("graphic = { collection = \"cats\" }", false),
    ] {
        let projected = effect(
            &custom(recipe),
            "sparkle_words.profanity.palette",
            "[\"#112233\", \"#445566\"]",
        );
        assert_eq!(
            !effect_note_contains(&projected, "Sparkle/Starburst"),
            expected_live,
            "legacy burst consumer mismatch for {recipe}: {projected:?}"
        );
    }

    let shadowed = concat!(
        "[sparkle_words.profanity]\nstyle = \"rainbow\"\n",
        "[[sparkle_words.custom]]\nwords = [\"sameword\"]\n",
        "burst = { kind = \"nova\", chance = 100 }\n",
        "[[sparkle_words.custom]]\nwords = [\"sameword\"]\n",
        "graphic = { collection = \"cats\" }\n",
    );
    let state = SettingsViewState::new(&aterm_toml::from_str(shadowed).unwrap());
    assert_eq!(
        state.sparkle_spec_consumers,
        Some(aterm_effects::spec::SpecConsumerCapabilities::default()),
        "an unreachable overridden recipe cannot keep a shared setting live"
    );
    let projected = effect(shadowed, "sparkle_words.profanity.magic", "true");
    assert!(effect_note_contains(&projected, "Nova style"));

    let empty_word = custom("burst = { kind = \"nova\", chance = 100 }")
        .replace("words = [\"typedword\"]", "words = [\"   \"]");
    let projected = effect(&empty_word, "sparkle_words.profanity.magic", "true");
    assert!(
        effect_note_contains(&projected, "Nova style"),
        "an entry without an admitted word is not a consumer"
    );
}

#[test]
fn dependent_style_projection_uses_runtime_fallbacks_not_raw_enum_text() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();

    let supernova = projected_effect(
        "[sparkle_words.profanity]\nstyle = \"laser\"\n",
        &[("sparkle_words.profanity.supernova_chance", "20")],
        "sparkle_words.profanity.supernova_chance",
        availability,
        motion,
    );
    assert!(
        !effect_note_contains(&supernova, "Rainbow style only"),
        "unknown profanity style resolves to Rainbow: {supernova:?}"
    );

    for key in ["sparkle_words.ink.sweep_ms", "sparkle_words.ink.loop"] {
        let projected = projected_effect(
            "[sparkle_words.profanity]\nstyle = \"laser\"\n",
            &[(
                key,
                if key.ends_with("loop") {
                    "true"
                } else {
                    "1200"
                },
            )],
            key,
            availability,
            motion,
        );
        assert!(
            effect_note_contains(
                &projected,
                if key.ends_with("loop") {
                    "class TwoTone only"
                } else {
                    "TwoTone ink only"
                }
            ),
            "unknown style is Rainbow, not a synthetic TwoTone style: {projected:?}"
        );
    }

    let spaced_nova = projected_effect(
        "[sparkle_words.profanity]\nstyle = \" Nova \"\n",
        &[("sparkle_words.profanity.magic", "true")],
        "sparkle_words.profanity.magic",
        availability,
        motion,
    );
    assert!(
        !effect_note_contains(&spaced_nova, "Nova style only"),
        "trimmed case-insensitive Nova must use the owning runtime mode: {spaced_nova:?}"
    );
    let spaced_sparkle = projected_effect(
        "[sparkle_words.profanity]\nstyle = \" Sparkle \"\n",
        &[("sparkle_words.profanity.palette", "[]")],
        "sparkle_words.profanity.palette",
        availability,
        motion,
    );
    assert!(
        !effect_note_contains(&spaced_sparkle, "Sparkle/Starburst only"),
        "trimmed case-insensitive Sparkle must use the owning runtime mode: {spaced_sparkle:?}"
    );

    let cased_paw = projected_effect(
        "[sparkle_words.feline]\nstyle = \" Paw \"\n",
        &[("sparkle_words.feline.magic", "true")],
        "sparkle_words.feline.magic",
        availability,
        motion,
    );
    assert!(
        effect_note_contains(&cased_paw, "Cat graphic"),
        "trimmed case-insensitive Paw selects the legacy ink-only runtime mode"
    );
    let cased_style = projected_effect(
        "[sparkle_words.feline]\nstyle = \" Paw \"\n",
        &[("sparkle_words.feline.style", " Paw ")],
        "sparkle_words.feline.style",
        availability,
        motion,
    );
    assert!(effect_note_contains(&cased_style, "Legacy Paw"));

    let paw_product = projected_effect(
        "[sparkle_words.feline]\nenabled = true\nstyle = \"paw\"\n",
        &[(KEYWORD_KITTIES_KEY, "true")],
        KEYWORD_KITTIES_KEY,
        availability,
        motion,
    );
    assert!(effect_note_contains(&paw_product, "no kitty graphic"));
    assert!(effect_note_contains(&paw_product, "legacy Paw ink only"));
    assert!(
        paw_product.has_live_effect,
        "Paw still has a live ink effect; Top must describe it rather than pretending the toggle is inert"
    );

    let exact_paw = projected_effect(
        "[sparkle_words.feline]\nstyle = \"paw\"\n",
        &[("sparkle_words.feline.magic", "true")],
        "sparkle_words.feline.magic",
        availability,
        motion,
    );
    assert!(effect_note_contains(&exact_paw, "Cat graphic"));
}

#[test]
fn invalid_registered_enum_and_color_values_disclose_runtime_fallbacks() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();
    for (source, key, value, expected) in [
        (
            "background_material = \"not-a-material\"\nbackground_opacity = 0.8\n",
            prefs::EDIT_BACKGROUND_MATERIAL,
            "not-a-material",
            "Invalid choice",
        ),
        (
            "window_colorspace = \"laser-rgb\"\n",
            prefs::EDIT_WINDOW_COLORSPACE,
            "laser-rgb",
            "Invalid choice",
        ),
        (
            "foreground = \"purple-ish\"\n",
            prefs::EDIT_FOREGROUND,
            "purple-ish",
            "Invalid color",
        ),
    ] {
        let projected = projected_effect(source, &[(key, value)], key, availability, motion);
        assert!(
            effect_note_contains(&projected, expected),
            "{key}: {projected:?}"
        );
        assert!(!projected.has_live_effect);
    }

    let valid = projected_effect(
        "foreground = \"#a0b1c2\"\n",
        &[(prefs::EDIT_FOREGROUND, "#a0b1c2")],
        prefs::EDIT_FOREGROUND,
        availability,
        motion,
    );
    assert!(!effect_note_contains(&valid, "Invalid color"));
}

#[test]
fn a_setting_with_no_effect_here_paints_idle() {
    let control = |source: &str| {
        let (mut runtime, instance, view) = setup();
        replace_settings_source(&mut runtime, view, source.to_string());
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::Modified),
                    value: None,
                }),
            )
            .unwrap();
        let compiled = compile_settings_view(&runtime, instance, view, &view_cx());
        let key = format!("settings/control/{}", prefs::EDIT_BIDI);
        let node = compiled
            .semantic(&UiKey::new(key.clone()))
            .unwrap_or_else(|| panic!("{key} is on Modified"));
        (node.label.clone(), node.state.expect("a control"))
    };
    let (label, state) = control("bidi = \"sideways\"\n");
    assert!(
        label.contains("outside this setting's registered choices"),
        "{label}"
    );
    assert!(state.muted && state.enabled, "{label}: {state:?}");
    let (label, state) = control("bidi = \"explicit\"\n");
    assert!(!state.muted, "{label}: {state:?}");
}

#[test]
fn custom_ink_and_emphasis_dependencies_match_runtime_ownership() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();
    let effect = |source: &str, key: &str, value: &str| {
        projected_effect(source, &[(key, value)], key, availability, motion)
    };
    let source = |recipe: &str| {
        format!(
            "[sparkle_words.profanity]\nstyle = \"rainbow\"\n\
             [[sparkle_words.custom]]\nwords = [\"inkword\"]\n{recipe}\n"
        )
    };

    let rainbow: Config = aterm_toml::from_str(&source("ink = \"rainbow\"")).unwrap();
    let rainbow = SettingsViewState::new(&rainbow)
        .sparkle_spec_consumers
        .unwrap();
    assert!(rainbow.rainbow_ink);
    assert!(!rainbow.twotone_ink);

    let twotone_source = source("ink = \"twotone:#112233,#445566\"");
    let twotone: Config = aterm_toml::from_str(&twotone_source).unwrap();
    let twotone = SettingsViewState::new(&twotone)
        .sparkle_spec_consumers
        .unwrap();
    assert!(twotone.twotone_ink);
    assert!(!twotone.rainbow_ink);

    let graphic: Config =
        aterm_toml::from_str(&source("graphic = { collection = \"cats\" }")).unwrap();
    assert_eq!(
        SettingsViewState::new(&graphic).sparkle_spec_consumers,
        Some(aterm_effects::spec::SpecConsumerCapabilities::default())
    );

    let mut self_glow_table = aterm_effects::spec::SpecTable::default();
    self_glow_table.insert_custom(
        "glowword",
        aterm_effects::spec::WordEffectSpec {
            ink: Some(aterm_effects::spec::InkSpec {
                colorway: aterm_effects::spec::Colorway::SelfGlow {
                    lift: 0.2,
                    amp: 0.5,
                    window_ms: 900,
                },
                sweep_once: true,
            }),
            ..Default::default()
        },
    );
    assert_eq!(
        self_glow_table.consumer_capabilities(),
        aterm_effects::spec::SpecConsumerCapabilities::default(),
        "SelfGlow owns its intensity and cannot consume shared strength/sweep"
    );

    let sweep = effect(&twotone_source, "sparkle_words.ink.sweep_ms", "1200");
    assert!(
        !effect_note_contains(&sweep, "TwoTone ink only"),
        "custom TwoTone consumes the shared sweep duration"
    );
    let rainbow_sweep = effect(
        &source("ink = \"rainbow\""),
        "sparkle_words.ink.sweep_ms",
        "1200",
    );
    assert!(effect_note_contains(&rainbow_sweep, "TwoTone ink only"));

    let loop_projection = effect(&twotone_source, "sparkle_words.ink.loop", "true");
    assert!(
        effect_note_contains(&loop_projection, "class TwoTone only"),
        "custom sweep_once ownership must not make global ink.loop live"
    );

    let custom_emphasis = effect(&twotone_source, "sparkle_words.emphasis.enabled", "true");
    assert!(
        effect_note_contains(&custom_emphasis, "default Emphasis"),
        "custom overrides bypass the emphasis class gate"
    );
    let extra_words = effect(
        "[sparkle_words.emphasis]\nenabled = true\nextra_words = [\"wow\"]\n",
        "sparkle_words.emphasis.enabled",
        "true",
    );
    assert!(!effect_note_contains(&extra_words, "default Emphasis"));

    let blank_words = effect(
        "[sparkle_words.emphasis]\nenabled = true\nextra_words = [\"\", \"   \"]\n",
        "sparkle_words.emphasis.enabled",
        "true",
    );
    assert!(effect_note_contains(&blank_words, "default Emphasis"));

    let ink_off = effect(
        "[sparkle_words.ink]\nenabled = false\n\
         [sparkle_words.emphasis]\nenabled = true\nextra_words = [\"wow\"]\n",
        "sparkle_words.emphasis.enabled",
        "true",
    );
    assert!(effect_note_contains(&ink_off, "Ink shimmer Off"));
}

#[test]
fn custom_consumers_obey_master_product_and_ink_parent_gates() {
    let availability = audited_availability();
    let motion = crate::native_app::ViewMotionCx::default();
    let cases = [
        (
            "[sparkle_words]\nenabled = false\n\
             [[sparkle_words.custom]]\nwords = [\"nova\"]\nburst = { kind = \"nova\", chance = 100 }\n",
            "sparkle_words.profanity.magic",
            "true",
            "all word effects are switched off in aterm.toml",
        ),
        (
            "[sparkle_words.profanity]\nenabled = false\nstyle = \"rainbow\"\n\
             [[sparkle_words.custom]]\nwords = [\"nova\"]\nburst = { kind = \"nova\", chance = 100 }\n",
            "sparkle_words.profanity.magic",
            "true",
            "Sparkle words is Off",
        ),
        (
            "[sparkle_words.profanity]\nenabled = false\n\
             [[sparkle_words.custom]]\nwords = [\"ink\"]\nink = \"twotone:#112233,#445566\"\n",
            "sparkle_words.ink.sweep_ms",
            "1200",
            "Sparkle words is Off",
        ),
        (
            "[sparkle_words.ink]\nenabled = false\n\
             [[sparkle_words.custom]]\nwords = [\"ink\"]\nink = \"twotone:#112233,#445566\"\n",
            "sparkle_words.ink.sweep_ms",
            "1200",
            "Ink shimmer is Off",
        ),
        (
            "[sparkle_words.profanity]\nenabled = false\n\
             [sparkle_words.feline]\nenabled = false\n",
            "sparkle_words.reduced_motion",
            "true",
            "Sparkle words and Keyword kitties are Off",
        ),
        (
            "[sparkle_words.profanity]\nenabled = false\n\
             [sparkle_words.feline]\nenabled = false\n",
            "sparkle_words.suppress_in_alt_screen",
            "true",
            "Sparkle words and Keyword kitties are Off",
        ),
        (
            "[sparkle_words.profanity]\nenabled = false\n\
             [sparkle_words.feline]\nenabled = false\n",
            "sparkle_words.ink.enabled",
            "true",
            "Sparkle words and Keyword kitties are Off",
        ),
        (
            "[sparkle_words.profanity]\nenabled = false\n\
             [sparkle_words.feline]\nenabled = false\n",
            SPARKLE_MASTER_KEY,
            "true",
            "Sparkle words and Keyword kitties are Off",
        ),
    ];
    for (source, key, value, expected) in cases {
        let projected = projected_effect(source, &[(key, value)], key, availability, motion);
        assert!(
            effect_note_contains(&projected, expected),
            "{key} did not preserve {expected:?}: {projected:?}"
        );
        assert!(!projected.has_live_effect);
    }
}

#[test]
fn settings_projection_consumes_the_admitted_toy_pack_capability_carrier() {
    let motion = crate::native_app::ViewMotionCx::default();
    let source = include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../aterm-effects/toy-packs/community/tiny-triumphs/pack.toml"
    ));
    let pack = aterm_effects::spec::compile_toy_pack_toml(source).unwrap();
    let (_, table, _) = pack.into_parts();
    let consumers = table.consumer_capabilities();
    assert!(consumers.sparkle_or_starburst_burst);

    let assets = Arc::new(crate::app_config::ConfigAssetCatalog {
        trail_style: crate::app_config::TrailStyleCache::empty(),
        kitty_sprite: crate::app_config::KittySpriteAsset::BuiltIn,
        wallpaper: crate::app_config::WallpaperAsset::None,
        themes: crate::app_config::ThemeCatalog::empty(),
        sparkle_spec_consumers: Some(Arc::new(consumers)),
    });
    let config: Config =
        aterm_toml::from_str("[sparkle_words.profanity]\nstyle = \"rainbow\"\n").unwrap();
    let state = SettingsViewState::from_config_and_assets(&config, assets);
    let projected = setting_effect_projection(
        &state,
        Some(&test_patch(&[("sparkle_words.profanity.palette", "[]")])),
        "sparkle_words.profanity.palette",
        audited_availability(),
        motion,
    );
    assert!(
        !effect_note_contains(&projected, "Sparkle/Starburst"),
        "Settings must use the worker-admitted Toy Pack table, not inline-path inference"
    );

    let exact_all_false = Arc::new(crate::app_config::ConfigAssetCatalog {
        trail_style: crate::app_config::TrailStyleCache::empty(),
        kitty_sprite: crate::app_config::KittySpriteAsset::BuiltIn,
        wallpaper: crate::app_config::WallpaperAsset::None,
        themes: crate::app_config::ThemeCatalog::empty(),
        sparkle_spec_consumers: Some(Arc::new(Default::default())),
    });
    let inline_nova: Config = aterm_toml::from_str(concat!(
        "[sparkle_words.profanity]\nstyle = \"rainbow\"\n",
        "[[sparkle_words.custom]]\nwords = [\"shadowed\"]\n",
        "burst = { kind = \"nova\", chance = 100 }\n",
    ))
    .unwrap();
    let state = SettingsViewState::from_config_and_assets(&inline_nova, exact_all_false);
    assert_eq!(
        state.sparkle_spec_consumers,
        Some(aterm_effects::spec::SpecConsumerCapabilities::default()),
        "Some(all-false) is an observed worker verdict, not an empty-catalog sentinel"
    );
    let projected = setting_effect_projection(
        &state,
        Some(&test_patch(&[("sparkle_words.profanity.magic", "true")])),
        "sparkle_words.profanity.magic",
        audited_availability(),
        motion,
    );
    assert!(
        effect_note_contains(&projected, "Nova style"),
        "a shadowed inline Nova must not leak back through fallback inference"
    );

    let preliminary = SettingsViewState::from_config_and_assets(
        &inline_nova,
        crate::app_config::ConfigAssetCatalog::empty(),
    );
    assert_eq!(preliminary.sparkle_spec_consumers, None);
    let projected = setting_effect_projection(
        &preliminary,
        Some(&test_patch(&[("sparkle_words.profanity.magic", "true")])),
        "sparkle_words.profanity.magic",
        audited_availability(),
        motion,
    );
    assert!(
        effect_note_contains(&projected, "recipe admission pending"),
        "None is an explicit unobserved state, never permission to infer inline authority"
    );
    assert!(!effect_note_contains(&projected, "Nova style"));

    let product_off: Config = aterm_toml::from_str(
        "[sparkle_words.profanity]\nenabled = false\n\
         [sparkle_words.emphasis]\nenabled = false\n",
    )
    .unwrap();
    let product_off = SettingsViewState::from_config_and_assets(
        &product_off,
        crate::app_config::ConfigAssetCatalog::empty(),
    );
    for key in [
        "sparkle_words.ink.strength",
        "sparkle_words.ink.sweep_ms",
        "sparkle_words.ink.loop",
        "sparkle_words.emphasis.enabled",
    ] {
        let value = match key {
            "sparkle_words.ink.strength" => "0.8",
            "sparkle_words.ink.sweep_ms" => "1200",
            "sparkle_words.ink.loop" | "sparkle_words.emphasis.enabled" => "true",
            _ => unreachable!("bounded pending-consumer key"),
        };
        let projected = setting_effect_projection(
            &product_off,
            Some(&test_patch(&[(key, value)])),
            key,
            audited_availability(),
            motion,
        );
        assert!(
            effect_note_contains(&projected, "Sparkle words is Off"),
            "the hard product gate decides {key} even before recipe admission: {projected:?}"
        );
        assert!(!effect_note_contains(
            &projected,
            "recipe admission pending"
        ));
    }

    let unresolved_recipes: Config = aterm_toml::from_str(
        "[sparkle_words.profanity]\nenabled = true\nstyle = \"rainbow\"\n\
         [sparkle_words.emphasis]\nenabled = false\n",
    )
    .unwrap();
    let unresolved_recipes = SettingsViewState::from_config_and_assets(
        &unresolved_recipes,
        crate::app_config::ConfigAssetCatalog::empty(),
    );
    for (key, value) in [
        ("sparkle_words.profanity.magic", "true"),
        ("sparkle_words.profanity.palette", "[]"),
        ("sparkle_words.ink.sweep_ms", "1200"),
        ("sparkle_words.ink.loop", "true"),
        ("sparkle_words.emphasis.enabled", "true"),
    ] {
        let projected = setting_effect_projection(
            &unresolved_recipes,
            Some(&test_patch(&[(key, value)])),
            key,
            audited_availability(),
            motion,
        );
        assert!(
            effect_note_contains(&projected, "recipe admission pending"),
            "unobserved recipes can still decide {key}: {projected:?}"
        );
    }

    let strength = setting_effect_projection(
        &unresolved_recipes,
        Some(&test_patch(&[("sparkle_words.ink.strength", "0.8")])),
        "sparkle_words.ink.strength",
        audited_availability(),
        motion,
    );
    assert!(strength.has_live_effect);
    assert!(!effect_note_contains(&strength, "recipe admission pending"));

    let ink_off: Config = aterm_toml::from_str(
        "[sparkle_words.profanity]\nenabled = true\n\
         [sparkle_words.ink]\nenabled = false\n\
         [sparkle_words.emphasis]\nenabled = true\n",
    )
    .unwrap();
    let ink_off = SettingsViewState::from_config_and_assets(
        &ink_off,
        crate::app_config::ConfigAssetCatalog::empty(),
    );
    let emphasis = setting_effect_projection(
        &ink_off,
        Some(&test_patch(&[("sparkle_words.emphasis.enabled", "true")])),
        "sparkle_words.emphasis.enabled",
        audited_availability(),
        motion,
    );
    assert!(effect_note_contains(&emphasis, "Ink shimmer is Off"));
    assert!(!effect_note_contains(&emphasis, "recipe admission pending"));
}

