fn post_newest(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    evict: bool,
) {
    let mut state = sample_messages();
    let mut newest = state.entries[3].clone();
    newest.id = 41;
    newest.title = "config warning 41".to_string();
    state.entries.insert(0, newest);
    if evict {
        state.entries.retain(|entry| entry.id != 1);
    } else {
        for (tag, count) in &mut state.tags {
            if tag == "config" {
                *count += 1;
            }
        }
    }
    state.revision = 8;
    assert!(runtime.replace_settings_messages(state, 8));
    runtime
        .dispatch(instance, view, AppEvent::MessagesChanged { revision: 8 })
        .unwrap();
}

#[test]
fn a_publication_never_leaves_the_keyboard_on_an_entry_it_moved_away() {
    let cx = view_cx_at(774.0, 612.0);
    let shown_at_top = {
        let (runtime, instance, view) = setup_with_messages();
        message_rows(&compile_settings_view(&runtime, instance, view, &cx))
    };
    let mut pushed = false;
    for id in shown_at_top {
        let (mut runtime, instance, view) = setup_with_messages();
        let _ = compile_settings_view(&runtime, instance, view, &cx);
        messages_action(
            &mut runtime,
            instance,
            view,
            &format!("settings/messages/row/{id}/title"),
        );
        let copy = format!("settings/messages/row/{id}/copy");
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        if messages_view_state(&runtime, view).page_scroll != 0
            || compiled.semantic(&UiKey::new(copy.clone())).is_none()
        {
            continue;
        }
        focus_key(&mut runtime, instance, view, &copy);
        post_newest(&mut runtime, instance, view, false);
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        pushed |= !message_rows(&compiled).contains(&id);
        let (focus, shown) = focus_on_page(&runtime, instance, view, &cx);
        assert!(
            shown,
            "entry {id}: the keyboard is on {focus:?}, which the view does not show"
        );
    }
    assert!(
        pushed,
        "premise: a record posted pushed an entry opened low in the view out of it"
    );
    let (mut runtime, instance, view) = setup_with_messages();
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(250))
        .unwrap();
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/1/title",
    );
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    let copy = "settings/messages/row/1/copy";
    focus_key(&mut runtime, instance, view, copy);
    let (_, shown) = focus_on_page(&runtime, instance, view, &cx);
    assert!(shown, "premise: the oldest entry's Copy is on the page");
    post_newest(&mut runtime, instance, view, true);
    let (focus, shown) = focus_on_page(&runtime, instance, view, &cx);
    assert!(
        shown,
        "eviction: the keyboard is on {focus:?}, which the view does not show"
    );
}

fn publish_told_on(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    told: u64,
    standing: bool,
) {
    let mut state = sample_messages();
    let mut row = state
        .entries
        .iter()
        .find(|entry| entry.id == told)
        .expect("the entry")
        .clone();
    state.entries.retain(|entry| entry.id != told);
    if standing {
        row.id = 41;
        row.title = "config warning, in its next words".to_string();
        state.entries.insert(0, row);
        state.told_on = vec![(told, 41)];
    }
    state.revision = 8;
    assert!(runtime.replace_settings_messages(state, 8));
    runtime
        .dispatch(instance, view, AppEvent::MessagesChanged { revision: 8 })
        .unwrap();
}

#[test]
fn an_open_entry_a_later_row_tells_on_stays_open_as_that_row() {
    let cx = view_cx_at(774.0, 612.0);
    for standing in [true, false] {
        let (mut runtime, instance, view) = setup_with_messages();
        let _ = compile_settings_view(&runtime, instance, view, &cx);
        select_message(&mut runtime, instance, view, 10);
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        let scroll = messages_view_state(&runtime, view).page_scroll;
        assert_ne!(scroll, 0, "premise: deep in the log");
        let before = message_rows(&compiled);
        assert_eq!(before.first(), Some(&10), "premise");
        publish_told_on(&mut runtime, instance, view, 10, standing);
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        let state = messages_view_state(&runtime, view);
        let rows = message_rows(&compiled);
        assert!(!rows.contains(&10), "it left the list");
        if standing {
            assert_eq!(state.messages_selected, Some(41), "open as its row");
            assert_eq!(rows.first(), Some(&41), "where the entry was: {rows:?}");
            assert!(
                compiled
                    .semantic(&UiKey::new("settings/messages/row/41/copy"))
                    .is_some(),
                "open"
            );
        } else {
            assert_eq!(state.messages_selected, Some(10), "nothing re-pointed");
            assert!(
                before
                    .iter()
                    .filter(|id| **id != 10)
                    .all(|id| rows.contains(id)),
                "the list kept its place: {before:?} -> {rows:?}"
            );
        }
    }
    let (mut runtime, instance, view) = setup_with_messages();
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    select_message(&mut runtime, instance, view, 10);
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    focus_key(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/9/title",
    );
    let (_, shown) = focus_on_page(&runtime, instance, view, &cx);
    assert!(shown, "premise: entry 9 is on the page below the open one");
    publish_told_on(&mut runtime, instance, view, 9, true);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let state = messages_view_state(&runtime, view);
    let title = UiKey::new("settings/messages/row/41/title");
    assert_eq!(state.common.last_focus.as_ref(), Some(&title));
    assert!(compiled.semantic(&title).is_some(), "seated");
    assert_eq!(
        state.messages_selected,
        Some(10),
        "the open entry as it was"
    );
    let (mut runtime, instance, view) = setup_with_messages();
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    publish_told_on(&mut runtime, instance, view, 35, true);
    select_message(&mut runtime, instance, view, 35);
    assert_eq!(
        messages_view_state(&runtime, view).messages_selected,
        Some(41)
    );
}

#[test]
fn a_row_told_on_at_the_top_of_the_view_keeps_the_readers_place() {
    let cx = view_cx_at(774.0, 612.0);
    for open in [false, true] {
        let (mut runtime, instance, view) = setup_with_messages();
        let _ = compile_settings_view(&runtime, instance, view, &cx);
        runtime
            .dispatch(instance, view, AppEvent::ScrollLines(12))
            .unwrap();
        let before = message_rows(&compile_settings_view(&runtime, instance, view, &cx));
        assert!(before.len() >= 4, "premise: a view of rows {before:?}");
        let (top, read) = (before[0], before[before.len() - 2]);
        assert_ne!(top, 40, "premise: scrolled into the log");
        let keyboard = format!("settings/messages/row/{read}/title");
        focus_key(&mut runtime, instance, view, &keyboard);
        if open {
            messages_action(
                &mut runtime,
                instance,
                view,
                &format!("settings/messages/row/{top}/title"),
            );
            focus_key(&mut runtime, instance, view, &keyboard);
        }
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        let before = message_rows(&compiled);
        assert_eq!(before.first(), Some(&top), "premise: {before:?}");
        assert_eq!(
            messages_view_state(&runtime, view).messages_selected,
            open.then_some(top),
            "premise"
        );
        publish_told_on(&mut runtime, instance, view, top, true);
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        let after = message_rows(&compiled);
        let state = messages_view_state(&runtime, view);
        if open {
            assert_eq!(after.first(), Some(&41), "open: {before:?} -> {after:?}");
            assert_eq!(state.messages_selected, Some(41));
            continue;
        }
        let kept: Vec<u64> = before.iter().copied().filter(|id| *id != top).collect();
        assert!(
            kept.iter().all(|id| after.contains(id)),
            "the view lost rows: {before:?} -> {after:?}"
        );
        assert!(!after.contains(&41), "jumped to the head: {after:?}");
        assert_eq!(state.messages_selected, None, "nothing opened");
        assert_eq!(
            state.common.last_focus.as_ref().map(UiKey::as_str),
            Some(keyboard.as_str()),
            "the keyboard moved"
        );
        assert!(compiled.semantic(&UiKey::new(keyboard.as_str())).is_some());
    }
}

#[test]
fn a_publication_that_folds_the_tag_chips_moves_the_keyboard_with_them() {
    let cx = view_cx_at(760.0, 820.0);
    let chip = "settings/messages/filter/tag/crash";
    let (mut runtime, instance, view) = setup_with_messages();
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    focus_key(&mut runtime, instance, view, chip);
    messages_action(&mut runtime, instance, view, chip);
    let (focus, shown) = focus_on_page(&runtime, instance, view, &cx);
    assert!(
        shown && focus.as_ref().map(UiKey::as_str) == Some(chip),
        "premise: the wide page shows the focused crash chip, focus {focus:?}"
    );
    post_newest(&mut runtime, instance, view, false);
    let (focus, shown) = focus_on_page(&runtime, instance, view, &cx);
    assert!(
        shown && focus.as_ref().map(UiKey::as_str) == Some(chip),
        "a publication that kept the chips moved the keyboard to {focus:?}"
    );
    let publish = |runtime: &mut NativeRuntime, mut state: MessagesState, revision: u64| {
        state.revision = revision;
        assert!(runtime.replace_settings_messages(state, revision));
        runtime
            .dispatch(instance, view, AppEvent::MessagesChanged { revision })
            .unwrap();
        compile_settings_view(runtime, instance, view, &cx)
    };
    let compiled = publish(&mut runtime, script_tag_messages(2), 9);
    assert!(
        compiled.semantic(&UiKey::new(chip)).is_none()
            && compiled.semantic(&UiKey::new(MESSAGES_TAG_MENU)).is_some(),
        "premise: two new tags fold the chips into the Tag pop-up"
    );
    let (focus, shown) = focus_on_page(&runtime, instance, view, &cx);
    assert!(
        shown,
        "folded: the keyboard is on {focus:?}, which the page no longer shows"
    );
    assert_eq!(
        focus.as_ref().map(UiKey::as_str),
        Some(MESSAGES_TAG_MENU),
        "folded: the chip's keyboard goes to the pop-up's button"
    );
    let compiled = publish(&mut runtime, sample_messages(), 10);
    assert!(
        compiled.semantic(&UiKey::new(chip)).is_some()
            && compiled.semantic(&UiKey::new(MESSAGES_TAG_MENU)).is_none(),
        "premise: without the new tags the chips are back"
    );
    let (focus, shown) = focus_on_page(&runtime, instance, view, &cx);
    assert!(
        shown,
        "unfolded: the keyboard is on {focus:?}, which the page no longer shows"
    );
}

