fn painted_backdrop_at(prims: &[crate::widget::DrawPrim], upto: usize, x: f32, y: f32) -> [u8; 3] {
    use crate::widget::DrawPrim;
    let mut color = [0.0_f32; 3];
    let mut clips: Vec<(f32, f32, f32, f32)> = Vec::new();
    let inside =
        |(cx, cy, cw, ch): (f32, f32, f32, f32)| x >= cx && x < cx + cw && y >= cy && y < cy + ch;
    for prim in &prims[..upto] {
        match prim {
            DrawPrim::ClipPush { x, y, w, h } => clips.push((*x, *y, *w, *h)),
            DrawPrim::ClipPop => {
                clips.pop();
            }
            DrawPrim::Panel {
                x: px,
                y: py,
                w,
                h,
                fill,
                ..
            } if inside((*px, *py, *w, *h)) && clips.iter().all(|clip| inside(*clip)) => {
                let alpha = f32::from(fill[3]) / 255.0;
                for (channel, value) in color.iter_mut().enumerate() {
                    *value = *value * (1.0 - alpha) + f32::from(fill[channel]) * alpha;
                }
            }
            _ => {}
        }
    }
    color.map(|value| value.round() as u8)
}

fn painted_text_contrast(
    compiled: &crate::native_ui::CompiledUi,
    prims: &[crate::widget::DrawPrim],
    key: &str,
) -> Vec<(String, f32)> {
    use crate::widget::DrawPrim;
    let Some(rect) = compiled
        .paint
        .iter()
        .find(|node| node.key.as_str() == key)
        .map(|node| node.rect)
    else {
        return Vec::new();
    };
    prims
        .iter()
        .enumerate()
        .filter_map(|(index, prim)| {
            let DrawPrim::Text {
                x,
                baseline,
                s,
                px,
                color,
                ..
            } = prim
            else {
                return None;
            };
            let inside = *x >= rect.x - 0.5
                && *x <= rect.right()
                && *baseline >= rect.y
                && *baseline <= rect.bottom() + 0.5;
            if !inside {
                return None;
            }
            let under = painted_backdrop_at(prims, index, x + 1.0, baseline - px * 0.35);
            let alpha = f32::from(color[3]) / 255.0;
            let ink: [u8; 3] = std::array::from_fn(|channel| {
                (f32::from(under[channel]) * (1.0 - alpha) + f32::from(color[channel]) * alpha)
                    .round() as u8
            });
            Some((
                s.clone(),
                crate::native_appearance::contrast_ratio(ink, under),
            ))
        })
        .collect()
}

#[test]
fn messages_chrome_meets_contrast_on_github_light() {
    use crate::widget::DrawPrim;
    let light = {
        let parts = aterm_types::scheme::builtin("GitHub Light")
            .expect("a builtin scheme")
            .to_theme_parts();
        aterm_render::Theme {
            fg: parts.fg,
            bg: parts.bg,
            cursor: parts.cursor,
            selection: parts.selection,
        }
    };
    for (width, height) in [(1_200.0, 820.0), (1_074.0, 686.0), (738.0, 420.0)] {
        let (mut runtime, instance, view) = setup_with_these_messages(sample_messages());
        for filtered in [false, true] {
            if filtered {
                messages_action(
                    &mut runtime,
                    instance,
                    view,
                    "settings/messages/filter/warn",
                );
                messages_action(
                    &mut runtime,
                    instance,
                    view,
                    "settings/messages/filter/tag/update",
                );
            }
            let at = format!("{width}x{height} filtered={filtered}");
            let compiled =
                compile_settings_view(&runtime, instance, view, &view_cx_at(width, height));
            let prims = compiled.tray(light, 13.0).prims;
            let resting = |key: &str| {
                compiled
                    .semantic(&UiKey::new(key))
                    .is_some_and(|node| node.state.as_ref().is_none_or(|state| !state.selected))
            };
            let mut keys: Vec<&str> = compiled
                .semantics
                .iter()
                .map(|node| node.key.as_str())
                .filter(|key| {
                    (key.starts_with("settings/messages/filter/") && resting(key))
                        || *key == "settings/messages/status"
                        || *key == "settings/messages/no-match"
                        || *key == MESSAGES_TAG_MENU
                })
                .collect();
            keys.sort_unstable();
            assert!(keys.contains(&"settings/messages/status"), "{at}: {keys:?}");
            assert_eq!(
                keys.contains(&"settings/messages/no-match"),
                filtered,
                "{at}: the no-match line exactly when nothing is shown"
            );
            for key in &keys {
                let words = painted_text_contrast(&compiled, &prims, key);
                assert!(!words.is_empty(), "{at}: {key} paints its words");
                for (text, ratio) in words {
                    assert!(
                        ratio >= 4.5,
                        "{at}: {key} paints {text:?} at {ratio:.2}:1 on GitHub Light"
                    );
                }
                if !key.starts_with(MESSAGES_TAG_CHIPS) {
                    continue;
                }
                let rect = compiled
                    .paint
                    .iter()
                    .find(|node| node.key.as_str() == *key)
                    .expect("a painted chip")
                    .rect;
                let near = |a: f32, b: f32| (a - b).abs() < 0.6;
                assert!(
                    prims.iter().any(|prim| matches!(
                        prim,
                        DrawPrim::Panel { x, y, w, fill, .. }
                            if near(*x, rect.x) && near(*y, rect.y) && near(*w, rect.width)
                                && fill[3] == 255
                    )),
                    "{at}: the resting chip {key} paints an opaque fill"
                );
                assert!(
                    prims.iter().any(|prim| matches!(
                        prim,
                        DrawPrim::Stroke { x, y, .. }
                            if near(*x, rect.x + 0.5) && near(*y, rect.y + 0.5)
                    )),
                    "{at}: the resting chip {key} paints an edge"
                );
            }
        }
    }
}

#[test]
fn messages_filters_sit_on_a_card_and_chips_hold_3_to_1() {
    use crate::native_appearance::contrast_ratio;
    use crate::widget::DrawPrim;
    let light = {
        let parts = aterm_types::scheme::builtin("GitHub Light")
            .expect("a builtin scheme")
            .to_theme_parts();
        aterm_render::Theme {
            fg: parts.fg,
            bg: parts.bg,
            cursor: parts.cursor,
            selection: parts.selection,
        }
    };
    let over = |color: [u8; 4], under: [u8; 3]| -> [u8; 3] {
        let alpha = f32::from(color[3]) / 255.0;
        std::array::from_fn(|channel| {
            (f32::from(under[channel]) * (1.0 - alpha) + f32::from(color[channel]) * alpha).round()
                as u8
        })
    };
    for (theme_name, theme) in [
        ("GitHub Light", light),
        ("Default", aterm_render::Theme::default()),
    ] {
        let roles = crate::settings::Roles::from_theme(theme);
        for (width, height) in [(1_200.0, 820.0), (1_074.0, 686.0), (738.0, 420.0)] {
            let (mut runtime, instance, view) = setup_with_these_messages(sample_messages());
            for filtered in [false, true] {
                if filtered {
                    messages_action(
                        &mut runtime,
                        instance,
                        view,
                        "settings/messages/filter/warn",
                    );
                    messages_action(
                        &mut runtime,
                        instance,
                        view,
                        "settings/messages/filter/tag/update",
                    );
                }
                let at = format!("{theme_name} {width}x{height} filtered={filtered}");
                let compiled =
                    compile_settings_view(&runtime, instance, view, &view_cx_at(width, height));
                let prims = compiled.tray(theme, 13.0).prims;
                let rect_of = |key: &str| {
                    compiled
                        .paint
                        .iter()
                        .find(|node| node.key.as_str() == key)
                        .map(|node| node.rect)
                };
                let card = rect_of("settings/messages/filters")
                    .unwrap_or_else(|| panic!("{at}: the filters card"));
                let mut inside = vec!["settings/messages/status"];
                if filtered {
                    inside.push("settings/messages/no-match");
                }
                let chips: Vec<&str> = compiled
                    .paint
                    .iter()
                    .map(|node| node.key.as_str())
                    .filter(|key| {
                        key.starts_with("settings/messages/filter/")
                            && matches!(
                                compiled
                                    .paint
                                    .iter()
                                    .find(|node| node.key.as_str() == *key)
                                    .map(|node| &node.content),
                                Some(UiContent::Button(_))
                            )
                    })
                    .collect();
                assert!(chips.len() >= 2, "{at}: chips {chips:?}");
                for key in inside.iter().chain(chips.iter()) {
                    let rect = rect_of(key).unwrap_or_else(|| panic!("{at}: {key}"));
                    assert!(
                        rect.x >= card.x - 0.5
                            && rect.right() <= card.right() + 0.5
                            && rect.y >= card.y - 0.5
                            && rect.bottom() <= card.bottom() + 0.5,
                        "{at}: {key} {rect:?} is on the card {card:?}"
                    );
                }
                let mut resting_fill = None;
                let mut selected_fill = None;
                for key in &chips {
                    let rect = rect_of(key).expect("a chip");
                    let selected = compiled
                        .semantic(&UiKey::new(*key))
                        .and_then(|node| node.state.as_ref())
                        .is_some_and(|state| state.selected);
                    let index = prims
                        .iter()
                        .position(|prim| {
                            matches!(prim, DrawPrim::Panel { x, y, w, .. }
                            if (*x - rect.x).abs() < 0.6 && (*y - rect.y).abs() < 0.6
                                && (*w - rect.width).abs() < 0.6)
                        })
                        .unwrap_or_else(|| panic!("{at}: {key} paints its fill"));
                    let beside = painted_backdrop_at(
                        &prims,
                        index,
                        rect.x - 1.0,
                        rect.y + rect.height / 2.0,
                    );
                    assert_eq!(beside, roles.elevated, "{at}: {key} stands on the card");
                    let DrawPrim::Panel { fill, .. } = prims[index] else {
                        unreachable!()
                    };
                    let fill = over(fill, beside);
                    let rim = prims
                        .iter()
                        .find_map(|prim| match prim {
                            DrawPrim::Stroke { x, y, color, .. }
                                if (*x - rect.x - 0.5).abs() < 0.6
                                    && (*y - rect.y - 0.5).abs() < 0.6 =>
                            {
                                Some(*color)
                            }
                            _ => None,
                        })
                        .unwrap_or_else(|| panic!("{at}: {key} paints its edge"));
                    let edge = contrast_ratio(over(rim, beside), beside);
                    assert!(edge >= 3.0, "{at}: {key}'s edge is {edge:.2}:1 on the card");
                    if selected {
                        selected_fill = Some(fill);
                        for (text, ratio) in painted_text_contrast(&compiled, &prims, key) {
                            assert!(ratio >= 4.5, "{at}: {key} paints {text:?} at {ratio:.2}:1");
                        }
                    } else {
                        resting_fill = Some(fill);
                    }
                }
                let (Some(resting), Some(selected)) = (resting_fill, selected_fill) else {
                    panic!("{at}: a resting chip and a selected one");
                };
                let step = contrast_ratio(resting, selected);
                assert!(
                    step >= 3.0,
                    "{at}: a selected chip is {step:.2}:1 from a resting one"
                );
            }
        }
    }
}

#[test]
fn a_copy_that_cannot_update_offers_no_live_update_button() {
    if !cfg!(target_os = "macos") {
        return;
    }
    let mut status = update_status(false);
    status.installable = false;
    let update = UpdateState::from_status(1, "0.1.0", Some(&status), false)
        .with_install_posture(Some(aterm_update::which_copy::InstallPosture::NotABundle));
    let (mut runtime, instance, view) = setup_with_update(update);
    go_to_route(&mut runtime, instance, view, SettingsRoute::SoftwareUpdate);
    let mut subtitles = BTreeSet::new();
    for (width, height) in [(1_200.0, 820.0), (738.0, 420.0), (560.0, 336.0)] {
        let at = format!("{width}x{height}");
        let cx = view_cx_at(width, height);
        let mut button = None;
        let mut caption = None;
        let mut switch = None;
        each_screen(&mut runtime, instance, view, &cx, |compiled, _| {
            compiled.validate_parity().unwrap();
            if let Some(node) = compiled.semantic(&UiKey::new("updates/install-now")) {
                button.get_or_insert(node.clone());
            }
            if let Some(hero) = compiled.semantic(&UiKey::new("updates/hero")) {
                assert!(!hero.label.contains(".."), "{at}: {:?}", hero.label);
            }
            assert!(
                compiled
                    .semantics
                    .iter()
                    .all(|node| !node.key.as_str().starts_with("updates/release-notes")),
                "{at}: no release notes are coming, so no card for them"
            );
            if let Some(subtitle) = compiled
                .semantics
                .iter()
                .find(|node| node.key.as_str().starts_with("settings/page-subtitle/"))
            {
                subtitles.insert(subtitle.label.clone());
            }
            if let Some(node) = compiled.semantic(&UiKey::new("updates/automatic/caption")) {
                caption.get_or_insert(node.label.clone());
            }
            if let Some(node) = compiled.semantic(&UiKey::new(format!(
                "settings/control/{}",
                prefs::EDIT_UPDATE_ENABLED
            ))) {
                switch.get_or_insert(node.label.clone());
            }
        });
        let button = button.unwrap_or_else(|| panic!("{at}: the action is drawn"));
        assert!(
            button.state.as_ref().is_some_and(|state| !state.enabled),
            "{at}: greyed"
        );
        assert_eq!(
            button.description.as_deref(),
            Some(UPDATE_CANT_INSTALL),
            "{at}: and says why"
        );
        assert!(
            button.rect.width < 220.0,
            "{at}: a button's width, not the card's: {:?}",
            button.rect
        );
        if let Some(caption) = caption {
            assert_eq!(
                caption, "These switches take effect in an installed copy of aterm.",
                "{at}"
            );
        }
        assert!(
            switch.is_some_and(|label| label.contains("can\u{2019}t update itself")),
            "{at}: the switch says it does nothing here"
        );
    }
    assert_eq!(
        subtitles.len(),
        1,
        "one subtitle at every width: {subtitles:?}"
    );
    assert!(
        !subtitles
            .iter()
            .any(|subtitle| subtitle.contains("Update now")),
        "{subtitles:?}"
    );

    let pressed = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("updates/install-now"),
                value: None,
            }),
        )
        .unwrap();
    assert!(
        pressed
            .effects
            .iter()
            .all(|effect| !matches!(effect, AppEffect::Update { .. })),
        "no check is sent from a copy that never starts one"
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert_eq!(state.feedback.as_deref(), Some(UPDATE_CANT_INSTALL));
    let check = runtime
        .commands(instance, view)
        .unwrap()
        .into_iter()
        .find(|command| command.id.as_str() == "updates/check")
        .expect("the palette offers it on this route");
    assert!(!check.enabled, "and greys it with the button");
}

#[test]
fn a_filter_that_matches_nothing_says_so_and_copies_nothing() {
    let (mut runtime, instance, view) = setup_with_these_messages(sample_messages());
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/warn",
    );
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/tag/update",
    );
    for (width, height) in [(1_200.0, 820.0), (738.0, 420.0), (474.0, 572.0)] {
        let at = format!("{width}x{height}");
        let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(width, height));
        compiled.validate_parity().unwrap();
        assert!(message_rows(&compiled).is_empty(), "{at}");
        assert_eq!(
            compiled
                .semantic(&UiKey::new("settings/messages/no-match"))
                .map(|node| node.label.as_str()),
            Some(aterm_messages::page::NO_MATCH),
            "{at}"
        );
        assert!(
            compiled
                .hits
                .iter()
                .any(|hit| hit.key.as_str() == MESSAGES_SHOW_ALL),
            "{at}: Show All is pressable"
        );
        assert!(
            compiled
                .semantic(&UiKey::new(MESSAGES_COPY_ALL))
                .and_then(|node| node.state.as_ref())
                .is_some_and(|state| !state.enabled),
            "{at}: nothing shown, nothing to copy"
        );
    }
    let copy = runtime
        .commands(instance, view)
        .unwrap()
        .into_iter()
        .find(|command| command.id.as_str() == MESSAGES_COPY_ALL)
        .expect("the palette offers it on this route");
    assert!(!copy.enabled);
    let pressed = messages_action(&mut runtime, instance, view, MESSAGES_COPY_ALL);
    assert!(
        pressed
            .iter()
            .all(|effect| !matches!(effect, AppEffect::Clipboard { .. })),
        "a press copies nothing: {pressed:?}"
    );

    messages_action(&mut runtime, instance, view, MESSAGES_SHOW_ALL);
    assert!(messages_view_state(&runtime, view).messages_filter.is_all());
    let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_200.0, 820.0));
    assert!(!message_rows(&compiled).is_empty(), "every message is back");
    assert!(
        compiled
            .semantic(&UiKey::new("settings/messages/no-match"))
            .is_none()
    );
}

#[test]
fn about_names_its_site_once_and_the_byline_is_not_a_link() {
    let (mut runtime, instance, view) = setup();
    go_to_route(&mut runtime, instance, view, SettingsRoute::About);
    for (width, height) in [(1_200.0, 820.0), (738.0, 420.0)] {
        let at = format!("{width}x{height}");
        let cx = view_cx_at(width, height);
        let mut bylines = 0;
        each_screen(&mut runtime, instance, view, &cx, |compiled, _| {
            assert!(
                compiled
                    .semantics
                    .iter()
                    .all(|node| !node.key.as_str().starts_with("about/support")),
                "{at}: no Project card"
            );
            if let Some(byline) = compiled
                .paint
                .iter()
                .find(|node| !node.peek && node.key.as_str() == "about/byline")
            {
                bylines += 1;
                assert!(
                    matches!(&byline.content, UiContent::Text(spec) if spec.style == StyleRef::Quiet),
                    "{at}: the byline is quiet text, not link-coloured"
                );
                assert!(
                    compiled
                        .semantic(&UiKey::new("about/byline"))
                        .is_some_and(|node| node.action.is_none()),
                    "{at}"
                );
            }
        });
        assert!(bylines > 0, "{at}: the byline is painted");
    }
}

fn top_of_page(runtime: &mut NativeRuntime, view: crate::native_app::ViewId) {
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!();
    };
    state.scroll_page_to(0);
    state.page_reveal = None;
}

#[test]
fn the_about_hero_names_its_author_and_the_card_lists_what_it_cannot() {
    let full = format!(
        "{} \u{00b7} {}",
        crate::build_info::AUTHOR_COMPANY_BYLINE,
        aterm_types::identity::SITE
    );
    let provenance = |runtime: &mut NativeRuntime, instance, view, width: f32, height: f32| {
        let mut rows = BTreeSet::new();
        each_screen(
            runtime,
            instance,
            view,
            &view_cx_at(width, height),
            |compiled, _| {
                for fact in ["author", "company", "site", "tagline"] {
                    if compiled
                        .semantic(&UiKey::new(format!("about/provenance/row/{fact}")))
                        .is_some()
                    {
                        rows.insert(fact);
                    }
                }
            },
        );
        rows
    };
    let (mut runtime, instance, view) = setup();
    go_to_route(&mut runtime, instance, view, SettingsRoute::About);
    for (width, height, short) in [
        (738.0, 420.0, false),
        (584.0, 350.0, false),
        (584.0, 260.0, true),
    ] {
        let at = format!("{width}x{height}");
        top_of_page(&mut runtime, view);
        let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(width, height));
        assert_eq!(
            compiled
                .semantic(&UiKey::new("about/compact-identity"))
                .is_some(),
            short,
            "{at}: the short hero exactly where the full one, buttons and all, does \
             not fit the list's room"
        );
        let hero = compiled
            .semantic(&UiKey::new("about/hero"))
            .unwrap_or_else(|| panic!("{at}: the hero"))
            .rect;
        let copy = compiled
            .semantic(&UiKey::new("about/copy-build-info"))
            .unwrap_or_else(|| panic!("{at}: Copy Build Information"))
            .rect;
        assert!(
            copy.bottom() <= hero.bottom() + 0.5,
            "{at}: the hero holds its buttons: {copy:?} in {hero:?}"
        );
        let byline = compiled
            .semantic(&UiKey::new("about/byline"))
            .unwrap_or_else(|| panic!("{at}: the byline is on the first screen"));
        assert_eq!(byline.label, full, "{at}");
        let audit = compiled
            .text_fit_audit_line(&UiKey::new("about/byline"))
            .expect("the byline is painted");
        assert!(audit.contains(" overflow=false "), "{at}: {audit}");
        assert!(
            provenance(&mut runtime, instance, view, width, height).is_empty(),
            "{at}: the card repeats nothing the hero paints"
        );
    }
    let rows = provenance(&mut runtime, instance, view, 286.5, 558.0);
    assert_eq!(
        rows.into_iter().collect::<Vec<_>>(),
        vec!["site"],
        "286.5x558: the site the byline cannot hold"
    );
    at_each_text_scale(&[2.0], "About at the window floor", |_| {
        let (mut runtime, instance, view) = setup();
        go_to_route(&mut runtime, instance, view, SettingsRoute::About);
        let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(164.0, 558.0));
        assert!(compiled.semantic(&UiKey::new("about/byline")).is_none());
        let rows = provenance(&mut runtime, instance, view, 164.0, 558.0);
        for fact in ["author", "company", "site"] {
            assert!(
                rows.contains(fact),
                "164x558 at 2x: {fact} is listed: {rows:?}"
            );
        }
    });
}

#[test]
fn the_about_hero_wraps_its_tagline_and_measures_its_labels() {
    at_each_text_scale(&[1.0, 1.5, 2.0], "About hero wording", |scale| {
        let (mut runtime, instance, view) = setup();
        go_to_route(&mut runtime, instance, view, SettingsRoute::About);
        for width in [240.0_f32, 320.0, 438.0, 600.0, 900.0] {
            let at = format!("{width}x558 at {scale}x");
            top_of_page(&mut runtime, view);
            let compiled =
                compile_settings_view(&runtime, instance, view, &view_cx_at(width, 558.0));
            let lines = compiled
                .paint
                .iter()
                .filter(|node| node.key.as_str().starts_with("about/tagline/line-"))
                .collect::<Vec<_>>();
            let column = compiled
                .paint
                .iter()
                .find(|node| node.key.as_str() == "about/wordmark")
                .map(|node| node.rect.width)
                .expect("the wordmark");
            let (px, _) = crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Plain);
            let widest = crate::build_info::TAGLINE
                .split_whitespace()
                .map(|word| crate::tray_raster::ui_text_width(word, px))
                .fold(0.0_f32, f32::max);
            if lines.is_empty() {
                assert!(
                    widest > column,
                    "{at}: the tagline is painted where its words fit"
                );
                let mut listed = false;
                each_screen(
                    &mut runtime,
                    instance,
                    view,
                    &view_cx_at(width, 558.0),
                    |compiled, _| {
                        listed |= compiled
                            .semantic(&UiKey::new("about/provenance/row/tagline"))
                            .is_some();
                    },
                );
                assert!(listed, "{at}: the card lists the tagline the hero cannot");
                continue;
            }
            assert!(
                lines.iter().all(|line| widest <= line.rect.width + 0.01),
                "{at}: no word is broken"
            );
            let joined = lines
                .iter()
                .filter_map(|node| match &node.content {
                    UiContent::Text(text) => Some(text.text.trim().to_string()),
                    _ => None,
                })
                .collect::<Vec<_>>()
                .join(" ");
            assert_eq!(
                joined,
                crate::build_info::TAGLINE,
                "{at}: whole words, in order"
            );
            for line in &lines {
                let audit = compiled
                    .text_fit_audit_line(&line.key)
                    .expect("each tagline line is audited");
                assert!(audit.contains(" overflow=false "), "{at}: {audit}");
            }
            for key in ["about/copy-build-info", "about/open-site"] {
                let node = compiled
                    .paint
                    .iter()
                    .find(|node| node.key.as_str() == key)
                    .unwrap_or_else(|| panic!("{at}: {key}"));
                let UiContent::Button(control) = &node.content else {
                    panic!("{at}: {key} is a button");
                };
                let painted = control
                    .spec
                    .visual_label
                    .clone()
                    .unwrap_or_else(|| control.spec.label.clone());
                assert!(
                    control.spec.label.contains(&painted),
                    "{at}: {key} paints {painted:?}, contained in its name {:?}",
                    control.spec.label
                );
            }
        }
    });
}

#[test]
fn a_copy_without_its_package_tool_does_not_contradict_itself() {
    let (mut runtime, instance, view) = setup();
    assert!(runtime.replace_settings_packages(missing_tool_packages_state(), 2));
    go_to_route(&mut runtime, instance, view, SettingsRoute::Packages);
    let mut words = String::new();
    each_screen(
        &mut runtime,
        instance,
        view,
        &view_cx_at(1_200.0, 820.0),
        |compiled, _| {
            for node in &compiled.semantics {
                if node.key.as_str().starts_with("packages/") {
                    words.push_str(&node.label);
                    words.push('\n');
                }
                if [
                    "packages/check",
                    "packages/install-default",
                    "packages/uninstall-all",
                ]
                .contains(&node.key.as_str())
                {
                    assert!(node.state.as_ref().is_some_and(|state| !state.enabled));
                }
                if node.key.as_str().starts_with("settings/control/") {
                    assert!(
                        node.label.contains("no effect") && !node.label.contains("Applies"),
                        "{}: {}",
                        node.key.as_str(),
                        node.label
                    );
                }
            }
        },
    );
    assert!(words.contains("Package tool missing"), "{words}");
    assert!(
        words.contains(crate::packages_screen::PACKAGE_TOOL_MISSING_DETAIL),
        "{words}"
    );
    for promise in [
        "still works",
        "always works",
        "works either way",
        "Signed updates",
        "take effect at once",
    ] {
        assert!(!words.contains(promise), "{promise:?} in {words}");
    }
    assert!(
        words.contains("Unavailable in this copy of aterm"),
        "{words}"
    );
}

